local config = {
  ui_story_5024_50240101_1_dialog_content = "Ibu.",
  ui_story_5024_50240101_2_dialog_content = "Ibu.",
  ui_story_5024_50240101_3_dialog_content = "Ibu…",
  ui_story_5024_50240101_4_dialog_content = "Siapa itu?",
  ui_story_5024_50240101_5_dialog_content = "Oh, kamu rupanya, Sayang. Sudah berapa lama kamu berdiri di situ?",
  ui_story_5024_50240101_6_dialog_content = "Belum lama. Ibu sedang membaca?",
  ui_story_5024_50240101_7_dialog_content = "Ah… Tidak. Ibu hanya sedang…",
  ui_story_5024_50240101_8_dialog_content = "Itu buku opini… Apa isinya?",
  ui_story_5024_50240101_9_dialog_content = "<size=45>Jangan pegang!</size>",
  ui_story_5024_50240101_10_dialog_content = "Ibu…",
  ui_story_5024_50240101_11_dialog_content = "Maafkan Ibu! Ibu tak bermaksud membuatmu takut…",
  ui_story_5024_50240101_12_dialog_content = "Hanya saja, kamu tak boleh membacanya… Tak seorang pun boleh.",
  ui_story_5024_50240101_13_dialog_content = "Buku apa itu…?",
  ui_story_5024_50240101_14_dialog_content = "Lupakan saja. Kamu ke sini mau mengatakan sesuatu, 'kan? Apa itu?",
  ui_story_5024_50240101_15_dialog_content = "Iya. Ibu, sepertinya sikuku lecet.",
  ui_story_5024_50240101_16_dialog_content = "Oh, ya? Coba Ibu lihat.",
  ui_story_5024_50240101_17_dialog_content = "Hmm…",
  ui_story_5024_50240101_18_dialog_content = "Lukanya besar… Sakit, tidak?",
  ui_story_5024_50240101_19_dialog_content = "Sakit!",
  ui_story_5024_50240101_20_dialog_content = "Darahnya mengucur… Lukanya harus dijahit.",
  ui_story_5024_50240101_21_dialog_content = "Sana, carilah kakakmu.",
  ui_story_5024_50240101_22_dialog_content = "Ibu tak mau menjahit lukaku?",
  ui_story_5024_50240101_23_dialog_content = "Ibu lebih pintar menjahit luka…",
  ui_story_5024_50240101_24_dialog_content = "Ada hal penting yang harus Ibu lakukan sekarang… Sangat penting.",
  ui_story_5024_50240101_25_dialog_content = "Jangan nakal, ya. Mintalah kakakmu untuk menjahit lukamu itu.",
  ui_story_5024_50240101_26_dialog_content = "…",
  ui_story_5024_50240101_27_dialog_content = "<size=42>Eh! Sini! Ibu memanggilmu!</size>",
  ui_story_5024_50240101_28_dialog_content = "Ya.",
  ui_story_5024_50240101_29_dialog_content = "Ada apa, Bu?",
  ui_story_5024_50240101_30_dialog_content = "Siku adikmu terluka. Lukanya harus dijahit. Kamu mau bantu adikmu, 'kan?",
  ui_story_5024_50240101_31_dialog_content = "Ya.",
  ui_story_5024_50240101_32_dialog_content = "Aduh… Pelan-pelan, dong… Jangan sampai terasa sakit!",
  ui_story_5024_50240101_33_dialog_content = "Sayang, kalian harus belajar untuk menjaga satu sama lain.",
  ui_story_5024_50240101_34_dialog_content = "Dunia ini bukan tempat yang cocok untuk kita.",
  ui_story_5024_50240101_35_dialog_content = "Tak ada orang lain yang ingin melihat kita hidup, kecuali kita sendiri.",
  ui_story_5024_50240101_36_dialog_content = "Ibu…",
  ui_story_5024_50240101_37_dialog_content = "Sebagai kakak, kamu harus menjaga adikmu. Paham? Dia lebih lemah daripada dirimu. Dia juga mudah jatuh sakit dan terluka.",
  ui_story_5024_50240101_38_dialog_content = "Kamu sendiri tak akan mengalaminya, tapi Ibu sudah mengajarimu cara mengatasinya, 'kan?",
  ui_story_5024_50240101_39_dialog_content = "Ya, Bu.",
  ui_story_5024_50240101_40_dialog_content = "Nah, kamu, kamu juga harus jaga kakakmu. Jangan lupa gulung senar kakakmu setiap hari, ya.",
  ui_story_5024_50240101_41_dialog_content = "Ingat, kamu tak boleh meninggalkannya sendirian setiap hari.",
  ui_story_5024_50240101_42_dialog_content = "Kakak sudah bisa menggulung senarnya sendiri. Dia tak butuh aku!",
  ui_story_5024_50240101_43_dialog_content = "<size=33>Tak ada yang butuh aku…</size>",
  ui_story_5024_50240101_44_dialog_content = "Ibu, Ibu mau pergi lagi?",
  ui_story_5024_50240101_45_dialog_content = "Hah?",
  ui_story_5024_50240101_46_dialog_content = "…",
  ui_story_5024_50240101_47_dialog_content = "Ya, Ibu harus pergi.",
  ui_story_5024_50240101_48_dialog_content = "Ibu harus menghadiri \"<color=#FFB400>pertunjukan</color>\" yang sangat penting.",
  ui_story_5024_50240101_49_dialog_content = "Ibu harus memperbaiki kesalahan yang dulu pernah Ibu lakukan…",
  ui_story_5024_50240101_50_dialog_content = "Setidaknya, Ibu harus berusaha… Mungkin inilah satu-satunya cara…",
  ui_story_5024_50240101_51_dialog_content = "Kesalahan di masa lalu?",
  ui_story_5024_50240101_52_dialog_content = "Kalian… Sudah waktunya kalian tidur, Sayang.",
  ui_story_5024_50240101_53_dialog_content = "Namun, sekarang kan masih…",
  ui_story_5024_50240101_54_dialog_content = "Sana, tidurlah. Saatnya mendengarkan dongeng pengantar tidur.",
  ui_story_5024_50240101_55_dialog_content = "Lenore dan May, kalian anak-anakku yang manis.",
  ui_story_5024_50240101_56_dialog_content = "Semoga kalian mimpi indah.",
  ui_story_5024_50240101_57_dialog_content = "<color=#e8d9bb>\"Bangunlah… Bangunlah…\"</color>",
  ui_story_5024_50240101_58_dialog_content = "<color=#e8d9bb>\"Bangun rumah yang indah.\"</color>",
  ui_story_5024_50240101_59_dialog_content = "<color=#e8d9bb>\"Bukan untuk Jenderal atau Tuan…\"</color>",
  ui_story_5024_50240101_60_dialog_content = "<color=#e8d9bb>\"Namun untuk si anjing tua baik yang mengantuk…\"</color>",
  ui_story_5024_50240101_61_dialog_content = "<color=#e8d9bb>\"Tertidur di samping perapian.\"</color>",
  ui_story_5024_50240101_62_dialog_content = "<color=#e8d9bb>Lumopolis Prison</color>",
  ui_story_5024_50240101_63_dialog_content = "Lagi-lagi kau? Sudah berapa kali kau ke sini?",
  ui_story_5024_50240101_64_dialog_content = "Sudah kubilang kan, kau tidak akan bisa lewat semudah itu.",
  ui_story_5024_50240101_65_dialog_content = "<color=#FFB400>Adikku</color> hilang…",
  ui_story_5024_50240101_66_dialog_content = "Apa kaulihat adikku?",
  ui_story_5024_50240101_67_dialog_content = "Tubuhnya kira-kira setinggi ini, rambutnya putih. Rambutnya dikucir dengan ikat rambut berbentuk pita berhias kubus.",
  ui_story_5024_50240101_68_dialog_content = "Dia hilang… Dia tak ada… Dia tak ada…",
  ui_story_5024_50240101_69_dialog_content = "Aku dengar, tahu! Tak usah mengulanginya terus!",
  ui_story_5024_50240101_70_dialog_content = "Pengumuman orang hilang sudah disebarkan. Semua penjaga kota sedang mencarinya. Apa lagi maumu?",
  ui_story_5024_50240101_71_dialog_content = "Bisa tidak sih kau tenang sedikit dan bersabar?",
  ui_story_5024_50240101_72_dialog_content = "Tak ada gunanya kau mengganggu para penghuni dan memaksa mereka memberitahukan hal yang tak mereka ketahui!",
  ui_story_5024_50240101_73_dialog_content = "Bisa-bisa malah kau ditangkap!",
  ui_story_5024_50240101_74_dialog_content = "Namun… adikku hilang…",
  ui_story_5024_50240101_75_dialog_content = "Aku tak bisa duduk diam dan menunggu saja… Aku harus berbuat sesuatu…",
  ui_story_5024_50240101_76_dialog_content = "Sekarang ini, kau hanya bisa menunggu.",
  ui_story_5024_50240101_77_dialog_content = "Dengarkan kata-kataku dan tenanglah sedikit, ya?",
  ui_story_5024_50240101_78_dialog_content = "<color=#e8d9bb>Dua jam kemudian…</color>",
  ui_story_5024_50240101_79_dialog_content = "Aku tak punya pilihan lagi. Terlalu banyak orang mengeluh tentangnya. Aku tak bisa membiarkan dia terus di sana.",
  ui_story_5024_50240101_80_dialog_content = "Aku tahu dia khawatir dan panik, tapi…",
  ui_story_5024_50240101_81_dialog_content = "Nah, bagaimana kalau kaulihat sendiri saja?",
  ui_story_5024_50240101_82_dialog_content = "Jadi? Kau sudah menemukan adikku?",
  ui_story_5024_50240101_83_dialog_content = "Kau… Tunggu!",
  ui_story_5024_50240101_84_dialog_content = "Apa sudah ada kabar tentangnya!?",
  ui_story_5024_50240101_85_dialog_content = "Aku tak tahu apa-apa, tapi kedua orang ini kemari untuk menemuimu.",
  ui_story_5024_50240101_86_dialog_content = "Aku tak menyangka ternyata kau kenal orang yang asal-usulnya tak jelas seperti dia ini, Guardian Captain.",
  ui_story_5024_50240101_87_dialog_content = "Dulu dia tinggal di Undercity terbengkalai. Aku punya urusan dengan hal yang menyebabkan dia ada di sini.",
  ui_story_5024_50240101_89_dialog_content = "Valencia, kau baik-baik saja?",
  ui_story_5024_50240101_90_dialog_content = "Kami sudah dengar tentangmu…",
  ui_story_5024_50240101_91_dialog_content = "Carleen, PlayerName…",
  ui_story_5024_50240101_92_dialog_content = "<color=#FFB400>Gretel</color>… Gretel hilang…",
  ui_story_5024_50240101_93_dialog_content = "Kami tahu. Jangan khawatir. Kau kan tahu Gretel itu seperti apa, dia kuat. Aku yakin dia pasti baik-baik saja.",
  ui_story_5024_50240101_94_dialog_content = "Sebentar, kau seorang Caelestite… Kau bisa melihat hal-hal yang tak bisa kulihat…",
  ui_story_5024_50240101_95_dialog_content = "Maukah kau membantu? Kau mau membantuku, 'kan?",
  ui_story_5024_50240101_96_dialog_content = "Eh…",
  ui_story_5024_50240101_97_dialog_content = "Valencia, memang untuk itulah kami kemari.",
  ui_story_5024_50240101_98_dialog_content = "Ayo kita mengobrol. Akan lebih mudah kalau kauceritakan semuanya dari awal.",
  ui_story_5024_50240101_101_dialog_content = "Aku… aku tak tahu harus mulai dari mana.",
  ui_story_5024_50240101_102_dialog_content = "Informasi apa pun bisa jadi berguna. Pasti ada banyak hal yang ingin kauceritakan tentang Gretel.",
  ui_story_5024_50240101_103_dialog_content = "Gretel…",
  ui_story_5024_50240101_104_dialog_content = "Dari awal saja, ya.",
  ui_story_5024_50240101_105_dialog_content = "Setelah meninggalkan kota, kami tinggal di Umbraton untuk sementara, tapi pada akhirnya kami memutuskan tinggal di Lumopolis karena di sana lebih tenang.",
  ui_story_5024_50240101_106_dialog_content = "Sementara kami masih berusaha membiasakan diri dengan kehidupan di sana, Gretel jatuh hati dengan lagu dan drama untuk anak-anak.",
  ui_story_5024_50240101_107_dialog_content = "Dia menghabiskan banyak waktu untuk kedua hal itu.",
  ui_story_5024_50240101_108_dialog_content = "Dia membeli buku dongeng sampai memenuhi rak buku dan membacanya siang malam.",
  ui_story_5024_50240101_109_dialog_content = "Dia juga sering pergi ke teater untuk menyaksikan semua drama di sana satu per satu, tanpa lelah.",
  ui_story_5024_50240101_110_dialog_content = "Awalnya, aku senang melihatnya karena dia bisa melakukan hal-hal yang disukainya. Kukira itu bisa membantunya membiasakan diri dengan kehidupan baru kami.",
  ui_story_5024_50240101_111_dialog_content = "Namun, tak lama kemudian, dia jadi muak dengan semua itu…",
  ui_story_5024_50240101_112_dialog_content = "Dia merobek-robek koleksi bukunya. Katanya, dia muak dengan kisah-kisah kacangan semacam itu…",
  ui_story_5024_50240101_113_dialog_content = "…",
  ui_story_5024_50240101_114_dialog_content = "Sekitar seminggu lalu, tiba-tiba saja dia tampak gembira.",
  ui_story_5024_50240101_115_dialog_content = "Katanya, ada hal sangat penting yang harus dilakukannya.",
  ui_story_5024_50240101_116_dialog_content = "Dia berniat menonton suatu pertunjukan <color=#FFB400>yang tak ada duanya</color>.",
  ui_story_5024_50240101_117_dialog_content = "Pertunjukan yang \"tak ada duanya\"?",
  ui_story_5024_50240101_118_dialog_content = "Berhari-hari dia berkemas, seakan-akan dia berniat menempuh perjalanan panjang.",
  ui_story_5024_50240101_119_dialog_content = "Kutanyakan ke mana tujuannya, tapi jawabannya selalu saja tak jelas.",
  ui_story_5024_50240101_120_dialog_content = "Lalu, pagi itu…",
  ui_story_5024_50240101_121_dialog_content = "Aku baru hendak mengajaknya sarapan, tapi dia sudah pergi…",
  ui_story_5024_50240101_122_dialog_content = "Dia tak berpamitan atau meninggalkan surat sama sekali. Dia pergi begitu saja.",
  ui_story_5024_50240101_123_dialog_content = "Lalu kau mulai mencarinya di jalanan?",
  ui_story_5024_50240101_124_dialog_content = "Benar… Pasti ada orang yang melihatnya menyeret kopernya menyusuri Lumopolis.",
  ui_story_5024_50240101_125_dialog_content = "Itu saja… Aku tak punya petunjuk lain lagi.",
  ui_story_5024_50240101_126_dialog_content = "Bagaimana menurutmu, PlayerName?",
  ui_story_5024_50240101_127_dialog_content = "Tak bisa mencari orang dengan cara ini. Lumopolis terlalu luas.",
  ui_story_5024_50240101_128_dialog_content = "Kita harus cari tahu dulu apa sebenarnya niat Gretel.",
  ui_story_5024_50240101_129_dialog_content = "Sebaiknya kita mulai dari pertunjukan yang \"tak ada duanya\" yang disebutkannya itu.",
  ui_story_5024_50240101_130_dialog_content = "Benar. Itu langkah pertama kita.",
  ui_story_5024_50240101_131_option_content = "Selidiki pertunjukan yang sedang digelar itu.",
  ui_story_5024_50240101_132_dialog_content = "Ada banyak sekali pertunjukan di Lumopolis. Kita juga tak bisa mengesampingkan kemungkinan bahwa mungkin saja dia pergi keluar Lumopolis.",
  ui_story_5024_50240101_133_dialog_content = "Kalau begini, tak akan ada kemajuan dalam pencarian kita.",
  ui_story_5024_50240101_134_option_content = "Cari petunjuk di rumah mereka",
  ui_story_5024_50240101_135_dialog_content = "Benar. Sebaiknya kita mulai dengan memeriksa rumah mereka.",
  ui_story_5024_50240101_136_dialog_content = "Valencia, boleh kami pinjam kunci rumahmu?",
  ui_story_5024_50240101_137_dialog_content = "Apa kau tak keberatan?",
  ui_story_5024_50240101_138_dialog_content = "Kami ingin memeriksa rumah kalian, siapa tahu di sana ada petunjuk tentang keberadaannya.",
  ui_story_5024_50240101_139_dialog_content = "Tak apa… Apa pun akan kulakukan demi Gretel…",
  ui_story_5024_50240101_140_dialog_content = "Huuhh…",
  ui_story_5024_50240101_141_dialog_content = "Desahmu panjang amat. Kenapa?",
  ui_story_5024_50240101_142_dialog_content = "Melihat Valencia dipenjara seperti itu… Aku benar-benar tak percaya ini nyata.",
  ui_story_5024_50240101_143_dialog_content = "Kau agak kelewat dramatis.",
  ui_story_5024_50240101_144_dialog_content = "Kalau kau tak berbuat tindak kejahatan apa pun, berarti tak ada yang perlu kaukhawatirkan.",
  ui_story_5024_50240101_145_dialog_content = "Berapa lama masa hukuman Valencia di penjara itu?",
  ui_story_5024_50240101_146_dialog_content = "Dakwaannya tak berat, kok. Besok dia sudah bebas.",
  ui_story_5024_50240101_147_dialog_content = "Namun… saat dia bebas, sebaiknya kita sudah punya petunjuk tentang keberadaan Gretel.",
  ui_story_5024_50240101_148_dialog_content = "Kondisi mental Valencia sedang tak stabil. Kalau terus berlarut-larut, aku khawatir akan dampaknya terhadap dirinya.",
  ui_story_5024_50240101_149_dialog_content = "Besok… Waktu berjalan cepat, padahal saat ini kita belum punya petunjuk apa pun.",
  ui_story_5024_50240101_150_dialog_content = "Karena itulah aku meminta bantuanmu.",
  ui_story_5024_50240101_151_dialog_content = "Kita butuh kemampuanmu sebagai Caelestite untuk mencari petunjuk di rumah Gretel.",
  ui_story_5024_50240101_152_dialog_content = "Jelas, dong. Tentu saja aku akan berusaha sebaik mungkin untuk membantu Gretel!",
  ui_story_5024_50240101_153_dialog_content = "<color=#e8d9bb>Kruuk…</color>",
  ui_story_5024_50240101_154_dialog_content = "Namun… seperti yang kaudengar sendiri, perutku keroncongan karena belum makan malam…",
  ui_story_5024_50240101_155_dialog_content = "Mungkin sebaiknya kita cari…",
  ui_story_5024_50240101_156_dialog_content = "…",
  ui_story_5024_50240101_157_dialog_content = "Kenapa tampangmu seperti itu?",
  ui_story_5024_50240101_158_dialog_content = "Ini penjara. Jangan bilang kau berniat minta makanan kepada mereka.",
  ui_story_5024_50240101_159_dialog_content = "Bukan itu maksudku!",
  ui_story_5024_50240101_160_dialog_content = "<color=#e8d9bb>Kriek…</color>",
  ui_story_5024_50240101_161_dialog_content = "Pintunya terbuka. Ini benar rumah Gretel.",
  ui_story_5024_50240101_162_dialog_content = "Tampaknya cukup semarak.",
  ui_story_5024_50240101_163_dialog_content = "Sepertinya mereka berhasil beradaptasi cukup baik dengan kehidupan baru mereka. Menyenangkan sekali.",
  ui_story_5024_50240101_164_dialog_content = "Bukan saatnya bersikap sentimental. Kita harus cari petunjuk tentang keberadaan Gretel.",
  ui_story_5024_50240101_165_dialog_content = "Di sana itu pasti kamarnya.",
  ui_story_5024_50240101_166_dialog_content = "Banyak sekali sobekan kertas… Rupanya dia benar-benar merobek buku-buku ceritanya.",
  ui_story_5024_50240101_167_dialog_content = "Di rak, ada beberapa buku yang masih utuh.",
  ui_story_5024_50240101_168_dialog_content = "Apa buku-buku itu lebih bermakna bagi Gretel dibandingkan buku-buku dongengnya…?",
  ui_story_5024_50240101_169_dialog_content = "Kita berpencar saja agar pencarian kita lebih menyeluruh. Carleen, periksa rak bukunya. Aku akan memeriksa sekeliling kamar ini.",
  ui_story_5024_50240101_170_dialog_content = "Baiklah. Kau punya kemampuan psikis. Pasti itu akan berguna untuk memeriksa tempat-tempat yang sulit dijangkau.",
  ui_story_5024_50240101_171_dialog_content = "<color=#e8d9bb>Beberapa lama kemudian…</color>",
  ui_story_5024_50240101_172_dialog_content = "Apa isi lemari ini, ya… Oh, camilan.",
  ui_story_5024_50240101_173_dialog_content = "Sebaiknya ingatkan Valencia agar tak melupakan camilan ini. Kalau tidak, nanti camilannya terlanjur kedaluwarsa.",
  ui_story_5024_50240101_174_dialog_content = "Kau sebenarnya mau mencari petunjuk atau bersih-bersih?",
  ui_story_5024_50240101_175_dialog_content = "Eh… Apa kau menemukan petunjuk di sana?",
  ui_story_5024_50240101_176_dialog_content = "Tidak juga… Buku-buku yang ditinggalkannya tampak aneh.",
  ui_story_5024_50240101_177_dialog_content = "Ini bukan buku, tapi buku kliping hias miliknya.",
  ui_story_5024_50240101_178_dialog_content = "Isinya kliping dari koran dan buku-buku tentang drama.",
  ui_story_5024_50240101_179_dialog_content = "Banyak sekali buku klipingnya? Berarti, di Lumopolis pasti ada banyak sekali drama…",
  ui_story_5024_50240101_180_dialog_content = "Jumlahnya sangat banyak karena dia mengumpulkan info tentang drama dari bertahun-tahun yang lalu.",
  ui_story_5024_50240101_181_dialog_content = "Ini kliping tentang drama dari lima dan sebelas tahun lalu…",
  ui_story_5024_50240101_182_dialog_content = "Kenapa harus mengumpulkan info dari bertahun-tahun yang lalu?",
  ui_story_5024_50240101_183_dialog_content = "Semua drama ini sudah selesai… Sekarang, informasinya sudah tak ada gunanya…",
  ui_story_5024_50240101_184_dialog_content = "Aku masih memikirkan apa yang dimaksud \"pertunjukan yang tak ada duanya\" oleh Gretel.",
  ui_story_5024_50240101_185_dialog_content = "Mungkin, dia menemukan pertunjukan itu dari buku kliping ini…",
  ui_story_5024_50240101_186_dialog_content = "Sebentar!",
  ui_story_5024_50240101_187_dialog_content = "Buku ini berlubang. Sepertinya ini suatu alat atau perkakas tertentu.",
  ui_story_5024_50240101_188_dialog_content = "Apa isinya?",
  ui_story_5024_50240101_189_dialog_content = "Sebuah amplop, tapi isinya sudah tak ada.",
  ui_story_5024_50240101_190_dialog_content = "\"Undangan: Pertunjukan Perdana <color=#FFB400>Anjing Baik yang Mengantuk</color>.\"",
  ui_story_5024_50240101_191_dialog_content = "Mungkin Gretel pergi untuk menonton drama ini!",
  ui_story_5024_50240101_192_dialog_content = "Namun, tak tertulis keterangan tanggal atau tempatnya di amplop ini…",
  ui_story_5024_50240101_193_dialog_content = "Nah, mungkin aku tahu soal itu.",
  ui_story_5024_50240101_194_dialog_content = "Apa? Di mana?",
  ui_story_5024_50240101_195_dialog_content = "Buku kliping di lantai itu. Itu bukan semata buku dongeng yang halamannya dirobek-robek.",
  ui_story_5024_50240101_196_dialog_content = "Lihat yang ini. Sepertinya ini rencana perjalanan Gretel, tapi dia merobek halamannya karena ada terlalu banyak kesalahan ejaan.",
  ui_story_5024_50240101_197_dialog_content = "\"09.00, mandi, berkemas\"",
  ui_story_5024_50240101_198_dialog_content = "\"11.00, naik kereta di area pusat bisnis\"",
  ui_story_5024_50240101_199_dialog_content = "\"30 mnt ke <color=#FFB400>Midnight Street</color>\"",
  ui_story_5024_50240101_199X_dialog_content = "\"Harus sampai paling lambat pukul <color=#FFB400>12.00</color>. Bukan masalah! :D\"",
  ui_story_5024_50240101_200_dialog_content = "Emotikonnya lucu…",
  ui_story_5024_50240101_201_dialog_content = "<color=#FFB400>Midnight Street</color>… Itu di Lower Lumopolis.",
  ui_story_5024_50240101_202_dialog_content = "Coba kita periksa di sana.",
  ui_story_5024_50240101_203_dialog_content = "Eh? Sekarang?",
  ui_story_5024_50240201_1_dialog_content = "<color=#e8d9bb>Tuut… Tuut…</color>",
  ui_story_5024_50240201_2_dialog_content = "(Suara apa itu?)",
  ui_story_5024_50240201_3_dialog_content = "(Sekarang tak terdengar lagi…)",
  ui_story_5024_50240201_4_dialog_content = "(Tak kusangka ada jalan sesepi ini di Lumopolis…)",
  ui_story_5024_50240201_5_dialog_content = "(Begitu sunyi, tak tampak seorang pun di balik jendela…)",
  ui_story_5024_50240201_6_dialog_content = "(Mungkin karena ini sudah sangat larut…)",
  ui_story_5024_50240201_7_dialog_content = "PlayerName, sedang apa kau? Ayo, cepat!",
  ui_story_5024_50240201_8_dialog_content = "Aku datang!",
  ui_story_5024_50240201_9_dialog_content = "Carleen, yakin ini tempatnya?",
  ui_story_5024_50240201_10_dialog_content = "Kita sudah berkali-kali memeriksa jalan ini. Tak ada teater di sini…",
  ui_story_5024_50240201_11_dialog_content = "Yah. Dari tadi aku berpikir…",
  ui_story_5024_50240201_12_dialog_content = "Mungkinkah ini hanya stasiun transfer menuju teater?",
  ui_story_5024_50240201_13_dialog_content = "Kita kan tak benar-benar membaca undangannya. Lagi pula, info dari potongan-potongan rencana perjalanan itu juga tak cukup…",
  ui_story_5024_50240201_14_dialog_content = "<color=#e8d9bb>Dong… Dong…</color>",
  ui_story_5024_50240201_15_dialog_content = "Loncengnya berbunyi. Sekarang pasti sudah tengah malam.",
  ui_story_5024_50240201_16_dialog_content = "Gretel bilang, \"harus sampai paling lambat pukul 12.00\". Mungkin itu adalah jam dimulainya drama itu?",
  ui_story_5024_50240201_17_dialog_content = "Sudah larut. Kita tak bisa terus mencari seperti anak ayam kehilangan induk.",
  ui_story_5024_50240201_18_dialog_content = "Coba kita cari sekali lagi. Siapa tahu ada bagian yang lewat dari perhatian kita.",
  ui_story_5024_50240201_19_dialog_content = "Kalau kita benar-benar tak bisa menemukan apa pun, besok aku akan minta bantuan dari para penjaga.",
  ui_story_5024_50240201_20_dialog_content = "Baiklah.",
  ui_story_5024_50240201_21_dialog_content = "Omong-omong, drama macam apa yang dimulai saat tengah malam?",
  ui_story_5024_50240201_22_dialog_content = "Selarut ini, aku tak yakin akan ada orang yang menontonnya…",
  ui_story_5024_50240201_23_dialog_content = "Kau benar. Ada yang aneh.",
  ui_story_5024_50240201_24_dialog_content = "Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240201_25_dialog_content = "Ada orang di sana? Padahal dari tadi kita tak melihat seorang pun.",
  ui_story_5024_50240201_26_dialog_content = "Ayo kita lihat.",
  ui_story_5024_50240201_27_dialog_content = "<color=#FFB400>Wonderland Theater</color>… Aku harus melihatnya… Harus!",
  ui_story_5024_50240201_28_dialog_content = "Tempatnya di jalan ini! Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240201_29_dialog_content = "Sudah kubilang, di sini tak ada tempat semacam itu!",
  ui_story_5024_50240201_30_dialog_content = "Jangan menggangguku lagi! Enyahlah!",
  ui_story_5024_50240201_31_dialog_content = "Orang itu juga kemari untuk menonton drama itu?",
  ui_story_5024_50240201_32_dialog_content = "<color=#FFB400>Wonderland Theater</color>… Aku ingat, sepertinya nama itu tertulis di buku kliping Gretel.",
  ui_story_5024_50240201_33_dialog_content = "Kalian tahu! Kalian tahu tentang Wonderland Theater!",
  ui_story_5024_50240201_34_dialog_content = "Kau…",
  ui_story_5024_50240201_35_dialog_content = "Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240201_36_dialog_content = "Maaf. Kami tak tahu apa pun!",
  ui_story_5024_50240201_37_dialog_content = "Tak tahu… Tak seorang pun tahu…",
  ui_story_5024_50240201_38_dialog_content = "Wonderland Theater… Aku harus melihatnya… Harus…",
  ui_story_5024_50240201_39_dialog_content = "Orang itu kenapa, sih… Agak menyeramkan…",
  ui_story_5024_50240201_40_dialog_content = "Penjaga, orang itu kenapa?",
  ui_story_5024_50240201_41_dialog_content = "Jangan menggangguku lagi! Enyahlah!",
  ui_story_5024_50240201_42_dialog_content = "Kau!",
  ui_story_5024_50240201_43_dialog_content = "Sudahlah. Ayo pergi, PlayerName.",
  ui_story_5024_50240201_44_dialog_content = "Ternyata ada penjaga yang tak mengenalimu, ya?",
  ui_story_5024_50240201_45_dialog_content = "Aku bukan orang yang harus dikenal oleh Lumo Guard.",
  ui_story_5024_50240201_46_dialog_content = "Mungkin, dia sekadar tak tertarik dengan kalangan bangsawan.",
  ui_story_5024_50240201_47_dialog_content = "Begitukah? Menurutku aneh…",
  ui_story_5024_50240201_48_dialog_content = "Memang, tapi prioritas kita adalah mencari Gretel sekaligus mencari petunjuk tentang pertunjukan drama itu.",
  ui_story_5024_50240201_49_dialog_content = "Ada orang lagi di sana. Biar kutanyai dia.",
  ui_story_5024_50240201_50_dialog_content = "Ya.",
  ui_story_5024_50240201_51_dialog_content = "Tunggu, Carleen!",
  ui_story_5024_50240201_52_dialog_content = "Hah? Ada apa?",
  ui_story_5024_50240201_53_dialog_content = "Tak usah menanyainya.",
  ui_story_5024_50240201_54_dialog_content = "Itu bukan orang. Itu <color=#FFB400>maneken</color>.",
  ui_story_5024_50240201_55_dialog_content = "!!!",
  ui_story_5024_50240201_56_dialog_content = "Kenapa maneken itu ada di jalanan!?",
  ui_story_5024_50240201_57_dialog_content = "Kita kan sudah cukup lama di sini. Bagaimana mungkin tadi kita tak melihatnya?",
  ui_story_5024_50240201_58_dialog_content = "Kita pergi saja… Aku merasakan firasat buruk tentang ini…",
  ui_story_5024_50240201_59_dialog_content = "<color=#e8d9bb>Tak… Tuk… Tak… Tuk…</color>",
  ui_story_5024_50240201_60_dialog_content = "(Ada yang aneh di sini.)",
  ui_story_5024_50240201_61_dialog_content = "(Mungkinkah ada sesuatu yang tersembunyi dan tak kasat mata?)",
  ui_story_5024_50240201_62_dialog_content = "(Coba kuperluas jangkauan kemampuan psikisku…)",
  ui_story_5024_50240201_63_dialog_content = "(Hah…?)",
  ui_story_5024_50240201_64_dialog_content = "(Kok aku tak bisa merasakan apa pun…?",
  ui_story_5024_50240201_65_dialog_content = "Kau baik-baik saja?",
  ui_story_5024_50240201_66_dialog_content = "Uh, ya…",
  ui_story_5024_50240201_67_dialog_content = "Aku hanya khawatir membayangkan Gretel berkeliaran sendirian di sekitar sini.",
  ui_story_5024_50240201_68_dialog_content = "Dia mencari hal yang sama dengan orang gila yang tadi itu, 'kan?",
  ui_story_5024_50240201_69_dialog_content = "Pertunjukan yang tak ada duanya di Wonderland Theater…",
  ui_story_5024_50240201_70_dialog_content = "Kaubilang kau sudah pernah membaca nama teater itu. Apa ada informasi lain tentangnya?",
  ui_story_5024_50240201_71_dialog_content = "Gretel menuliskan banyak sekali nama teater. Aku hanya membacanya sekilas.",
  ui_story_5024_50240201_72_dialog_content = "Aku hanya ingat bahwa teater itu sudah bertahun-tahun ditutup karena ada kecelakaan.",
  ui_story_5024_50240201_73_dialog_content = "Sudah ditutup?",
  ui_story_5024_50240201_74_dialog_content = "Kukira itu tak ada hubungannya dengan hal yang sedang kita selidiki, jadi aku tak membacanya lebih lanjut.",
  ui_story_5024_50240201_75_dialog_content = "Mestinya aku lebih cermat…",
  ui_story_5024_50240201_76_dialog_content = "Pertunjukan yang tak ada duanya, yang digelar pada tengah malam di Wonderland Theater yang sudah lama tutup…",
  ui_story_5024_50240201_77_dialog_content = "Mau bagaimana pun, ini…",
  ui_story_5024_50240201_78_dialog_content = "Tunggu.",
  ui_story_5024_50240201_79_dialog_content = "Entah kenapa, rasanya ada yang janggal, ya?",
  ui_story_5024_50240201_80_dialog_content = "Apa?",
  ui_story_5024_50240201_81_dialog_content = "Jangan bergerak. Diam saja.",
  ui_story_5024_50240201_82_dialog_content = "Oh…",
  ui_story_5024_50240201_83_dialog_content = "<color=#e8d9bb>Tak… Tuk… Tak… Tuk…</color>",
  ui_story_5024_50240201_84_dialog_content = "Aku dengar suara langkah kaki!",
  ui_story_5024_50240201_85_dialog_content = "Di sini…",
  ui_story_5024_50240201_86_dialog_content = "Eclipsite? Di area permukiman di Lumopolis ini?",
  ui_story_5024_50240201_87_dialog_content = "<anim type=Shake><size=45>Graaaah!!</size></anim>",
  ui_story_5024_50240201_88_dialog_content = "Carleen, awas!",
  ui_story_5024_50240202_1_dialog_content = "Eclipsite? Di sini? Tak masuk akal…",
  ui_story_5024_50240202_2_dialog_content = "Yah… Sekarang, situasi bukan hanya aneh, tapi juga sangat berbahaya!",
  ui_story_5024_50240202_3_dialog_content = "Bagaimana mungkin dia bisa masuk ke Lumopolis?",
  ui_story_5024_50240202_4_dialog_content = "Kita harus cari tahu! Jangan sampai Lumopolis terancam bahaya saat malam begini!",
  ui_story_5024_50240202_5_dialog_content = "Ada apa sebenarnya di jalan ini…",
  ui_story_5024_50240202_6_dialog_content = "Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240202_7_dialog_content = "Wonderland Theater… Aku harus melihatnya… Harus!",
  ui_story_5024_50240202_8_dialog_content = "?",
  ui_story_5024_50240202_9_dialog_content = "Lagi-lagi dia? Bagaimana…?",
  ui_story_5024_50240202_10_dialog_content = "Tempatnya di jalan ini! Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240202_11_dialog_content = "Sudah kubilang, di sini tak ada tempat semacam itu!",
  ui_story_5024_50240202_12_dialog_content = "Jangan menggangguku lagi! Enyahlah!",
  ui_story_5024_50240202_13_dialog_content = "Kita kembali ke tempat yang sama lagi?",
  ui_story_5024_50240202_14_dialog_content = "Mustahil… Dari tadi kan kita berjalan maju…",
  ui_story_5024_50240202_15_dialog_content = "…",
  ui_story_5024_50240202_16_dialog_content = "Mungkin tadi kita salah belok di tempat yang gelap.",
  ui_story_5024_50240202_17_dialog_content = "Tak usah pedulikan mereka. Ayo kita pergi.",
  ui_story_5024_50240202_18_dialog_content = "Benarkah kita salah belok…?",
  ui_story_5024_50240202_19_dialog_content = "Kedengarannya mereka mengulangi apa yang tadi mereka katakan tadi…",
  ui_story_5024_50240202_20_dialog_content = "Jalanan dan gang di area permukiman ini rumit. Tak usah malu kalau memang kita salah belok.",
  ui_story_5024_50240202_21_dialog_content = "Sekarang sudah gelap, dan kita baru saja menghadapi pertarungan sengit.",
  ui_story_5024_50240202_22_dialog_content = "Memangnya penjelasan apa lagi yang masuk akal…",
  ui_story_5024_50240202_23_dialog_content = "Hei!",
  ui_story_5024_50240202_24_dialog_content = "Woah!",
  ui_story_5024_50240202_25_dialog_content = "Maneken itu lagi…",
  ui_story_5024_50240202_26_dialog_content = "Memangnya tadi maneken itu ada di sini?",
  ui_story_5024_50240202_27_dialog_content = "Tidak… Dan posenya berbeda…",
  ui_story_5024_50240202_28_dialog_content = "Kalau begitu, pasti ada seseorang yang mengendalikannya!",
  ui_story_5024_50240202_29_dialog_content = "Aku tak tahu siapa dalangnya, tapi ini tak lucu.",
  ui_story_5024_50240202_30_dialog_content = "Ayo kita pergi!",
  ui_story_5024_50240202_31_dialog_content = "Mana yang sebaiknya kita selidiki lebih dulu?",
  ui_story_5024_50240202_32_dialog_content = "Gretel, Wonderland Theater, atau dari mana asal Eclipsite yang tadi itu?",
  ui_story_5024_50240202_33_dialog_content = "Entahlah…",
  ui_story_5024_50240202_34_dialog_content = "Dari sudut pandang keamanan, prioritasnya tentu saja mencari tahu asal Eclipsite itu.",
  ui_story_5024_50240202_35_dialog_content = "Tak terbayangkan betapa besarnya bahaya kalau ada Eclipsite berkeliaran di kota ini saat malam.",
  ui_story_5024_50240202_36_dialog_content = "Entah kenapa… Aku merasa semua peristiwa ini saling berhubungan.",
  ui_story_5024_50240202_37_dialog_content = "Kalau kita hanya fokus menyelidiki Eclipsite itu, bisa jadi kita akan melewatkan hal yang penting.",
  ui_story_5024_50240202_38_dialog_content = "Apa hubungan antara semua ini…?",
  ui_story_5024_50240202_39_dialog_content = "Omong-omong, aku lupa bertanya, apa kau merasakan sesuatu?",
  ui_story_5024_50240202_40_dialog_content = "Kebetulan sekali kau menanyakannya. Anehnya, aku tak merasakan apa pun.",
  ui_story_5024_50240202_41_dialog_content = "Maksudku, aku sama sekali tak merasakan apa pun.",
  ui_story_5024_50240202_42_dialog_content = "Bukan hanya petunjuk, tapi aku juga tak bisa merasakan ada seorang pun di sini…",
  ui_story_5024_50240202_43_dialog_content = "Apa? Kita kan ada di area permukiman…",
  ui_story_5024_50240202_44_dialog_content = "Apa mungkin itu karena mereka semua sudah tidur?",
  ui_story_5024_50240202_45_dialog_content = "Tidak. Kalaupun mereka sudah tidur, aku masih bisa merasakan kesadaran mereka.",
  ui_story_5024_50240202_46_dialog_content = "Atau, mungkin masalahnya ada pada diriku. Kemampuan psikisku memang kadang mengalami korsleting kalau kondisi fisikku sedang tak enak.",
  ui_story_5024_50240202_47_dialog_content = "Apa sebaiknya kuantar kau pulang saja?",
  ui_story_5024_50240202_48_dialog_content = "Maaf, aku mengajakmu pergi sampai selarut ini.",
  ui_story_5024_50240202_49_dialog_content = "Tak apa. Aku justru minta maaf karena tak bisa membantu…",
  ui_story_5024_50240202_50_dialog_content = "Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240202_51_dialog_content = "?",
  ui_story_5024_50240202_52_dialog_content = "Wonderland Theater… Aku harus melihatnya… Harus!",
  ui_story_5024_50240202_53_dialog_content = "Carleen, aku yakin kali ini kita tak salah belok…",
  ui_story_5024_50240202_54_dialog_content = "Ya… Aku juga.",
  ui_story_5024_50240202_55_dialog_content = "Lagi pula, kalau aku tak salah dengar, kata-katanya sama dengan yang tadi…",
  ui_story_5024_50240202_56_dialog_content = "Tempatnya di jalan ini! Tolong… Tolong, beri tahu aku…",
  ui_story_5024_50240202_57_dialog_content = "…",
  ui_story_5024_50240202_58_dialog_content = "Sudah kubilang, di sini tak ada tempat semacam itu!",
  ui_story_5024_50240202_59_dialog_content = "Jangan menggangguku lagi! Enyahlah!",
  ui_story_5024_50240202_60_dialog_content = "Semuanya persis sama… Apa aku bermimpi?",
  ui_story_5024_50240202_61_dialog_content = "Andai saja ini hanya mimpi…",
  ui_story_5024_50240202_62_dialog_content = "Rasanya seakan-akan kita terperangkap dalam lingkaran tanpa ujung.",
  ui_story_5024_50240202_63_dialog_content = "Kita terus kembali ke titik waktu dan tempat yang sama.",
  ui_story_5024_50240202_64_dialog_content = "Kalau begitu, berarti mestinya setelah ini kita akan melihat maneken itu…",
  ui_story_5024_50240202_65_dialog_content = "Benar. Aku sudah melihatnya.",
  ui_story_5024_50240202_66_dialog_content = "Lihat, 'kan? Lagi-lagi maneken itu.",
  ui_story_5024_50240202_67_dialog_content = "Kali ini, posenya berbeda lagi.",
  ui_story_5024_50240202_68_dialog_content = "Sepertinya dia memegang sesuatu. Itu <color=#FFB400>kertas</color> bukan, ya?",
  ui_story_5024_50240202_69_dialog_content = "Ambillah… Mungkin saja itu petunjuk.",
  ui_story_5024_50240202_70_dialog_content = "Kau benar.",
  ui_story_5024_50240202_71_dialog_content = "…",
  ui_story_5024_50240202_71X_dialog_content = "…",
  ui_story_5024_50240202_72_dialog_content = "Apa… Aku?",
  ui_story_5024_50240202_73_dialog_content = "Uh… Oh… Kukira kau bakal tertarik dengan kertas itu.",
  ui_story_5024_50240202_74_dialog_content = "Anu, tanganku agak dingin…",
  ui_story_5024_50240202_75_dialog_content = "Begitu rupanya… Baiklah. Biar kuambil.",
  ui_story_5024_50240202_76_dialog_content = "Biar kuambil…",
  ui_story_5024_50240202_77_dialog_content = "…",
  ui_story_5024_50240202_78_dialog_content = "(Jangan lihat manekennya. Fokus saja pada kertas di tangannya.)",
  ui_story_5024_50240202_79_dialog_content = "(Surat? Di sini agak gelap, aku tak bisa membacanya…)",
  ui_story_5024_50240202_80_dialog_content = "!!!",
  ui_story_5024_50240202_81_dialog_content = "PlayerName, dia memegang… <color=#FFB400>undangan</color> ke Wonderland Theater!",
  ui_story_5024_50240202_82_dialog_content = "Apa? Coba kulihat!",
  ui_story_5024_50240202_83_dialog_content = "Boleh saja, akan ku…",
  ui_story_5024_50240202_84_dialog_content = "Tidak.",
  ui_story_5024_50240202_85_dialog_content = "!!!",
  ui_story_5024_50240202_86_dialog_content = "Kau tidak boleh mencuri barang milik <color=#FFB400>Lenore</color>!",
  ui_story_5024_50240202_87_dialog_content = "Ahhhhh!",
  ui_story_5024_50240301_1_dialog_content = "Dia bisa bicara!",
  ui_story_5024_50240301_2_dialog_content = "Uh… manekennya bicara…",
  ui_story_5024_50240301_3_dialog_content = "PlayerName… Coba cari tahu, dia itu manusia atau bukan.",
  ui_story_5024_50240301_4_dialog_content = "Kalau bukan, aku akan menyerangnya…",
  ui_story_5024_50240301_5_dialog_content = "Jelas, dia bukan manusia!",
  ui_story_5024_50240301_6_dialog_content = "Namun, dia tak tampak seperti musuh.",
  ui_story_5024_50240301_7_dialog_content = "Menurut akal sehatku, maneken yang bisa bicara sudah cukup bisa dianggap musuh.",
  ui_story_5024_50240301_8_dialog_content = "Maaf. Lenore tidak bermaksud membuat kalian takut.",
  ui_story_5024_50240301_9_dialog_content = "Lenore biasanya tidak bicara di depan orang asing. Kata Ibu, tidak boleh.",
  ui_story_5024_50240301_10_dialog_content = "Namun, Lenore tidak bisa biarkan kalian mengambil surat ini.",
  ui_story_5024_50240301_11_dialog_content = "Ini penting untuk Lenore.",
  ui_story_5024_50240301_12_dialog_content = "Namamu… <color=#FFB400>Lenore</color>?",
  ui_story_5024_50240301_13_dialog_content = "Ya.",
  ui_story_5024_50240301_14_dialog_content = "Maneken yang bisa bicara?",
  ui_story_5024_50240301_15_dialog_content = "Lenore tidak tahu dia itu apa.",
  ui_story_5024_50240301_16_dialog_content = "Lenore anak Ibu. Hanya itu yang Lenore tahu.",
  ui_story_5024_50240301_17_dialog_content = "Carleen, yang dipegangnya itu… ada hubungannya dengan Wonderland Theater, 'kan?",
  ui_story_5024_50240301_18_dialog_content = "Ya. Aku melihat namanya tertulis di sana.",
  ui_story_5024_50240301_19_dialog_content = "Coba kita tanyai dia, mungkin saja dia tahu sesuatu.",
  ui_story_5024_50240301_20_dialog_content = "Bicara dengan maneken saat tengah malam…",
  ui_story_5024_50240301_21_dialog_content = "Kalau ini bukan mimpi, berarti aku sudah gila.",
  ui_story_5024_50240301_22_dialog_content = "Haha… Aku setuju…",
  ui_story_5024_50240301_23_dialog_content = "Lenore, yang kaupegang itu apa?",
  ui_story_5024_50240301_24_dialog_content = "Undangan.",
  ui_story_5024_50240301_25_dialog_content = "\"Pertunjukan Perdana <color=#FFB400>Anjing Baik yang Mengantuk</color>.\"",
  ui_story_5024_50240301_26_dialog_content = "Sama dengan undangan Gretel!",
  ui_story_5024_50240301_27_dialog_content = "Di Wonderland Theater, ya?",
  ui_story_5024_50240301_28_dialog_content = "Benar.",
  ui_story_5024_50240301_29_dialog_content = "Nah, di mana Wonderland Theater itu?",
  ui_story_5024_50240301_30_dialog_content = "Tidak yakin. Lenore berusaha mencarinya.",
  ui_story_5024_50240301_31_dialog_content = "Pasti ada di jalan ini.",
  ui_story_5024_50240301_32_dialog_content = "Sedari tadi kami juga mencarinya di jalan ini, tapi tak ketemu.",
  ui_story_5024_50240301_33_dialog_content = "Mungkin teaternya dulu ada di jalan ini?",
  ui_story_5024_50240301_34_dialog_content = "Namun, sekarang sudah tutup, seperti kata Carleen.",
  ui_story_5024_50240301_35_dialog_content = "Wonderland Theater tidak ada di Lumopolis pada masa kini.",
  ui_story_5024_50240301_36_dialog_content = "Namun, sebenarnya sekarang kita tidak berada di Lumopolis.",
  ui_story_5024_50240301_37_dialog_content = "Apa?!",
  ui_story_5024_50240301_38_dialog_content = "Kalian bisa lihat koran di kotak-kotak surat itu.",
  ui_story_5024_50240301_39_dialog_content = "Koran…",
  ui_story_5024_50240301_40_dialog_content = "\"Kabar gembira! Potongan Pajak untuk Semua Warga!\"",
  ui_story_5024_50240301_41_dialog_content = "Pemotongan pajak? Aku ingat, itu terjadi…",
  ui_story_5024_50240301_42_dialog_content = "Sudah kuduga. Itu peristiwa lima belas tahun lalu.",
  ui_story_5024_50240301_43_dialog_content = "Kenapa koran ini ada di dalam kotak surat ini…",
  ui_story_5024_50240301_44_dialog_content = "Yang ini juga! Edisi September dari tujuh belas tahun lalu…",
  ui_story_5024_50240301_45_dialog_content = "Ini juga, Edisi Maret dari tujuh belas tahun lalu…",
  ui_story_5024_50240301_46_dialog_content = "(Tujuh belas tahun lalu…)",
  ui_story_5024_50240301_47_dialog_content = "(Kalau yang dimaksud adalah tahun itu… Mestinya Eraveil juga diberitakan di koran ini…)",
  ui_story_5024_50240301_48_dialog_content = "(Apa sebaiknya kulihat saja?)",
  ui_story_5024_50240301_49_dialog_content = "(…)",
  ui_story_5024_50240301_50_dialog_content = "(Lupakan…)",
  ui_story_5024_50240301_51_dialog_content = "(Aku… aku agak takut membayangkan akan dikritik oleh orang luar.)",
  ui_story_5024_50240301_52_dialog_content = "(Fokus saja pada apa yang sedang kami lakukan… Ya, benar.)",
  ui_story_5024_50240301_53_dialog_content = "Koran lawas dari beberapa tahun lalu…",
  ui_story_5024_50240301_54_dialog_content = "Kalaupun ternyata kita memang kembali ke masa lalu, tetap saja ini tak masuk akal.",
  ui_story_5024_50240301_55_dialog_content = "Mungkin, waktu bukanlah kata yang tepat di sini.",
  ui_story_5024_50240301_56_dialog_content = "Coba kulihat yang ini…",
  ui_story_5024_50240301_57_dialog_content = "Ini dia. Wonderland Theater diberitakan di semua koran di sebelah sini!",
  ui_story_5024_50240301_58_dialog_content = "Lagi-lagi Wonderland Theater…?",
  ui_story_5024_50240301_59_dialog_content = "\"Edisi Maret: Pertunjukan Perdana Anjing Baik yang Mengantuk di Wonderland Theater, Enam Bulan Lagi\"",
  ui_story_5024_50240301_60_dialog_content = "\"Drama Dongeng Hebat yang Layak Dinanti\"",
  ui_story_5024_50240301_61_dialog_content = "Anjing Baik yang Mengantuk…",
  ui_story_5024_50240301_62_dialog_content = "\"Edisi Oktober: Kecelakaan di Pertunjukan Anjing Baik yang Mengantuk! Wonderland Theater Ditutup!\"",
  ui_story_5024_50240301_63_dialog_content = "Rupanya itulah sebabnya Wonderland Theater ditutup!",
  ui_story_5024_50240301_64_dialog_content = "Masih ada lagi.",
  ui_story_5024_50240301_65_dialog_content = "\"Semua staf yang terlibat dalam pertunjukan Anjing Baik yang Mengantuk tewas dalam kecelakaan itu. Akhir cerita pertunjukan ini akan selamanya menjadi misteri.\"",
  ui_story_5024_50240301_66_dialog_content = "Kecelakaannya parah sekali…",
  ui_story_5024_50240301_67_dialog_content = "Tewas saat baru saja tiba… Pantas saja Gretel menyebutnya pertunjukan yang tak ada duanya.",
  ui_story_5024_50240301_68_dialog_content = "Sebenarnya, apa yang terjadi?",
  ui_story_5024_50240301_69_dialog_content = "Tak disebutkan di sini. Bisa dibilang, ini hanya berita kecil.",
  ui_story_5024_50240301_70_dialog_content = "Lenore ingat pertunjukan itu.",
  ui_story_5024_50240301_71_dialog_content = "Hanya sekali itu Ibu mengajak Lenore pergi ke luar.",
  ui_story_5024_50240301_72_dialog_content = "Kau ada di sana saat itu? Di Wonderland Theater, tujuh belas tahun lalu?",
  ui_story_5024_50240301_73_dialog_content = "Ya, tapi waktu itu Lenore masih kecil. Tidak banyak yang bisa diingat.",
  ui_story_5024_50240301_74_dialog_content = "Hanya ingat Ibu menyuruh kami pergi ke pertunjukan itu bersama-sama.",
  ui_story_5024_50240301_75_dialog_content = "Namun, Lenore… sepertinya tidak mematuhi perintah Ibu.",
  ui_story_5024_50240301_76_dialog_content = "Lalu, terjadi suatu peristiwa mengerikan…",
  ui_story_5024_50240301_77_dialog_content = "Lenore tidak bisa mengingatnya.",
  ui_story_5024_50240301_78_dialog_content = "Sebentar. Waktu itu, kau masih kecil?",
  ui_story_5024_50240301_79_dialog_content = "Kukira maneken tak bisa bertumbuh besar…",
  ui_story_5024_50240301_80_dialog_content = "Mungkinkah sebenarnya kau ini manusia… Atau dulunya manusia?",
  ui_story_5024_50240301_81_dialog_content = "Lenore tidak tahu. Lenore tidak ingat.",
  ui_story_5024_50240301_82_dialog_content = "Oh, begitu…",
  ui_story_5024_50240301_83_dialog_content = "Aku juga menemukan laporan tentang Wonderland Theater di sini.",
  ui_story_5024_50240301_84_dialog_content = "Apa isinya?",
  ui_story_5024_50240301_85_dialog_content = "Hanya sepotong kalimat sederhana di bagian ujung.",
  ui_story_5024_50240301_86_dialog_content = "\"Wonderland Theater Dibangun Ulang, Kini Jadi Umbraton Scenic Restaurant\"",
  ui_story_5024_50240301_87_dialog_content = "Umbraton Scenic Restaurant? Aku baru saja melihatnya!",
  ui_story_5024_50240301_88_dialog_content = "Iya, aku juga.",
  ui_story_5024_50240301_89_dialog_content = "Ayo. Pasti ada lebih banyak petunjuk di sana!",
  ui_story_5024_50240301_90_dialog_content = "<color=#e8d9bb>*Kriek*</color>",
  ui_story_5024_50240301_91_dialog_content = "Permisi…",
  ui_story_5024_50240301_92_dialog_content = "Tak ada siapa-siapa di sini. Persis seperti dugaanku.",
  ui_story_5024_50240301_93_dialog_content = "Sudah larut, pasti sudah tutup.",
  ui_story_5024_50240301_94_dialog_content = "Permisi.",
  ui_story_5024_50240301_95_dialog_content = "Kau… Kau mengikuti kami…?",
  ui_story_5024_50240301_96_dialog_content = "Walau cara bicaramu memang wajar… tapi tetap saja agak seram…",
  ui_story_5024_50240301_97_dialog_content = "Lenore juga mencari Wonderland Theater, sama seperti kalian.",
  ui_story_5024_50240301_98_dialog_content = "Jadi, kenapa kau mau pergi ke Wonderland Theater?",
  ui_story_5024_50240301_99_dialog_content = "Mau melihat pertunjukan ulang Anjing Baik yang Mengantuk.",
  ui_story_5024_50240301_100_dialog_content = "Lenore harus mencari Ibu.",
  ui_story_5024_50240301_101_dialog_content = "Mencari Ibu?",
  ui_story_5024_50240301_102_dialog_content = "Ya. Ibu hilang sejak beberapa hari lalu.",
  ui_story_5024_50240301_103_dialog_content = "Dia pergi untuk melihat \"pertunjukan yang tak ada duanya\", \"gelaran ulang pertunjukan akbar\".",
  ui_story_5024_50240301_104_dialog_content = "Kurasa, yang dimaksudnya adalah Anjing Baik yang Mengantuk.",
  ui_story_5024_50240301_105_dialog_content = "Pertunjukan ulang itu dimulai setahun lalu…",
  ui_story_5024_50240301_106_dialog_content = "Lalu, bagaimana ceritanya undangan itu bisa sampai ke tanganmu?",
  ui_story_5024_50240301_107_dialog_content = "Undangannya muncul begitu saja.",
  ui_story_5024_50240301_108_dialog_content = "Apa?",
  ui_story_5024_50240301_109_dialog_content = "Persis di rumahku.",
  ui_story_5024_50240301_110_dialog_content = "Kebetulannya tidak wajar! Kau mengambilnya dan langsung tergerak untuk menontonnya?",
  ui_story_5024_50240301_111_dialog_content = "Dan kau sama sekali tak penasaran tentang bagaimana undangan itu tiba-tiba saja ada di rumahmu?",
  ui_story_5024_50240301_112_dialog_content = "Tidak. Aku harus mencari Ibu. Ibu pergi melihat pertunjukan ulang Anjing Baik yang Mengantuk. Itu sudah cukup untukku.",
  ui_story_5024_50240301_113_dialog_content = "Baiklah… Bicara apa sih aku ini. Mana mungkin tindakan maneken bisa sesuai dengan logika manusia.",
  ui_story_5024_50240301_114_dialog_content = "Kami juga sedang mencari seseorang. Sebaiknya kita bekerja sama saja.",
  ui_story_5024_50240301_115_dialog_content = "Karena kita sama-sama tak punya banyak petunjuk, apa pun yang bisa memperbesar peluang kita dalam pencarian ini berarti hal bagus.",
  ui_story_5024_50240301_116_dialog_content = "Aku setuju.",
  ui_story_5024_50240301_117_dialog_content = "Tahu tidak, walau kau tampak agak seperti tak punya emosi saat bicara, kurasa kau sama saja dengan manusia biasa.",
  ui_story_5024_50240301_118_dialog_content = "Asalkan kau tak mendadak melompat dan membuat orang lain ketakutan…",
  ui_story_5024_50240301_119_dialog_content = "Lenore tidak bermaksud membuatmu takut.",
  ui_story_5024_50240301_120_dialog_content = "Aku tahu, aku tahu… Aku hanya butuh waktu untuk membiasakan diri denganmu, itu saja…",
  ui_story_5024_50240301_121_dialog_content = "Sekarang, apa yang harus kita lakukan? Tempat ini sepertinya tak ada hubungannya sama sekali dengan teater itu.",
  ui_story_5024_50240301_122_dialog_content = "Karena teater itu dibangun ulang menjadi restoran ini, mungkin masih ada bagian teater itu yang dibiarkan utuh?",
  ui_story_5024_50240301_123_dialog_content = "Misalnya… ruang bawah tanah?",
  ui_story_5024_50240301_124_dialog_content = "Kedengarannya memang sangat mungkin ada bagian teater itu yang tersembunyi di bawah restoran ini.",
  ui_story_5024_50240301_125_dialog_content = "Coba kita ketuk-ketuk lantainya. Kalau ada pintu rahasia, suaranya akan terdengar berbeda.",
  ui_story_5024_50240301_126_dialog_content = "Baiklah. Lenore, sini, bantu kami juga. Restoran ini besar, 'kan…",
  ui_story_5024_50240301_127_dialog_content = "Lenore tidak mengerti. Apa yang harus Lenore lakukan?",
  ui_story_5024_50240301_128_dialog_content = "Ketuk saja setiap panel lantainya. Coba dengarkan, barangkali ada yang suaranya berbeda saat diketuk.",
  ui_story_5024_50240301_129_dialog_content = "Kau paham?",
  ui_story_5024_50240301_130_dialog_content = "Ketuk lantai. Lenore mengerti.",
  ui_story_5024_50240301_131_dialog_content = "Yang Lenore tidak mengerti adalah, di mana restorannya?",
  ui_story_5024_50240301_132_dialog_content = "Hah? Kita kan sedang berdiri di dalam restoran.",
  ui_story_5024_50240301_133_dialog_content = "Tidak. Baunya bukan seperti restoran.",
  ui_story_5024_50240301_134_dialog_content = "!!!",
  ui_story_5024_50240301_135_dialog_content = "Dia benar. Di dalam sini, baunya memang bukan seperti restoran.",
  ui_story_5024_50240301_136_dialog_content = "Tak ada bau makanan, masakan, atau sabun cuci.",
  ui_story_5024_50240301_137_dialog_content = "Ini hanya samaran.",
  ui_story_5024_50240301_138_dialog_content = "Meja, jendela, bahkan dindingnya palsu.",
  ui_story_5024_50240301_139_dialog_content = "Lenore hafal benda-benda palsu. Semua ini palsu.",
  ui_story_5024_50240301_140_dialog_content = "Semuanya palsu…",
  ui_story_5024_50240301_141_dialog_content = "Baiklah, baiklah!",
  ui_story_5024_50240301_142_dialog_content = "Hmm? Apa maksudmu?",
  ui_story_5024_50240301_143_dialog_content = "Dindingnya! Hancurkan!",
  ui_story_5024_50240301_144_dialog_content = "Hanya kertas penghias dinding!?",
  ui_story_5024_50240301_145_dialog_content = "Restoran yang kita lihat ini ternyata hanya lukisan di kertas penghias dinding… Pantas saja…",
  ui_story_5024_50240301_146_dialog_content = "Di mana sebenarnya tempat ini!?",
  ui_story_5024_50240301_147_dialog_content = "Robek saja semua kertasnya, nanti kita akan tahu.",
  ui_story_5024_50240301_148_dialog_content = "<color=#e8d9bb>Klik… Klik…</color>",
  ui_story_5024_50240301_149_dialog_content = "Elevator!",
  ui_story_5024_50240301_150_dialog_content = "Sebentar. Bagaimana kita bisa masuk ke sana?",
  ui_story_5024_50240301_151_dialog_content = "Pintu elevator ini adalah jalan masuk ke restoran!?",
  ui_story_5024_50240301_152_dialog_content = "PlayerName… Situasi jadi menarik.",
  ui_story_5024_50240301_153_dialog_content = "Lihat! Itu logo True Order.",
  ui_story_5024_50240301_154_dialog_content = "Kau benar… Tempat ini pastilah…",
  ui_story_5024_50240301_155_dialog_content = "Berani-beraninya mereka menjalankan kegiatan licik mereka di Lumopolis!",
  ui_story_5024_50240301_156_dialog_content = "Kali ini, aku akan…",
  ui_story_5024_50240301_157_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5024_50240301_158_dialog_content = "Apa yang terjadi?",
  ui_story_5024_50240301_159_dialog_content = "Lihat! Di atasmu!",
  ui_story_5024_50240301_160_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5024_50240301_161_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5024_50240301_162_dialog_content = "Ada Eclipsite di atas elevator! Mereka berusaha masuk!",
  ui_story_5024_50240301_163_dialog_content = "Aku tak mau naik elevator bersama Eclipsite. Singkirkan mereka semua!",
  ui_story_5024_50240301_164_dialog_content = "Mengerti. Lenore akan bantu.",
  ui_story_5024_50240402_1_dialog_content = "Lenore selesai menjalankan tugas.",
  ui_story_5024_50240402_2_dialog_content = "Kau bisa menggunakan Luminatics!?",
  ui_story_5024_50240402_3_dialog_content = "Ya, dia sama seperti Aurorian.",
  ui_story_5024_50240402_4_dialog_content = "Lenore sangat berbeda dari semua orang.",
  ui_story_5024_50240402_5_dialog_content = "Lenore tidak perlu makan atau minum.",
  ui_story_5024_50240402_6_dialog_content = "Namun, pegas penggerak Lenore harus rutin diputar.",
  ui_story_5024_50240402_7_dialog_content = "Berarti, tetap saja maneken.",
  ui_story_5024_50240402_8_dialog_content = "Bagaimana cara penciptamu membuatmu…",
  ui_story_5024_50240402_9_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_5024_50240402_10_dialog_content = "Sekarang ada apa lagi?",
  ui_story_5024_50240402_11_dialog_content = "Aku mendorong tuas kontrolnya, lalu elevatornya aktif.",
  ui_story_5024_50240402_12_dialog_content = "Aku ingin tahu elevator ini mengarah ke mana.",
  ui_story_5024_50240402_13_dialog_content = "Kuharap elevator ini menuju Wonderland Theater dan Gretel ada di sana saat kita membuka pintunya.",
  ui_story_5024_50240402_14_dialog_content = "Kita akan mengajaknya pulang ke Lumopolis. Akhir cerita yang sempurna.",
  ui_story_5024_50240402_15_dialog_content = "Makin tinggi mimpinya, makin sakit kalau jatuh.",
  ui_story_5024_50240402_16_dialog_content = "Mestinya kau memperkirakan akan menemukan sekelompok pengikut True Order yang sudah menanti di luar pintu elevator ini.",
  ui_story_5024_50240402_17_dialog_content = "Lalu, mereka akan dengan senang hati menyeretmu dan mengorbankanmu kepada dewa palsu mereka.",
  ui_story_5024_50240402_18_dialog_content = "Yah, kalau begitu, semoga saja pintu elevatornya sama sekali tak terbuka…",
  ui_story_5024_50240402_19_dialog_content = "Apa True Order itu seram?",
  ui_story_5024_50240402_20_dialog_content = "Kau tak perlu mencari tahu jawabannya. Yang penting, jaga jarak saja dari mereka.",
  ui_story_5024_50240402_21_dialog_content = "Namun, Lenore sudah jadi anggota True Order.",
  ui_story_5024_50240402_22_dialog_content = "Apa?!",
  ui_story_5024_50240402_23_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_5024_50240402_24_dialog_content = "Aduh… Kenapa kau tadi kau tak menyebutkan hal sepenting itu!?",
  ui_story_5024_50240402_25_dialog_content = "Lenore tidak tahu hal ini penting.",
  ui_story_5024_50240402_26_dialog_content = "Jangan bersandar di pintu. Pintunya terbuka.",
  ui_story_5024_50240402_27_dialog_content = "Grr… Baiklah…",
  ui_story_5024_50240402_28_dialog_content = "<color=#e8d9bb>Kriek…</color>",
  ui_story_5024_50240402_29_dialog_content = "Di luar sana…",
  ui_story_5024_50240402_30_dialog_content = "Meong!",
  ui_story_5024_50240402_31_dialog_content = "Kucing!? Kucing pakai kacamata?",
  ui_story_5024_50240402_32_dialog_content = "Oh, rupanya kau, <color=#FFB400>Beau</color>.",
  ui_story_5024_50240402_33_dialog_content = "Beau? Kau tahu kucing ini, Lenore?",
  ui_story_5024_50240402_34_dialog_content = "Ya. Ini Beau, kucing milik <color=#FFB400>May</color>.",
  ui_story_5024_50240402_35_dialog_content = "<color=#FFB400>May</color> itu siapa?",
  ui_story_5024_50240402_36_dialog_content = "Putri Ibu.",
  ui_story_5024_50240402_37_dialog_content = "Putri Ibu? Hubungan ini jadi makin rumit!",
  ui_story_5024_50240402_38_dialog_content = "Kalian akan segera melihatnya. Beau selalu ada di dekat May.",
  ui_story_5024_50240402_39_dialog_content = "Baiklah… Sudahlah, ayo keluar dari elevator.",
  ui_story_5024_50240402_40_dialog_content = "Ini…",
  ui_story_5024_50240402_41_dialog_content = "Perpustakaan?",
  ui_story_5024_50240402_42_dialog_content = "!!!",
  ui_story_5024_50240402_43_dialog_content = "Koleksi bukunya banyak sekali!",
  ui_story_5024_50240402_44_dialog_content = "Aku tak tahu di Lumopolis ada perpustakaan rahasia yang koleksi bukunya sangat banyak…",
  ui_story_5024_50240402_45_dialog_content = "Ehem—",
  ui_story_5024_50240402_46_dialog_content = "Aku mengantuk… Kurang tidur…",
  ui_story_5024_50240402_47_dialog_content = "Beau? Di mana kau? Pantas saja aku kurang tidur.",
  ui_story_5024_50240402_48_dialog_content = "Tunggu… Ada sesuatu yang membangunkanku.",
  ui_story_5024_50240402_49_dialog_content = "Kenapa… Padahal aku sudah bersembunyi di perpustakaan ini agar bisa tidur…",
  ui_story_5024_50240402_50_dialog_content = "Siapa sih orang tolol yang tak bisa tenang di dalam perpustakaan…?",
  ui_story_5024_50240402_51_dialog_content = "Meong!",
  ui_story_5024_50240402_52_dialog_content = "Oh, Lenore. Kau rupanya.",
  ui_story_5024_50240402_53_dialog_content = "Hai, May. Lama tidak jumpa.",
  ui_story_5024_50240402_54_dialog_content = "Apa kau kemari dengan mengikuti petunjuk dalam undangan yang kutinggalkan?",
  ui_story_5024_50240402_55_dialog_content = "Ya. Jadi, May meninggalkan undangan itu?",
  ui_story_5024_50240402_56_dialog_content = "Memangnya siapa lagi? Tak ada benda yang tiba-tiba saja muncul entah dari mana… Tolol…",
  ui_story_5024_50240402_57_dialog_content = "Siapa kedua orang di sampingmu itu? Aku belum pernah melihat mereka…",
  ui_story_5024_50240402_58_dialog_content = "Kami baru saja bertemu. Tujuan kami sama, jadi kami pergi bersama-sama.",
  ui_story_5024_50240402_59_dialog_content = "Bepergian dengan maneken. Kalian berdua orang aneh.",
  ui_story_5024_50240402_60_dialog_content = "Yang aneh ya maneken yang bisa berjalan dan bicara ini!",
  ui_story_5024_50240402_61_dialog_content = "Nah… Nama, identitas, dan keperluan?",
  ui_story_5024_50240402_62_dialog_content = "Aku PlayerName… Soal identitasku…",
  ui_story_5024_50240402_63_dialog_content = "Kenapa kami harus memberitahumu?",
  ui_story_5024_50240402_64_dialog_content = "Bagaimana kalau kau beri tahu kami dulu ini tempat apa dan kau siapa?",
  ui_story_5024_50240402_65_dialog_content = "Tak apa kalau kalian tak mau memberitahuku. Aku hanya ingin tahu, kok.",
  ui_story_5024_50240402_66_dialog_content = "Tempat kalian berada ini… Kami menyebutnya \"<color=#FFB400>Manor of Truth</color>.\"",
  ui_story_5024_50240402_67_dialog_content = "True Order menyuruh kami menunggu di sini untuk pertunjukan ulang Anjing Baik yang Mengantuk yang tak ada duanya.",
  ui_story_5024_50240402_68_dialog_content = "!!!",
  ui_story_5024_50240402_69_dialog_content = "Rupanya ini tempat pertemuan True Order…",
  ui_story_5024_50240402_70_dialog_content = "May, apa ada tamu lagi?",
  ui_story_5024_50240402_71_dialog_content = "Ya. Orang-orang tolol yang tak tahu apa yang terjadi…",
  ui_story_5024_50240402_72_dialog_content = "Hah? PlayerName, dan Carleen? Kenapa kalian di sini…?",
  ui_story_5024_50240402_73_dialog_content = "Ini Lumopolis, apa salahnya kalau aku di sini?",
  ui_story_5024_50240402_74_dialog_content = "Faust, sekarang apa lagi yang kaurencanakan bersama True Order?",
  ui_story_5024_50240402_75_dialog_content = "Carleen, ini kesalahpahaman besar…",
  ui_story_5024_50240402_76_dialog_content = "Namun, tak apa. Waktu kita banyak. Kalian bisa mencari jawabannya sendiri.",
  ui_story_5024_50240402_77_dialog_content = "Aku sudah punya jawaban.",
  ui_story_5024_50240402_78_dialog_content = "Jadi, kenapa kalian ke sini?",
  ui_story_5024_50240402_79_dialog_content = "Kami mencari seorang gadis yang hilang. Mungkin dia ada di sini.",
  ui_story_5024_50240402_80_dialog_content = "Gadis berambut putih, rambutnya dikucir dengan ikat rambut berbentuk pita. Kau pernah melihatnya?",
  ui_story_5024_50240402_81_dialog_content = "Gretel?",
  ui_story_5024_50240402_82_dialog_content = "Ya! Rupanya kau memang melihatnya!",
  ui_story_5024_50240402_83_dialog_content = "Di mana dia?",
  ui_story_5024_50240402_84_dialog_content = "Dia…",
  ui_story_5024_50240402_85_dialog_content = "Maaf. Kalian tak bisa menemuinya sekarang.",
  ui_story_5024_50240402_86_dialog_content = "Dia ada di suatu tempat lain.",
  ui_story_5024_50240402_87_dialog_content = "Tempat lain?",
  ui_story_5024_50240402_88_dialog_content = "Aku… akan memberi tahu kalian tentang itu nanti.",
  ui_story_5024_50240402_89_dialog_content = "Mari, ikut aku. True Order tak pernah memperlakukan tamu seperti ini.",
  ui_story_5024_50240402_90_dialog_content = "Kami bukan tamu True Order.",
  ui_story_5024_50240402_91_dialog_content = "Maaf, tapi sekarang kalian sudah jadi tamu kami.",
  ui_story_5024_50240402_92_dialog_content = "Lihat sekeliling kalian. Tak ada bahaya di sekitarmu, Carleen. Kau tentu tak akan bersikap agresif terhadap kami, 'kan?",
  ui_story_5024_50240402_93_dialog_content = "…",
  ui_story_5024_50240402_94_dialog_content = "Apa Lenore juga tamu?",
  ui_story_5024_50240402_95_dialog_content = "Jelas. Mari, lewat sini.",
  ui_story_5024_50240402_96_dialog_content = "Aku tak menyangka, bagian dalamnya ternyata sangat luas.",
  ui_story_5024_50240402_97_dialog_content = "Aku tak melihat bangunan besar sama sekali di jalan ini.",
  ui_story_5024_50240402_98_dialog_content = "Kalian belum juga sadar? Akal sehat tak berfungsi di sini.",
  ui_story_5024_50240402_99_dialog_content = "Manor of Truth akan mengajarkan kapan kalian harus menanggalkan <color=#FFB400>indra</color> kalian.",
  ui_story_5024_50240402_100_dialog_content = "Indra?",
  ui_story_5024_50240402_101_dialog_content = "Kalian boleh menyebutnya dengan istilah lain. Nalar, logika, sebab-akibat…",
  ui_story_5024_50240402_102_dialog_content = "Atau, gampangnya, apa pun yang bisa membantu kita memahami apa yang diungkapkan oleh orang lain.",
  ui_story_5024_50240402_103_dialog_content = "Dewa menciptakan dunia ini dalam dua sisi. Indra membantu peradaban manusia untuk berkembang, tapi juga mengaburkan mata kita.",
  ui_story_5024_50240402_104_dialog_content = "Seperti itukah pandangan True Order tentang dunia ini…?",
  ui_story_5024_50240402_105_dialog_content = "Seperti itulah dunia ini bagi semua orang.",
  ui_story_5024_50240402_106_dialog_content = "Begitu pula apa yang sedang kalian alami ini.",
  ui_story_5024_50240402_107_dialog_content = "Kalian melihat sesuatu yang tak biasa, dan berusaha memahaminya, dan itu membuat nalar dan logika kalian hancur.",
  ui_story_5024_50240402_108_dialog_content = "Dengan kata lain, kalian menanggalkan sebagian indra kalian dalam proses ini.",
  ui_story_5024_50240402_109_dialog_content = "Setelah ini, kalian mungkin akan punya kesempatan untuk melihat lebih banyak.",
  ui_story_5024_50240402_110_dialog_content = "Aku tak paham… Jadi, bagaimana caranya kami masuk ke sini?",
  ui_story_5024_50240402_111_dialog_content = "Apa kami masih di Midnight Street di Lumopolis?",
  ui_story_5024_50240402_112_dialog_content = "Dalam undangan itu, memang tertulis bahwa kalian harus sampai di Midnight Street saat tengah malam.",
  ui_story_5024_50240402_113_dialog_content = "Begitu lonceng berdentang, selama kalian masih di Midnight Street, berarti kalian membuka pintu menuju Manor of Truth.",
  ui_story_5024_50240402_114_dialog_content = "Di sepanjang jalan, hal-hal yang kalian temui, yang bukan bagian dari Lumopolis, pelan-pelan melemahkan indra kalian.",
  ui_story_5024_50240402_115_dialog_content = "Dengan begitu, kalian bisa melihat lebih banyak, misalnya elevator yang tak wajar itu, dan Manor of Truth ini.",
  ui_story_5024_50240402_116_dialog_content = "Melihat lebih banyak…",
  ui_story_5024_50240402_117_dialog_content = "Tentu saja, kehilangan seluruh indra memang menghadirkan konsekuensi besar. Sebaiknya kalian berhenti sekarang.",
  ui_story_5024_50240402_118_dialog_content = "Biarlah misteri di luar batas ini menjadi urusan orang-orang yang lebih fanatik.",
  ui_story_5024_50240402_119_dialog_content = "…",
  ui_story_5024_50240402_120_dialog_content = "Haha! Tak usah jadi suram begitu. Bisa sampai di Manor of Truth adalah hal yang perlu dirayakan.",
  ui_story_5024_50240402_121_dialog_content = "Suasana di sini gembira.",
  ui_story_5024_50240402_122_dialog_content = "Jadi, tinggalkan semua kesedihan, sikap, dan identitas kalian, dan nikmatilah jamuan makan penuh sukacita bagi semua orang ini!",
  ui_story_5024_50240501_1_dialog_content = "Jamuan makannya akan segera dimulai…",
  ui_story_5024_50240501_2_dialog_content = "Makanannya belum siap… belum siap…",
  ui_story_5024_50240501_3_dialog_content = "Nails, kau baik-baik saja?",
  ui_story_5024_50240501_4_dialog_content = "Aku baik-baik saja… Hanya saja, aku agak khawatir tentang jamuan makannya…",
  ui_story_5024_50240501_5_dialog_content = "Aku harus ke dapur dan memastikan semua makanan sudah siap.",
  ui_story_5024_50240501_6_dialog_content = "Hm? Apa orang yang berdiri di dekatmu itu tamu baru?",
  ui_story_5024_50240501_7_dialog_content = "Ya. Mereka—",
  ui_story_5024_50240501_8_dialog_content = "Mungkin tak perlu perkenalan. Kau sudah kenal mereka, kok.",
  ui_story_5024_50240501_9_dialog_content = "Ya, tapi aku kaget melihat PlayerName dan Carleen ada di sini…",
  ui_story_5024_50240501_10_dialog_content = "Bagus. Makin banyak orang akan menikmati masakanku malam ini…",
  ui_story_5024_50240501_11_dialog_content = "Apa ada makanan tertentu yang kalian sukai? Bilang saja, jangan malu-malu…",
  ui_story_5024_50240501_12_dialog_content = "Eh? Aku suka makan apa saja, kok… Carleen?",
  ui_story_5024_50240501_13_dialog_content = "Tak ada makanan kesukaan tertentu…",
  ui_story_5024_50240501_14_dialog_content = "Bagus. Aku juga tak suka tamu yang terlalu pemilih, sih…",
  ui_story_5024_50240501_15_dialog_content = "Aku permisi dulu. Sampai jumpa nanti saat jamuan makan.",
  ui_story_5024_50240501_16_dialog_content = "Baiklah…",
  ui_story_5024_50240501_17_dialog_content = "Faust, jamuan makan ini dalam rangka apa?",
  ui_story_5024_50240501_18_dialog_content = "Aneh sekali kalau kau tiba-tiba menyajikan jamuan makan untuk kami…",
  ui_story_5024_50240501_19_dialog_content = "Kami kemari bukan untuk bersenang-senang. Kami sedang mencari seseorang!",
  ui_story_5024_50240501_20_dialog_content = "Tak ada yang aneh tentang ini. Semua orang yang datang ke Manor of Truth layak menerima jamuan makan.",
  ui_story_5024_50240501_21_dialog_content = "Lalu, tentang orang yang kalian cari itu… Tak perlu buru-buru. Lagi pula, kalian memang tak akan bisa memaksa untuk segera bertemu dengannya.",
  ui_story_5024_50240501_22_dialog_content = "Apa maksudmu!? Sudah berhari-hari Gretel hilang…",
  ui_story_5024_50240501_23_dialog_content = "Hah? PlayerName? Dan Carleen?",
  ui_story_5024_50240501_24_dialog_content = "Kenapa kalian di sini…? Apa kalian juga kemari untuk menonton pertunjukan ulang itu?",
  ui_story_5024_50240501_25_dialog_content = "Oh, Beryl! Lama tak jumpa!",
  ui_story_5024_50240501_26_dialog_content = "Sebenarnya kami kemari mencari seseorang. Rambutnya putih…",
  ui_story_5024_50240501_27_dialog_content = "Gretel, ya?",
  ui_story_5024_50240501_28_dialog_content = "Ya! Kau pernah melihatnya?",
  ui_story_5024_50240501_29_dialog_content = "Oh, betapa aku iri kepada si Gretel itu.",
  ui_story_5024_50240501_30_dialog_content = "Semua orang iri kepadanya. Kami semua ingin jadi seperti dia…",
  ui_story_5024_50240501_31_dialog_content = "Sayangnya, tak seorang pun dari kami berhasil menemukan cara untuk masuk ke teater.",
  ui_story_5024_50240501_32_dialog_content = "Tak seorang pun, kecuali dia…",
  ui_story_5024_50240501_33_dialog_content = "Teater? Maksudmu Wonderland Theater?",
  ui_story_5024_50240501_34_dialog_content = "Di mana Gretel?",
  ui_story_5024_50240501_35_dialog_content = "Bukan… Bukan begitu… Aku bingung bagaimana harus menjelaskannya…",
  ui_story_5024_50240501_36_dialog_content = "Ada beberapa buku tentang teater itu. Kalau sudah membacanya, kalian akan paham.",
  ui_story_5024_50240501_37_dialog_content = "Ayo kita baca buku, PlayerName. Akan kutunjukkan isinya.",
  ui_story_5024_50240501_38_dialog_content = "Apa ini… memang serumit itu?",
  ui_story_5024_50240501_39_dialog_content = "Maaf… Hanya saja, aku tak pintar memberikan penjelasan.",
  ui_story_5024_50240501_40_dialog_content = "Mungkin besok saja, Beryl. Kita tak punya waktu hari ini.",
  ui_story_5024_50240501_41_dialog_content = "Jamuan makannya akan segera dimulai. Jangan sampai ketinggalan.",
  ui_story_5024_50240501_42_dialog_content = "Benar, jamuan makannya…",
  ui_story_5024_50240501_43_dialog_content = "Terima kasih sudah mengingatkanku, Faust.",
  ui_story_5024_50240501_44_dialog_content = "Akan kukembalikan buku-buku ini ke rak.",
  ui_story_5024_50240501_45_dialog_content = "Jangan sampai tersesat.",
  ui_story_5024_50240501_46_dialog_content = "Ya… Semoga saja aku cukup hafal tempat ini.",
  ui_story_5024_50240501_47_dialog_content = "Jadi… Bagimu, Manor of Truth ini apa?",
  ui_story_5024_50240501_48_dialog_content = "Tempat pertemuan rahasia?",
  ui_story_5024_50240501_49_dialog_content = "Tidak juga. Kami semua menerima undangan untuk menonton pertunjukan itu.",
  ui_story_5024_50240501_50_dialog_content = "Kami semua di sini karena kami tertarik dengannya.",
  ui_story_5024_50240501_51_dialog_content = "Kalau begitu, kenapa ada logo True Order di elevator?",
  ui_story_5024_50240501_52_dialog_content = "Mungkin, entah bagaimana, orang yang membangun Manor of Truth ini punya hubungan dengan True Order.",
  ui_story_5024_50240501_53_dialog_content = "Entahlah. Untuk detailnya, tanyakan saja kepada Victoria.",
  ui_story_5024_50240501_54_dialog_content = "Victoria? Dia tak tertarik menjawab pertanyaan-pertanyaan membosankan.",
  ui_story_5024_50240501_55_dialog_content = "Fokus saja mencari cara masuk ke Wonderland Theater.",
  ui_story_5024_50240501_56_dialog_content = "Dengan begitu, setidaknya kalian akan makin mendekati kebenaran.",
  ui_story_5024_50240501_57_dialog_content = "Aku hanya menjawab pertanyaan dari para tamu baru kita, <color=#FFB400>Telamont</color>.",
  ui_story_5024_50240501_58_dialog_content = "Tamu baru…? Ada tamu baru lagi?",
  ui_story_5024_50240501_59_dialog_content = "Pakaiannya sangat biasa… Sungguh membosankan.",
  ui_story_5024_50240501_60_dialog_content = "Makin banyak perut yang akan ikut menikmati makanan itu.",
  ui_story_5024_50240501_61_dialog_content = "Perut!?",
  ui_story_5024_50240501_62_dialog_content = "Oh ya, kalian belum mengenalnya.",
  ui_story_5024_50240501_63_dialog_content = "Dia Telamont. Dia memang agak aneh, sekaligus seorang petapa.",
  ui_story_5024_50240501_64_dialog_content = "Jangan marah kepadanya. Dia memang memandang rendah semua orang, kecuali Victoria.",
  ui_story_5024_50240501_65_dialog_content = "Sudahlah. Kalau kau memang suka bicara keras-keras, silakan saja.",
  ui_story_5024_50240501_66_dialog_content = "Faust, sudah saatnya menjemput Victoria.",
  ui_story_5024_50240501_67_dialog_content = "Memang itulah niatku.",
  ui_story_5024_50240501_68_dialog_content = "Kita berpisah di sini. Aula jamuan makannya persis di depan sana. Kalian bisa menunggu di sana.",
  ui_story_5024_50240501_69_dialog_content = "Jamuan makannya akan segera dimulai. Sampai jumpa lagi nanti.",
  ui_story_5024_50240501_70_dialog_content = "Baiklah. Kita masuk tidak, nih?",
  ui_story_5024_50240501_71_dialog_content = "Santai saja. Jamuan makan ini untuk semua orang, kok.",
  ui_story_5024_50240501_72_dialog_content = "Ha, rupanya kau memang suka jadi pelayan, ya.",
  ui_story_5024_50240501_73_dialog_content = "Harus ada orang yang bertugas menjaga ketertiban, terutama kalau orang sepertimu ada di sini.",
  ui_story_5024_50240501_74_dialog_content = "Orang-orang True Order ini kenapa, sih…?",
  ui_story_5024_50240501_75_dialog_content = "Menggelar pertemuan rahasia di tempat seaneh ini… hanya untuk mengadakan jamuan makan?",
  ui_story_5024_50240501_76_dialog_content = "Haha, setidaknya ini lebih baik daripada mengorbankan kita kepada dewa palsu mereka…",
  ui_story_5024_50240501_77_dialog_content = "Coba kita lihat saja. Siapa tahu nanti pandanganmu tentang True Order akan berubah.",
  ui_story_5024_50240501_78_dialog_content = "Aku akan tetap mengamati segalanya…",
  ui_story_5024_50240501_79_dialog_content = "<color=#e8d9bb>Krieeek…</color>",
  ui_story_5024_50240501_80_dialog_content = "Satu, dua, tiga…",
  ui_story_5024_50240501_81_dialog_content = "Kali ini, banyak sekali bocah yang tersesat!",
  ui_story_5024_50240501_82_dialog_content = "Mendekatlah ke perapian. Kau pasti mengantuk.",
  ui_story_5024_50240501_83_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5024_50240501_84_dialog_content = "Woah!",
  ui_story_5024_50240501_85_dialog_content = "Apa ini!?",
  ui_story_5024_50240501_86_dialog_content = "Isaac tak banyak bicara, tapi dia anjing yang baik.",
  ui_story_5024_50240501_87_dialog_content = "Si anak domba yang sedang bekerja, si kucing yang sedang membaca, dan si burung hantu salju yang egois, semua sayang kepadanya.",
  ui_story_5024_50240501_88_dialog_content = "Mereka menyisiri bulu Isaac, mengelus-elus punggungnya, dan memberinya camilan.",
  ui_story_5024_50240501_89_dialog_content = "Namun, Isaac tak suka mereka!",
  ui_story_5024_50240501_90_dialog_content = "Isaac hanya suka cerita-ceritaku, sedangkan anak-anak itu selalu saja tak sabaran.",
  ui_story_5024_50240501_91_dialog_content = "Bagaimana dengan kalian, anak-anak yang tersesat?",
  ui_story_5024_50240501_92_dialog_content = "Apa kalian mau mendengarkan ceritaku?",
  ui_story_5024_50240501_93_dialog_content = "Namun, pertama-tama… Siapa kau?",
  ui_story_5024_50240501_94_dialog_content = "Aku sang narator. Kau boleh memanggilku <color=#FFB400>Giles</color>.",
  ui_story_5024_50240501_95_dialog_content = "Atau, terserah kau mau memanggilku apa. Aku suka nama julukan yang menarik.",
  ui_story_5024_50240501_96_dialog_content = "Aku bukan tokoh dalam kisah ini, jadi aku tak perlu nama.",
  ui_story_5024_50240501_97_dialog_content = "Apa maksud perkataannya…? Aku sama sekali tak paham.",
  ui_story_5024_50240501_98_dialog_content = "Setidaknya kita tahu bahwa dia biasa dipanggil Giles…",
  ui_story_5024_50240501_99_dialog_content = "Kalian berbeda dari si anak domba, si kucing, dan si burung hantu salju.",
  ui_story_5024_50240501_100_dialog_content = "Kalian pasti ada di sini karena kalian tersesat.",
  ui_story_5024_50240501_101_dialog_content = "Apa kita… tersesat?",
  ui_story_5024_50240501_102_dialog_content = "Yah, aku memang tak tahu pasti apa yang terjadi dalam perjalanan menuju ke sini…",
  ui_story_5024_50240501_103_dialog_content = "Namun, kami berniat pergi ke Wonderland Theater. Apa benar ini tempatnya?",
  ui_story_5024_50240501_104_dialog_content = "Apa? Kau juga?",
  ui_story_5024_50240501_105_dialog_content = "Kau juga mau ke Wonderland Theater, sama seperti mereka?",
  ui_story_5024_50240501_106_dialog_content = "Tidak… Tentu saja tidak! Sebaiknya kalian menyerah saja!",
  ui_story_5024_50240501_107_dialog_content = "Lupakan Theater! Nikmati saja kisah-kisah dongeng, atau jamuan makan…",
  ui_story_5024_50240501_108_dialog_content = "Pokoknya, lupakan Theater itu!",
  ui_story_5024_50240501_109_dialog_content = "Hah? Namun…",
  ui_story_5024_50240501_110_dialog_content = "Kalian tak boleh masuk ke Theater. Sama sekali tak boleh!",
  ui_story_5024_50240501_111_dialog_content = "Kalian sama saja seperti mereka… Kalian tak tahu apa pun!",
  ui_story_5024_50240501_112_dialog_content = "<color=#e8d9bb>Gong, gong, gong, gong…</color>",
  ui_story_5024_50240501_113_dialog_content = "Ya ampun, loncengnya berisik amat!",
  ui_story_5024_50240501_114_dialog_content = "Akhirnya… Berhasil!",
  ui_story_5024_50240501_115_dialog_content = "Tepat waktu!",
  ui_story_5024_50240501_116_dialog_content = "Jarang sekali kau tak terlambat.",
  ui_story_5024_50240501_117_dialog_content = "Cih. Pasti Faust sudah mengingatkan dia.",
  ui_story_5024_50240501_118_dialog_content = "Jamuan makannya akan segera dimulai… segera dimulai…",
  ui_story_5024_50240501_119_dialog_content = "Harus sajikan makanan di meja…",
  ui_story_5024_50240501_120_dialog_content = "Awas, Nails!",
  ui_story_5024_50240501_121_dialog_content = "Aku lapar sekali! Aku mau makan!",
  ui_story_5024_50240501_122_dialog_content = "Wow, aromanya sangat lezat…",
  ui_story_5024_50240501_123_dialog_content = "Kelihatannya memang ini jamuan makan biasa.",
  ui_story_5024_50240501_124_dialog_content = "Duduk, duduk!",
  ui_story_5024_50240501_125_dialog_content = "Mari kita sambut Victoria.",
  ui_story_5024_50240501_126_dialog_content = "Hari ini, kita kedatangan tamu baru. Jadi, tak usah saling berebut kursi.",
  ui_story_5024_50240501_127_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_5024_50240501_128_dialog_content = "Duduklah, Nails!",
  ui_story_5024_50240501_129_dialog_content = "Sebentar lagi… Tinggal beberapa hidangan lagi…",
  ui_story_5024_50240501_130_dialog_content = "<color=#e8d9bb>Ta…</color>",
  ui_story_5024_50240501_131_dialog_content = "Victoria!",
  ui_story_5024_50240501_132_dialog_content = "Begitu lonceng berdentang, jamuan makan akan dimulai.",
  ui_story_5024_50240501_133_dialog_content = "Tak usah memperhatikanku, atau siapa pun.",
  ui_story_5024_50240501_134_dialog_content = "Kita di sini untuk menikmati jamuan makan dan menantikan pertunjukan yang tak ada duanya itu.",
  ui_story_5024_50240501_135_dialog_content = "Kami paham, Victoria.",
  ui_story_5024_50240501_136_dialog_content = "Kalau begitu, mari kita mulai jamuan makannya.",
  ui_story_5024_50240501_137_dialog_content = "Oh! Mereka mulai menikmati makanan!",
  ui_story_5024_50240501_138_dialog_content = "Kita juga harus…",
  ui_story_5024_50240501_139_dialog_content = "Hah? Kalian berdua tak lapar?",
  ui_story_5024_50240501_140_dialog_content = "Lenore tidak perlu makan.",
  ui_story_5024_50240501_141_dialog_content = "Oh, iya… Hampir saja aku lupa…",
  ui_story_5024_50240501_142_dialog_content = "Aku tak tahan kalau harus makan di meja yang sama dengan True Order…",
  ui_story_5024_50240501_143_dialog_content = "Namun, bukannya kau lapar? Dari tadi kan kita sibuk sekali.",
  ui_story_5024_50240501_144_dialog_content = "Kalaupun kau benci True Order, makanan ini kan tak bersalah.",
  ui_story_5024_50240501_145_dialog_content = "Apa sekarang kalian menikmati hidangannya, tamu-tamu baru kami?",
  ui_story_5024_50240501_146_dialog_content = "Maaf, pasti gara-gara hidanganku…",
  ui_story_5024_50240501_147_dialog_content = "Nails, tak ada seorang pun yang menyalahkanmu.",
  ui_story_5024_50240501_148_dialog_content = "…",
  ui_story_5024_50240501_149_dialog_content = "Victoria, aku tak menyangka akan bertemu denganmu dalam situasi seperti ini.",
  ui_story_5024_50240501_150_dialog_content = "Kenapa? Apa Lumopolis yang megah itu melarangmu untuk membayangkannya, Carleen?",
  ui_story_5024_50240501_151_dialog_content = "Terlepas dari prasangka, ada banyak skenario bahwa kita mungkin akan bertemu.",
  ui_story_5024_50240501_152_dialog_content = "Mungkin saat Lumopolis runtuh, atau saat kau menikah.",
  ui_story_5024_50240501_153_dialog_content = "Atau, mungkin saat kita dikuburkan di liang yang sama.",
  ui_story_5024_50240501_154_dialog_content = "Aku yakin tak satu pun dari skenario itu akan terjadi!",
  ui_story_5024_50240501_155_dialog_content = "Yah, kemarin kau pasti juga tak membayangkan akan duduk bersantap semeja dengan True Order.",
  ui_story_5024_50240501_156_dialog_content = "\"Keyakinanmu\" tak ada artinya. Itulah sebabnya ayahmu jarang memanfaatkannya.",
  ui_story_5024_50240501_157_dialog_content = "…",
  ui_story_5024_50240501_158_dialog_content = "Karena para tamu baru kita tak tertarik dengan hidangannya, kami akan sajikan acara hiburannya lebih awal.",
  ui_story_5024_50240501_159_dialog_content = "Giles, kau sudah siap?",
  ui_story_5024_50240501_160_dialog_content = "Victoria… Suatu kehormatan bagiku!",
  ui_story_5024_50240501_161_dialog_content = "Namun… Bolehkah aku menyajikan pertunjukan lain?",
  ui_story_5024_50240501_162_dialog_content = "Tanyakan saja kepada para penontonmu.",
  ui_story_5024_50240501_163_dialog_content = "May mau menonton Anjing Baik yang Mengantuk.",
  ui_story_5024_50240501_164_dialog_content = "Benar… Aku lebih tertarik dengan Anjing Baik yang Mengantuk.",
  ui_story_5024_50240501_165_dialog_content = "Kami semua ke sini untuk menonton Anjing Baik yang Mengantuk…",
  ui_story_5024_50240501_166_dialog_content = "Kenapa!? Karya ciptaanku sendiri jauh lebih menarik daripada dongeng itu!",
  ui_story_5024_50240501_167_dialog_content = "Aku yakin sebagian besar dari kita di sini sudah pernah menonton kisah-kisahmu yang biasa saja itu.",
  ui_story_5024_50240501_168_dialog_content = "Simpan saja kisah-kisah itu untuk anak-anak Lumopolis. Kemungkinan besar mereka akan menyukainya.",
  ui_story_5024_50240501_169_dialog_content = "Kau tahu pasti apa tujuan kami datang ke sini.",
  ui_story_5024_50240501_170_dialog_content = "Cih.",
  ui_story_5024_50240501_171_dialog_content = "\"Si burung hantu salju yang egois selalu menganggap dirinya paling benar…\"",
  ui_story_5024_50240501_172_dialog_content = "\"Upayanya untuk menemukan cinta sama saja dengan membenturkan kepalanya ke cermin!\"",
  ui_story_5024_50240501_173_dialog_content = "Cukup sudah. Aku tak paham makna nyanyianmu.",
  ui_story_5024_50240501_174_dialog_content = "Langsung saja ke intinya. Kami semua menanti pencerahan.",
  ui_story_5024_50240501_175_dialog_content = "…Ba-baiklah.",
  ui_story_5024_50240501_176_dialog_content = "Akan kulakukan sesuai keinginanmu… Kalau begitu, saatnya Anjing Baik yang Mengantuk…",
  ui_story_5024_50240501_177_dialog_content = "Ini misiku…",
  ui_story_5024_50240501_178_dialog_content = "Namun, sekadar peringatan, ya…",
  ui_story_5024_50240501_179_dialog_content = "Tak seorang pun dari kalian boleh berusaha lagi mencari cara untuk masuk ke Theater.",
  ui_story_5024_50240501_180_dialog_content = "Dari lubuk hatiku yang paling dalam…",
  ui_story_5024_50240501_181_dialog_content = "Aku hanya berharap kalian mau percaya kepadaku dan mendengarkan nasihatku…",
  ui_story_5024_50240501_182_dialog_content = "Nah, silakan nikmati pertunjukannya: Anjing Baik yang Mengantuk.",
  ui_story_5024_50240501_183_dialog_content = "\"Bangunlah… Bangunlah…\"",
  ui_story_5024_50240501_184_dialog_content = "\"Bangun rumah yang indah.\"",
  ui_story_5024_50240501_185_dialog_content = "\"Bukan untuk Jenderal atau Tuan…\"",
  ui_story_5024_50240501_186_dialog_content = "\"Namun untuk si anjing baik yang mengantuk di dekat perapian.\"",
  ui_story_5024_50240501_187_dialog_content = "\"Bukalah, bukalah…\"",
  ui_story_5024_50240501_188_dialog_content = "\"Buka pintu masuk ke rumah.\"",
  ui_story_5024_50240501_189_dialog_content = "\"Si anak domba, si kucing, dan si burung hantu salju gelandangan…\"",
  ui_story_5024_50240501_190_dialog_content = "\"Mengitari si anjing baik yang mengantuk di dekat perapian.\"",
  ui_story_5024_50240501_191_dialog_content = "\"Kurung mereka, kurung mereka…\"",
  ui_story_5024_50240501_192_dialog_content = "\"Kuncilah jendela rumah.\"",
  ui_story_5024_50240501_193_dialog_content = "\"Gelak tawa pesta mengalun keluar dari jendela.…\"",
  ui_story_5024_50240501_194_dialog_content = "Namun tak bisa membangunkan si anjing baik yang tidur di dekat perapian.",
  ui_story_5024_50240501_195_dialog_content = "Kurung mereka, kurung mereka…",
  ui_story_5024_50240501_196_dialog_content = "Kuncilah pintu depan rumah.",
  ui_story_5024_50240501_197_dialog_content = "\"Di dalam hangat dan nyaman, meski tanpa kehadiran tuan…\"",
  ui_story_5024_50240501_198_dialog_content = "Tak usah hiraukan si anjing tua baik yang mengantuk di dekat perapian.",
  ui_story_5024_50240501_199_dialog_content = "Kurung mereka, kurung mereka…",
  ui_story_5024_50240501_200_dialog_content = "\"Kunci ■■■■■ semua.\"",
  ui_story_5024_50240501_201_dialog_content = "\"Betapa lucunya mereka, tidur berdampingan…\"",
  ui_story_5024_50240501_202_dialog_content = "Si anak domba, si kucing, dan si burung hantu salju, bersama si anjing baik yang mengantuk.",
  ui_story_5024_50240501_203_dialog_content = "Betapa lucunya mereka, tidur berdampingan…",
  ui_story_5024_50240501_204_dialog_content = "\"Si anak domba, si kucing, si burung hantu salju, dan si anjing tua baik yang mengantuk!\"",
  ui_story_5024_50240501_205_dialog_content = "<color=#e8d9bb>*Tepuk tangan*</color>",
  ui_story_5024_50240501_206_dialog_content = "Terima kasih, Giles. Cemerlang, seperti biasanya.",
  ui_story_5024_50240501_207_dialog_content = "Ini pertama kalinya Lenore dengar Anjing yang Mengantuk sampai selesai.",
  ui_story_5024_50240501_208_dialog_content = "Ibu biasa menceritakannya kepada Lenore, tapi hanya sepotong-sepotong.",
  ui_story_5024_50240501_209_dialog_content = "Terakhir kali kau dan ibumu menontonnya adalah tujuh belas tahun lalu, 'kan?",
  ui_story_5024_50240501_210_dialog_content = "Pertunjukannya terhenti, jadi lagunya pun tak selesai.",
  ui_story_5024_50240501_211_dialog_content = "Kalau benar begitu… Berarti, mestinya tak ada seorang pun yang pernah menonton Anjing Baik yang Mengantuk sampai selesai.",
  ui_story_5024_50240501_212_dialog_content = "Lalu, dari mana Giles tahu keseluruhan lagunya?",
  ui_story_5024_50240501_213_dialog_content = "Karena tahun lalu ada pertunjukan ulang Anjing Baik yang Mengantuk.",
  ui_story_5024_50240501_214_dialog_content = "Waktu itu, Giles datang ke Manor of Truth dan berhasil masuk ke Theater.",
  ui_story_5024_50240501_215_dialog_content = "Hah? Dia tahu cara masuk ke sana?",
  ui_story_5024_50240501_216_dialog_content = "Ya, tapi dia tak mau memberitahukannya.",
  ui_story_5024_50240501_217_dialog_content = "Lalu, sikapnya tentang Theater jadi sangat keras.",
  ui_story_5024_50240501_218_dialog_content = "Apa yang dialaminya di dalam Theater itu…?",
  ui_story_5024_50240501_219_dialog_content = "Aku hanya tahu bahwa ada empat orang lain yang masuk bersamanya.",
  ui_story_5024_50240501_220_dialog_content = "Dia satu-satunya orang yang berhasil keluar dari sana.",
  ui_story_5024_50240501_221_dialog_content = "Oh!",
  ui_story_5024_50240501_222_dialog_content = "Dia satu-satunya orang yang berhasil keluar dari sana.",
  ui_story_5024_50240501_223_dialog_content = "Karena itulah, dia satu-satunya orang yang tahu keseluruhan kisah Anjing Baik yang Mengantuk.",
  ui_story_5024_50240501_224_dialog_content = "Sebentar! Aku jadi kepikiran sesuatu…",
  ui_story_5024_50240501_225_dialog_content = "Maaf, aku harus pergi… Aku harus memeriksa sesuatu di perpustakaan.",
  ui_story_5024_50240501_226_dialog_content = "Kurasa tadi aku mendengar suara yang berbeda dalam lagunya.",
  ui_story_5024_50240501_227_dialog_content = "Victoria, bolehkah aku kembali ke kamar untuk bermeditasi?",
  ui_story_5024_50240501_228_dialog_content = "Tentu saja. Kita sudah makan dan acara hiburannya juga sudah selesai. Jamuan makan hari ini bisa diakhiri.",
  ui_story_5024_50240501_229_dialog_content = "Aku juga harus kembali ke kamar.",
  ui_story_5024_50240501_230_dialog_content = "Biar kuantar, Victoria.",
  ui_story_5024_50240501_231_dialog_content = "Tamu-tamu baru, mari kuantar kalian ke kamar tamu.",
  ui_story_5024_50240501_232_dialog_content = "Tadi kalian sudah menempuh perjalanan panjang. Kalian butuh istirahat.",
  ui_story_5024_50240501_233_dialog_content = "Tak usah mengkhawatirkan kami. Kami bisa mengurus diri kami sendiri.",
  ui_story_5024_50240501_234_dialog_content = "Carleen, aku paham kenapa kau merasa cemas dan tak sabar.",
  ui_story_5024_50240501_235_dialog_content = "Namun, kau tak akan menemukan Gretel hari ini.",
  ui_story_5024_50240501_236_dialog_content = "Akan lebih baik kalau kalian beristirahat dengan nyaman.",
  ui_story_5024_50240501_237_dialog_content = "Bagaimana menurutmu, PlayerName…?",
  ui_story_5024_50240501_238_dialog_content = "Aku tak merasakan ada niat jahat dari True Order.",
  ui_story_5024_50240501_239_dialog_content = "Kurasa, sebaiknya kita ikuti saja saran Faust. Hari ini, kita memang sudah menemukan banyak hal.",
  ui_story_5024_50240501_240_dialog_content = "Besok, aku akan mencari informasi dari Giles.",
  ui_story_5024_50240501_241_dialog_content = "Kalau begitu, mari ikut aku.",
  ui_story_5024_50240501_242_dialog_content = "Akomodasi di sini cukup bagus.",
  ui_story_5024_50240501_243_dialog_content = "Kami hanya bisa berharap semoga ini sesuai dengan standar Putri Lumopolis.",
  ui_story_5024_50240601_1_dialog_content = "Asyik!",
  ui_story_5024_50240601_2_dialog_content = "Kasurnya nyaman sekali!",
  ui_story_5024_50240601_3_dialog_content = "Matahari sudah terbit…? Aku masih ingin tidur…",
  ui_story_5024_50240601_4_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5024_50240601_5_dialog_content = "Woah! Apa itu!?",
  ui_story_5024_50240601_6_dialog_content = "Ada yang mengetuk pintu?",
  ui_story_5024_50240601_7_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5024_50240601_8_dialog_content = "Kenapa keras sekali, sih!?",
  ui_story_5024_50240601_9_dialog_content = "Carleen, kaukah itu?",
  ui_story_5024_50240601_10_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5024_50240601_11_dialog_content = "Iya, iya. Kubukakan pintunya…",
  ui_story_5024_50240601_12_dialog_content = "Nah, siapa…",
  ui_story_5024_50240601_13_dialog_content = "Hah? Tak ada orang di sini…?",
  ui_story_5024_50240601_14_dialog_content = "PlayerName, kaukah yang tadi mengetuk-ngetuk pintu kamarku?",
  ui_story_5024_50240601_15_dialog_content = "Eh? Aku baru saja berniat menanyakan hal yang sama!",
  ui_story_5024_50240601_16_dialog_content = "Lenore! Kenapa kau mengetuk-ngetuk pintuku seperti itu!?",
  ui_story_5024_50240601_17_dialog_content = "Baru hari pertama di Manor of Truth, tidurku sudah tak nyaman…",
  ui_story_5024_50240601_18_dialog_content = "Bukan Lenore. Ada seseorang yang juga mengetuk pintu kamar Lenore.",
  ui_story_5024_50240601_19_dialog_content = "Sebentar. Kita berempat sama-sama mendengar ada yang mengetuk pintu kamar kita?",
  ui_story_5024_50240601_20_dialog_content = "Namun, tak ada orang lain di koridor ini…",
  ui_story_5024_50240601_21_dialog_content = "*Hiks*",
  ui_story_5024_50240601_22_dialog_content = "Aku ingin pergi… Biarkan aku pergi…",
  ui_story_5024_50240601_23_dialog_content = "Aku dengar sesuatu dari arah sana.",
  ui_story_5024_50240601_24_dialog_content = "Ada yang menangis…",
  ui_story_5024_50240601_25_dialog_content = "Kita tak bisa melakukannya… Tamat sudah riwayat kita…",
  ui_story_5024_50240601_26_dialog_content = "Kita ini aktor… Kita tak boleh menganggap diri kita ini tokoh dalam cerita… Sama sekali tak boleh… *Hiks*",
  ui_story_5024_50240601_27_dialog_content = "Suaranya seperti Giles. Lagi-lagi dia berperilaku aneh.",
  ui_story_5024_50240601_28_dialog_content = "Apa dia… selalu begitu?",
  ui_story_5024_50240601_29_dialog_content = "Baru sekali ini aku mendengarnya menangis.",
  ui_story_5024_50240601_30_dialog_content = "Namun, biasanya dia memang tampak agak pemarah dan menganggap semua orang sama dengan binatang…",
  ui_story_5024_50240601_31_dialog_content = "Apa sebaiknya kita lihat saja keadaannya?",
  ui_story_5024_50240601_32_dialog_content = "Kalau kita ingin masuk ke Theater, dia punya semua petunjuknya.",
  ui_story_5024_50240601_33_dialog_content = "Kita harus mencoba.",
  ui_story_5024_50240601_34_dialog_content = "Namun, jangan berharap terlalu banyak.",
  ui_story_5024_50240601_35_dialog_content = "Dia sangat bersikeras tak mau membahas tentang Theater.",
  ui_story_5024_50240601_36_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_5024_50240601_37_dialog_content = "Apa yang kaulakukan… Ini bukan Anjing Baik yang Mengantuk… Ini kisah lain!",
  ui_story_5024_50240601_38_dialog_content = "Aku tak mau lagi jadi bagian darinya… Biarkan aku pergi… Biarkan aku pergi…",
  ui_story_5024_50240601_39_dialog_content = "Syarat apa pun akan kuterima…",
  ui_story_5024_50240601_40_dialog_content = "Apa kalian merasa di sini jadi gelap?",
  ui_story_5024_50240601_41_dialog_content = "Apa benar barusan koridor ini terasa sangat gelap?",
  ui_story_5024_50240601_42_dialog_content = "Mungkin karena sudutnya. Barangkali sinar mataharinya terhalang?",
  ui_story_5024_50240601_43_dialog_content = "Omong-omong, sekarang jam berapa?",
  ui_story_5024_50240601_44_dialog_content = "Entahlah. Maksudku, tadi kan aku terbangun tiba-tiba.",
  ui_story_5024_50240601_45_dialog_content = "Coba kita lihat ke luar jendela…",
  ui_story_5024_50240601_46_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5024_50240601_47_dialog_content = "Hah? Apa ini?",
  ui_story_5024_50240601_48_dialog_content = "Di luar jendela ini… langit, bukan?",
  ui_story_5024_50240601_49_dialog_content = "Jangan-jangan itu hanya kertas penghias dinding, sama seperti di dalam elevator itu?",
  ui_story_5024_50240601_50_dialog_content = "Bukan. Di Manor of Truth, itu memang langit.",
  ui_story_5024_50240601_51_dialog_content = "Dunia yang sangat jauh dari biasa tak butuh langit yang biasa-biasa saja.",
  ui_story_5024_50240601_52_dialog_content = "Makna keberadaannya hanyalah untuk menyambut pertunjukan ulang akbar itu.",
  ui_story_5024_50240601_53_dialog_content = "Pertunjukan ulang… pertunjukan ulang…",
  ui_story_5024_50240601_54_dialog_content = "Kita tak berhasil menyelesaikan pertunjukan ulangnya…",
  ui_story_5024_50240601_55_dialog_content = "Kita gagal…",
  ui_story_5024_50240601_56_dialog_content = "Sebentar… Apa aku jadi gila?",
  ui_story_5024_50240601_57_dialog_content = "Di mana kita? Mana koridornya?",
  ui_story_5024_50240601_58_dialog_content = "Ini…",
  ui_story_5024_50240601_59_dialog_content = "<size=45>Apa itu?!</size>",
  ui_story_5024_50240601_60_dialog_content = "Awas!",
  ui_story_5024_50240601_61_dialog_content = "Berhasil! Maaf sebesar-besarnya, ya!",
  ui_story_5024_50240601_62_dialog_content = "Aku tak menyangka kalian akan mengalami hal ini secepat itu.",
  ui_story_5024_50240601_63_dialog_content = "Kau… Sebaiknya kaujelaskan.",
  ui_story_5024_50240601_64_dialog_content = "Tempat apa ini?",
  ui_story_5024_50240601_65_dialog_content = "Ini adalah <color=#FFB400>mimpi buruk</color> Giles.",
  ui_story_5024_50240601_66_dialog_content = "Mimpi buruk?",
  ui_story_5024_50240601_67_dialog_content = "Kau pasti bercanda. Memangnya tak ada lelucon yang lebih bagus, ya?",
  ui_story_5024_50240601_68_dialog_content = "Aku tahu ini sulit dipahami, tapi akal sehat tak ada gunanya di Manor of Truth.",
  ui_story_5024_50240601_69_dialog_content = "Pertunjukan ulang Anjing Baik yang Mengantuk adalah makna dari keberadaan Manor of Truth.",
  ui_story_5024_50240601_70_dialog_content = "Aturan, atau kebenaran, di sini didasarkan pada lagu itu.",
  ui_story_5024_50240601_71_dialog_content = "Giles sedang mengingat pengalamannya saat mempertunjukkan Anjing Baik yang Mengantuk.",
  ui_story_5024_50240601_72_dialog_content = "Mimpi ini adalah salah satu dari sedikit hal yang nyata di Manor of Truth.",
  ui_story_5024_50240601_73_dialog_content = "Mimpi ini mungkin bahkan lebih nyata daripada kasur tempat kalian tidur, makanan yang kalian makan, atau bahkan diri kalian sendiri.",
  ui_story_5024_50240601_74_dialog_content = "Itulah sebabnya mimpi buruk ini mewujudkan diri dan menyeret kalian semua ke dalamnya.",
  ui_story_5024_50240601_75_dialog_content = "Perwujudan mimpi buruk… Maaf, tapi aku sama sekali tak percaya omong kosong ini.",
  ui_story_5024_50240601_76_dialog_content = "Yang kulihat adalah bahwa semua kenyamanan dan kebahagiaan yang kaujanjikan itu hanyalah dusta.",
  ui_story_5024_50240601_77_dialog_content = "Jadi, bagaimana kita bisa kembali ke… dunia yang tak biasa itu?",
  ui_story_5024_50240601_78_dialog_content = "Bantu Giles mengalahkan mimpi buruknya dan bangun dari tidurnya.",
  ui_story_5024_50240601_79_dialog_content = "Baiklah. Ini terakhir kalinya aku mau berbuat sesuatu dalam perjalanan konyol ini.",
  ui_story_5024_50240702_1_dialog_content = "Ice Blossom! Menyebar!",
  ui_story_5024_50240702_2_dialog_content = "Nah… Akhirnya kita kembali!",
  ui_story_5024_50240702_3_dialog_content = "Berkat kalian, mimpi buruk Giles akhirnya berakhir.",
  ui_story_5024_50240702_4_dialog_content = "Bukan masalah. PlayerName, ayo pergi.",
  ui_story_5024_50240702_5_dialog_content = "Hah? Pergi ke mana?",
  ui_story_5024_50240702_6_dialog_content = "Keluar dari sini dan kembali ke Lumopolis.",
  ui_story_5024_50240702_7_dialog_content = "Kalian membawa ancaman tak dikenal seperti ini ke Luminous…",
  ui_story_5024_50240702_8_dialog_content = "Ternyata Manor of Truth dan True Order bukannya tak punya salah sama sekali.",
  ui_story_5024_50240702_9_dialog_content = "Hukum Lumopolis tak akan pernah mengizinkan berdirinya tempat semacam ini.",
  ui_story_5024_50240702_10_dialog_content = "Kurasa kau masih belum paham, Carleen.",
  ui_story_5024_50240702_11_dialog_content = "Biar Hall of Justice saja yang memutuskannya.",
  ui_story_5024_50240702_12_dialog_content = "<color=#e8d9bb>Kriek…</color>",
  ui_story_5024_50240702_13_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5024_50240702_14_dialog_content = "Carleen, apa kita akan kembali tanpa Gretel?",
  ui_story_5024_50240702_15_dialog_content = "Tidak. Aku akan membawa bala bantuan untuk kita.",
  ui_story_5024_50240702_16_dialog_content = "Namun, tempat bernama Manor of Truth ini harus dikendalikan.",
  ui_story_5024_50240702_17_dialog_content = "Kalau tempat ini bisa menciptakan bahaya sebesar itu tanpa alasan, tak seorang pun bisa memperkirakan apa yang akan dilakukannya di kemudian hari.",
  ui_story_5024_50240702_18_dialog_content = "Kalau mimpi buruk ini sampai meluas dan menyeret warga Lumopolis… Akibatnya adalah malapetaka.",
  ui_story_5024_50240702_19_dialog_content = "Benar… Kalau kita tak bisa memahami cara kerjanya, kita juga tak akan bisa memperkirakan apa yang akan dilakukannya.",
  ui_story_5024_50240702_20_dialog_content = "Hal yang berpotensi mengancam harus ditangani sesegera mungkin.",
  ui_story_5024_50240702_21_dialog_content = "Namun, berdasarkan kata-kata Faust, kalau kita ingin masuk lagi ke sana, berarti harus saat tengah malam berikutnya…",
  ui_story_5024_50240702_22_dialog_content = "Tak apa. Kita butuh waktu untuk mengumpulkan bantuan dan melaporkannya ke Lumopolis Gardens.",
  ui_story_5024_50240702_23_dialog_content = "Sementara itu, kita akan sangat sibuk.",
  ui_story_5024_50240702_24_dialog_content = "<color=#e8d9bb>*gemuruh*</color>",
  ui_story_5024_50240702_25_dialog_content = "Ini dia. Kita akan pergi…",
  ui_story_5024_50240702_26_dialog_content = "<color=#e8d9bb>Kriek…</color>",
  ui_story_5024_50240702_27_dialog_content = "Selamat datang kembali, tamu-tamu terhormat.",
  ui_story_5024_50240702_28_dialog_content = "Apa-apaan!? Kukira barusan kita…",
  ui_story_5024_50240702_29_dialog_content = "Sebenarnya tadi aku ingin memberi tahu kalian, tapi mungkin lebih baik kalian mengalaminya sendiri.",
  ui_story_5024_50240702_30_dialog_content = "Kalian tak bisa pergi dari <color=#FFB400>Manor of Truth</color>.",
  ui_story_5024_50240702_31_dialog_content = "Tak bisa pergi!?",
  ui_story_5024_50240702_32_dialog_content = "Sekarang, permainan apa lagi yang kaumainkan…?",
  ui_story_5024_50240702_33_dialog_content = "Tak ada permainan. Seperti yang kalian lihat, semua orang terperangkap di Manor of Truth.",
  ui_story_5024_50240702_34_dialog_content = "Hanya saja, sebagian dari kami tak keberatan.",
  ui_story_5024_50240702_35_dialog_content = "Pertunjukan ulang Anjing Baik yang Mengantuk adalah makna keberadaan Manor of Truth.",
  ui_story_5024_50240702_36_dialog_content = "Kita tak akan bisa pergi ke mana-mana sampai pertunjukan ulang itu ditampilkan.",
  ui_story_5024_50240702_37_dialog_content = "Kalau begitu, kapan pertunjukan ulangnya?",
  ui_story_5024_50240702_38_dialog_content = "Segera setelah semua aktor sudah berkumpul di Theater.",
  ui_story_5024_50240702_39_dialog_content = "Kalian sedang mencari Gretel, yang berhasil masuk ke Theater, 'kan?",
  ui_story_5024_50240702_40_dialog_content = "Kurasa kalian bisa menganggap ini semacam permainan.",
  ui_story_5024_50240702_41_dialog_content = "Kalau kalian menang, kalian akan menemukan Gretel dan bisa pergi dari Manor of Truth bersama-sama.",
  ui_story_5024_50240702_42_dialog_content = "Sederhana, 'kan?",
  ui_story_5024_50240702_43_dialog_content = "Bagaimana kalau kami kalah?",
  ui_story_5024_50240702_44_dialog_content = "Kami tak pernah menanyakan apa yang akan terjadi kalau kami kalah.",
  ui_story_5024_50240702_45_dialog_content = "Kalau begitu, permainan ini justru terdengar makin menyeramkan!",
  ui_story_5024_50240702_46_dialog_content = "Baiklah. Kami akan ikuti permainannya.",
  ui_story_5024_50240702_47_dialog_content = "Eh? Carleen!?",
  ui_story_5024_50240702_48_dialog_content = "Toh kita memang akan terperangkap dalam permainan konyol ini, 'kan.",
  ui_story_5024_50240702_49_dialog_content = "Sekalian saja aku berusaha menang secepat mungkin.",
  ui_story_5024_50240702_50_dialog_content = "Terima kasih atas pengertianmu, Carleen.",
  ui_story_5024_50240702_51_dialog_content = "Mestinya sekarang Giles sudah bangun. Akan kuantar kalian menemuinya.",
  ui_story_5024_50240702_52_dialog_content = "Dia adalah kunci unik kita.",
  ui_story_5024_50240702_53_dialog_content = "<color=#e8d9bb>Ta… ta… ta…</color>",
  ui_story_5024_50240702_54_dialog_content = "Kalau benar semua orang terperangkap di sini, kenapa tak seorang pun tampak takut?",
  ui_story_5024_50240702_55_dialog_content = "Ada banyak buku di Manor of Truth. Pengetahuan tak terbatas saja sudah cukup untuk mengisi waktu kami.",
  ui_story_5024_50240702_56_dialog_content = "Namun, dibandingkan terperangkap di sini, sebenarnya mereka lebih memikirkan cara untuk masuk ke Theater.",
  ui_story_5024_50240702_57_dialog_content = "Kalau pertunjukan yang tak ada duanya itu mampu mengubah aturan dan menciptakan Manor of Truth ini…",
  ui_story_5024_50240702_58_dialog_content = "Berarti, rahasia yang tersembunyi di dalamnya pastilah bisa memberikan sedikit pengetahuan tentang kebenaran.",
  ui_story_5024_50240702_59_dialog_content = "Jadi, rupanya kau juga ingin masuk ke Theater?",
  ui_story_5024_50240702_60_dialog_content = "Bukan aku. Sama seperti Victoria, aku hanya ingin melihat hasil dari semua ini.",
  ui_story_5024_50240702_61_dialog_content = "Hasil dari pertunjukan ulang ini justru lebih menarik daripada Theater itu sendiri.",
  ui_story_5024_50240702_62_dialog_content = "Berarti, kau membantu kami hanya agar kau bisa melihat hasilnya?",
  ui_story_5024_50240702_63_dialog_content = "Memangnya tak boleh ya aku membantu kalian semata karena kita saling kenal, PlayerName?",
  ui_story_5024_50240702_64_dialog_content = "Aku hanya ingin membantumu mencari temanmu itu.",
  ui_story_5024_50240702_65_dialog_content = "Di sini. Ini kamar Giles.",
  ui_story_5024_50240702_66_dialog_content = "<color=#e8d9bb>*Kriek*</color>",
  ui_story_5024_50240702_67_dialog_content = "Jangan bertanya lagi! Aku tak mau bilang!",
  ui_story_5024_50240702_68_dialog_content = "Namun…",
  ui_story_5024_50240702_69_dialog_content = "Aku tak mau, aku tak mau, aku tak mau!",
  ui_story_5024_50240702_70_dialog_content = "Isaac, singkirkan mereka!",
  ui_story_5024_50240702_71_dialog_content = "<anim type=Shake>Meeeehhhh!</anim>",
  ui_story_5024_50240702_72_dialog_content = "<anim type=Shake>Hiss…</anim>",
  ui_story_5024_50240702_73_dialog_content = "Hoi, dia membuat Beau takut!",
  ui_story_5024_50240702_74_dialog_content = "Betapa bersemangatnya…",
  ui_story_5024_50240702_75_dialog_content = "Giles, merekalah yang berhasil membangunkanmu dari mimpi burukmu.",
  ui_story_5024_50240702_76_dialog_content = "Tak bisakah kau bicara dengan mereka?",
  ui_story_5024_50240702_77_dialog_content = "Setidaknya, bantu mereka memahami alasanmu.",
  ui_story_5024_50240702_78_dialog_content = "Oh, rupanya kalian menolongku. Pantas saja kali ini mimpi burukku singkat sekali.",
  ui_story_5024_50240702_79_dialog_content = "Isaac, sampaikan rasa terima kasihku kepada mereka.",
  ui_story_5024_50240702_80_dialog_content = "<anim type=Shake>Meeeehhhh!</anim>",
  ui_story_5024_50240702_81_dialog_content = "(Suaranya terdengar sama saja dengan yang tadi…)",
  ui_story_5024_50240702_82_dialog_content = "Sebenarnya, kami ingin tahu cara untuk masuk ke…",
  ui_story_5024_50240702_83_dialog_content = "Ssst!",
  ui_story_5024_50240702_84_dialog_content = "Jangan sebut kata itu. Kalau tidak, nanti dia mengamuk lagi.",
  ui_story_5024_50240702_85_dialog_content = "Kalau begitu… Aku harus bertanya dengan cara apa?",
  ui_story_5024_50240702_86_dialog_content = "Giles, bagaimana kalau kauceritakan apa yang terjadi kepadamu?",
  ui_story_5024_50240702_87_dialog_content = "Apa yang terjadi saat pertunjukan ulang Anjing Baik yang Mengantuk tahun lalu?",
  ui_story_5024_50240702_88_dialog_content = "…",
  ui_story_5024_50240702_89_dialog_content = "Itu bukan cerita yang bagus.",
  ui_story_5024_50240702_90_dialog_content = "Tak apa. Kami tetap ingin tahu, kok.",
  ui_story_5024_50240702_91_dialog_content = "…",
  ui_story_5024_50240702_92_dialog_content = "Biar kumulai dari diriku sendiri.",
  ui_story_5024_50240702_93_dialog_content = "Sejak lahir, aku sudah tahu cara menyanyikan Anjing Baik yang Mengantuk. Sepertinya kami lahir bersamaan.",
  ui_story_5024_50240702_94_dialog_content = "Dulu, aku sangat suka dongeng itu, dan aku menceritakannya kepada semua orang.",
  ui_story_5024_50240702_95_dialog_content = "Aku berangan-angan bisa mempertunjukkannya di panggung dan ditonton oleh jutaan orang.",
  ui_story_5024_50240702_96_dialog_content = "Saat usiaku tiga tahun, dongeng itu diangkat menjadi drama, tapi pertunjukannya gagal.",
  ui_story_5024_50240702_97_dialog_content = "Aku kecewa. Aku pun terus menantikan pertunjukan ulangnya.",
  ui_story_5024_50240702_98_dialog_content = "Lalu, tahun lalu, akhirnya pertunjukan ulang itu digelar.",
  ui_story_5024_50240702_99_dialog_content = "Apa itu pertunjukan ulang terakhir?",
  ui_story_5024_50240702_100_dialog_content = "Sama seperti tahun ini, kami menerima undangan dan masuk ke sini dari Midnight Street.",
  ui_story_5024_50240702_101_dialog_content = "Pada akhirnya, ada lima orang yang berhasil masuk ke Theater. Aku salah satunya.",
  ui_story_5024_50240702_102_dialog_content = "Misi kami adalah mempertunjukkan Anjing Baik yang Mengantuk sebagai aktor dan menuntaskan pertunjukan ulangnya.",
  ui_story_5024_50240702_103_dialog_content = "Masing-masing dari kami diberi tugas memerankan salah satu tokoh.",
  ui_story_5024_50240702_104_dialog_content = "Dramanya sendiri tak panjang. Sama sekali tak sulit.",
  ui_story_5024_50240702_105_dialog_content = "Namun, kami tak berhasil menuntaskannya… Kami tak mungkin bisa…",
  ui_story_5024_50240702_106_dialog_content = "…",
  ui_story_5024_50240702_107_dialog_content = "Begitu kami menginjakkan kaki di atas panggung, kami berubah…",
  ui_story_5024_50240702_108_dialog_content = "Awalnya kami \"memerankan\" tokoh, tapi kemudian kami malah \"menjadi\" tokoh itu sendiri.",
  ui_story_5024_50240702_109_dialog_content = "Si pemeran kucing mulai menjilati bulunya sendiri.",
  ui_story_5024_50240702_110_dialog_content = "Si pemeran anak domba mulai mengunyah pakan kering.",
  ui_story_5024_50240702_111_dialog_content = "Si pemeran burung hantu salju memutar kepalanya sampai 180 derajat.",
  ui_story_5024_50240702_112_dialog_content = "Namun, salah seorang dari kami yang berhasil masuk ke Theater mulai membunuh para pemeran lainnya…",
  ui_story_5024_50240702_113_dialog_content = "Aku memerankan si tokoh utama, Anjing Baik yang Mengantuk… Namun, aku tak tahu cara untuk membuat pertunjukannya kembali terkendali.",
  ui_story_5024_50240702_114_dialog_content = "Mereka melenceng dari naskah, seakan-akan merekalah tokoh utamanya.",
  ui_story_5024_50240702_115_dialog_content = "Semua jadi gila.",
  ui_story_5024_50240702_116_dialog_content = "Yang dipertunjukkan di atas panggung adalah hal yang tak bisa dinalar, mengejutkan, dan sama sekali tak indah…",
  ui_story_5024_50240702_117_dialog_content = "Pertunjukannya gagal total. Satu-satunya harapanku untuk selamat adalah dengan pergi dari sana.",
  ui_story_5024_50240702_118_dialog_content = "Namun, syarat yang harus kupenuhi agar aku bisa pergi adalah bahwa aku harus menjadi promotor untuk menarik lebih banyak orang untuk menonton Anjing Baik yang Mengantuk…",
  ui_story_5024_50240702_119_dialog_content = "Rupanya itulah sebabnya kau sebenarnya enggan melantunkan lagu itu saat jamuan makan!",
  ui_story_5024_50240702_120_dialog_content = "Sekarang kalian percaya kepadaku? Kalian tak boleh masuk ke sana. Tak seorang pun boleh masuk ke sana.",
  ui_story_5024_50240702_121_dialog_content = "Siapa pun yang masuk ke sana akan jadi gila total…",
  ui_story_5024_50240702_122_dialog_content = "Aku tak boleh… membiarkan kalian mengalaminya…",
  ui_story_5024_50240702_123_dialog_content = "Tidak apa. Lenore tidak takut.",
  ui_story_5024_50240702_124_dialog_content = "Lenore harus mencari Ibu. Itu saja sudah cukup untuk Lenore.",
  ui_story_5024_50240702_125_dialog_content = "Kau mencari… ibumu?",
  ui_story_5024_50240702_126_dialog_content = "Ya. Tahun lalu, Ibu pergi menonton Anjing Baik yang Mengantuk, dan tak pernah pulang sejak itu.",
  ui_story_5024_50240702_127_dialog_content = "Ibu pasti ada di Theater.",
  ui_story_5024_50240702_128_dialog_content = "Ibu… Ibu…",
  ui_story_5024_50240702_129_dialog_content = "Benar, dia masuk ke Theater itu bersama Ibu!",
  ui_story_5024_50240702_130_dialog_content = "Pasti dia pernah melihat Ibu!",
  ui_story_5024_50240702_131_dialog_content = "Sekarang aku ingat… Seorang wanita paruh baya memerankan si anak domba…",
  ui_story_5024_50240702_132_dialog_content = "Dia selalu bilang, dia harus mengubah putrinya kembali menjadi Aurorian!",
  ui_story_5024_50240702_133_dialog_content = "Mengubah kembali menjadi Aurorian! Itu pasti Lenore!",
  ui_story_5024_50240702_134_dialog_content = "Rupanya dulu Lenore adalah Aurorian… Bagaimana mungkin bisa jadi begini?",
  ui_story_5024_50240702_135_dialog_content = "…",
  ui_story_5024_50240702_136_dialog_content = "Lenore harus mencari Ibu.",
  ui_story_5024_50240702_137_dialog_content = "Kalau dia memang benar ibumu…",
  ui_story_5024_50240702_138_dialog_content = "Namun, kalaupun dia masih hidup, pasti dia sudah tak seperti yang kaukenal dulu…",
  ui_story_5024_50240702_139_dialog_content = "Tidak apa. Lenore harus mencari Ibu.",
  ui_story_5024_50240702_140_dialog_content = "Ibu bilang, setiap kali Lenore tidak tahu apa yang harus dilakukan, Lenore harus mencarinya.",
  ui_story_5024_50240702_141_dialog_content = "Lenore akan selalu mematuhi perintah ini.",
  ui_story_5024_50240702_142_dialog_content = "…",
  ui_story_5024_50240702_143_dialog_content = "Baiklah, akan kuberitahukan cara masuk ke Theater.",
  ui_story_5024_50240702_144_dialog_content = "Eh! A-Aku juga harus mencari ibuku!",
  ui_story_5024_50240702_145_dialog_content = "Aku harus jadi yang pertama… Aku akan mencari Ibu lebih dulu daripada Lenore!",
  ui_story_5024_50240702_146_dialog_content = "Kami juga! Kami juga harus mencari seseorang!",
  ui_story_5024_50240702_147_dialog_content = "Orang-orang dungu tak berpengetahuan di Manor of Truth ini juga sudah mendengar ceritaku…",
  ui_story_5024_50240702_148_dialog_content = "Namun, mereka menganggap apa yang terjadi di atas panggung itu bukan hal gila.",
  ui_story_5024_50240702_149_dialog_content = "Mereka mendambakan panggung itu dengan alasan untuk menerima kebenaran.",
  ui_story_5024_50240702_150_dialog_content = "Namun… kalian tak seperti mereka, 'kan?",
  ui_story_5024_50240702_151_dialog_content = "Kalian merasakan sendiri ketakutanku dan kalian tahu apa yang akan terjadi kalau kalian masuk ke sana.",
  ui_story_5024_50240702_152_dialog_content = "Kalian sudah tahu risikonya, tapi tetap bersikeras ingin menyelamatkan seseorang yang ada di dalam sana…",
  ui_story_5024_50240702_153_dialog_content = "Kalau begitu, aku tak akan menghalangi kalian untuk mendapatkan kesempatan yang memang layak kalian dapatkan ini.",
  ui_story_5024_50240702_154_dialog_content = "Nah, kalian semua yang bertekad bulat, ikutlah aku ke Theater.",
  ui_story_5024_50240801_1_dialog_content = "Aku tak mengira kita semua boleh masuk…",
  ui_story_5024_50240801_2_dialog_content = "Rupanya satu-satunya orang yang tak bertekad bulat akhirnya muncul, ya!?",
  ui_story_5024_50240801_3_dialog_content = "Eh, aku bertekad bulat, kok!",
  ui_story_5024_50240801_4_dialog_content = "Memangnya perkataan Giles tak membuatmu takut?",
  ui_story_5024_50240801_5_dialog_content = "Kalau di dalam sana memang benar seperti apa yang dikatakan Giles, berarti kita tak boleh membiarkan Gretel di dalam sana.",
  ui_story_5024_50240801_6_dialog_content = "Bagaimana denganmu? Memangnya kau tak takut?",
  ui_story_5024_50240801_7_dialog_content = "Tak ada yang perlu ditakuti. Aku hanya ingin mengakhiri permainan konyol ini sesegera mungkin.",
  ui_story_5024_50240801_8_dialog_content = "Kita sudah sampai.",
  ui_story_5024_50240801_9_dialog_content = "Theater ada di balik pintu ini.",
  ui_story_5024_50240801_10_dialog_content = "Theater… Ibu ada di dalam sana.",
  ui_story_5024_50240801_11_dialog_content = "Seperti yang kalian lihat, pintu ini selalu tertutup.",
  ui_story_5024_50240801_12_dialog_content = "Tak bisa dibuka paksa dan tak ada kuncinya.",
  ui_story_5024_50240801_13_dialog_content = "Pintu ini hanya akan terbuka untuk para aktor yang akan berperan dalam Anjing Baik yang Mengantuk.",
  ui_story_5024_50240801_14_dialog_content = "Oh? Jadi, asalkan kami setuju untuk memerankan salah satu tokoh, berarti kami bisa masuk?",
  ui_story_5024_50240801_15_dialog_content = "Tentu saja tidak! Sekarang saja, kalian bahkan tak tampak menyerupai peran kalian!",
  ui_story_5024_50240801_16_dialog_content = "Apa?",
  ui_story_5024_50240801_17_dialog_content = "Apa? Apa yang aneh? Kalau mau memerankan suatu tokoh, pertama-tama penampilan kalian harus menyerupai tokoh itu!",
  ui_story_5024_50240801_18_dialog_content = "Jadi, kami harus mengenakan kostum seperti tokoh yang akan kami perankan?",
  ui_story_5024_50240801_19_dialog_content = "Ya. Anak domba, kucing, burung hantu salju, dan anjing yang mengantuk.",
  ui_story_5024_50240801_20_dialog_content = "Bagaimana caranya? Cukup pakai kostum berbulu?",
  ui_story_5024_50240801_21_dialog_content = "Memangnya kaukira ini permainan anak-anak?",
  ui_story_5024_50240801_22_dialog_content = "Kedengarannya kan memang seperti itu…",
  ui_story_5024_50240801_23_dialog_content = "Siapa pun yang memerankan si anak domba haruslah orang yang berkepribadian patuh dan rela mengorbankan diri demi orang lain.",
  ui_story_5024_50240801_24_dialog_content = "Si kucing punya kepribadian penasaran dan serba ingin tahu apa yang sedang dilakukan orang lain.",
  ui_story_5024_50240801_25_dialog_content = "Si burung hantu salju punya kepribadian egois dan congkak, selalu ingin tampil sama baiknya dengan orang lain.",
  ui_story_5024_50240801_26_dialog_content = "Ada banyak orang berkepribadian seperti itu di True Order.",
  ui_story_5024_50240801_27_dialog_content = "Hah? Aku jadi bingung…",
  ui_story_5024_50240801_28_dialog_content = "Sekarang aku mulai paham kenapa Giles selalu menyamakan kita dengan binatang.",
  ui_story_5024_50240801_29_dialog_content = "Anak domba, kucing, dan burung hantu salju mewakili tipe kepribadian manusia.",
  ui_story_5024_50240801_30_dialog_content = "Dibagi-bagi menjadi beberapa kategori berdasarkan pemahaman tentang keyakinan kita.",
  ui_story_5024_50240801_31_dialog_content = "Keyakinan?",
  ui_story_5024_50240801_32_dialog_content = "First Faction di True Order meyakini persembahan korban untuk True God dan hidup menurut harapan-Nya.",
  ui_story_5024_50240801_33_dialog_content = "Menurut Giles, orang seperti ini termasuk kategori \"Anak Domba\".",
  ui_story_5024_50240801_34_dialog_content = "Second Faction memuja pengetahuan dan berharap bisa memahami mekanisme dunia.",
  ui_story_5024_50240801_35_dialog_content = "Orang seperti ini adalah \"Kucing\".",
  ui_story_5024_50240801_36_dialog_content = "Lalu, ada juga para petapa penyendiri yang tak termasuk faksi mana pun.",
  ui_story_5024_50240801_37_dialog_content = "Mereka adalah Burung Hantu Salju.",
  ui_story_5024_50240801_38_dialog_content = "Benar! Sekarang aku paham!",
  ui_story_5024_50240801_39_dialog_content = "Nah, bagaimana kita akan memerankan mereka… Dengan menerima metode mereka dalam menunjukkan keyakinannya?",
  ui_story_5024_50240801_40_dialog_content = "Menerima keyakinan True Order? Yang benar saja!",
  ui_story_5024_50240801_41_dialog_content = "Kurasa bukan begitu. Kalau memang itulah cara untuk masuk ke Theater, mestinya dari tadi kita sudah berhasil membuka pintu ini.",
  ui_story_5024_50240801_42_dialog_content = "Namun, sampai sekarang, yang berhasil masuk hanyalah Gretel, yang bukan anggota True Order…",
  ui_story_5024_50240801_43_dialog_content = "Tokoh di atas panggung dan aktor yang memerankannya adalah orang yang berbeda!",
  ui_story_5024_50240801_44_dialog_content = "Semua orang yang pernah menonton drama pasti tahu soal itu!",
  ui_story_5024_50240801_45_dialog_content = "Pemeran raja di atas panggung kan bukan raja betulan.",
  ui_story_5024_50240801_46_dialog_content = "Bahkan kalaupun tokoh raja diperankan oleh seorang raja betulan, belum tentu dia bisa memerankannya dengan lebih baik.",
  ui_story_5024_50240801_47_dialog_content = "Yang bisa memerankan tokoh tertentu hanyalah aktor yang bisa sepenuhnya memahami esensi dari tokoh itu.",
  ui_story_5024_50240801_48_dialog_content = "Dongeng Anjing Baik yang Mengantuk sebenarnya sederhana, begitu pula kepribadian para tokohnya.",
  ui_story_5024_50240801_49_dialog_content = "Yang kita butuhkan hanyalah memahami suatu \"simbol\" sederhana yang mencerminkan tokoh itu.",
  ui_story_5024_50240801_50_dialog_content = "Uhh… lalu?",
  ui_story_5024_50240801_51_dialog_content = "Bagaimana caranya?",
  ui_story_5024_50240801_52_dialog_content = "Coba cari ilham dari kehidupan nyata.",
  ui_story_5024_50240801_53_dialog_content = "Coba <color=#FFB400>tanyai si kucing</color>, <color=#FFB400>bantu si anak domba</color>, <color=#FFB400>kalahkan si burung hantu salju</color>, dan tariklah ilham dari mereka.",
  ui_story_5024_50240801_54_dialog_content = "Tanyai si kucing, bantu si anak domba, kalahkan si burung hantu salju…",
  ui_story_5024_50240801_55_dialog_content = "Akan lebih mudah jadinya seandainya saja binatang-binatang itu adalah manusia sungguhan…",
  ui_story_5024_50240801_56_dialog_content = "Namun, tetap saja itu gambaran yang abstrak.",
  ui_story_5024_50240801_57_dialog_content = "Tanyai si kucing. Beau seekor kucing.",
  ui_story_5024_50240801_58_dialog_content = "Bukan!",
  ui_story_5024_50240801_59_dialog_content = "Bukan… tapi iya… tapi…",
  ui_story_5024_50240801_60_dialog_content = "Uhh… seekor kucing dan \"si kucing\" itu beda. Paham, tidak?",
  ui_story_5024_50240801_61_dialog_content = "Sama seperti Isaac adalah seekor anak domba, tapi Isaac bukan \"si anak domba\"!",
  ui_story_5024_50240801_62_dialog_content = "Penjelasanmu malah makin membingungkan!",
  ui_story_5024_50240801_63_dialog_content = "Beau, bagaimana kami bisa masuk ke Theater?",
  ui_story_5024_50240801_64_dialog_content = "Kau… tetap saja mencobanya…",
  ui_story_5024_50240801_65_dialog_content = "Meong…",
  ui_story_5024_50240801_66_dialog_content = "Aku mengerti.",
  ui_story_5024_50240801_67_dialog_content = "Hah? Apa katanya?",
  ui_story_5024_50240801_68_dialog_content = "Beau menyuruhku mendorong pintunya.",
  ui_story_5024_50240801_69_dialog_content = "Itulah yang dilakukannya kalau dia terkunci di kamar tidur.",
  ui_story_5024_50240801_70_dialog_content = "Hah? A-Aku tak tahu soal itu…",
  ui_story_5024_50240801_71_dialog_content = "Sudah kubilang dia bukan \"si Kucing\"! Lagi pula, kau tak bisa membuka pintunya dengan cara itu…",
  ui_story_5024_50240801_72_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5024_50240801_73_dialog_content = "B-Bagaimana mungkin…?",
  ui_story_5024_50240801_74_dialog_content = "Pintunya… terbuka.",
  ui_story_5024_50240801_75_dialog_content = "Lenore tidak mendorongnya.",
  ui_story_5024_50240801_76_dialog_content = "Pintunya mendorong Lenore.",
  ui_story_5024_50240801_77_dialog_content = "Benda apa itu? Maneken?",
  ui_story_5024_50240801_78_dialog_content = "Mereka menarik Lenore!",
  ui_story_5024_50240801_79_dialog_content = "<size=45>Lenore!</size>",
  ui_story_5024_50240801_80_dialog_content = "Keluarlah dari sana!",
  ui_story_5024_50240801_81_dialog_content = "Tidak… Mestinya tak seperti ini…",
  ui_story_5024_50240801_82_dialog_content = "Yang kulihat dulu bukan seperti ini… Mestinya tak seperti ini…",
  ui_story_5024_50240801_83_dialog_content = "Dia bukan aktor! Dia… suatu makhluk lain, entah apa…",
  ui_story_5024_50240801_84_dialog_content = "Sudahlah, cepat selamatkan dia!",
  ui_story_5024_50240801_85_dialog_content = "Lenore memang ingin masuk ke Theater, tapi bukan dengan cara mengerikan seperti itu!",
  ui_story_5024_50240801_86_dialog_content = "Apa Lenore… bisa bertemu Ibu?",
  ui_story_5024_50240802_1_dialog_content = "Lenore! Lenore!",
  ui_story_5024_50240802_2_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5024_50240802_3_dialog_content = "Pintu Theater tiba-tiba tertutup lagi…",
  ui_story_5024_50240802_4_dialog_content = "Pintunya terbuka… hanya untuk menarik Lenore masuk?",
  ui_story_5024_50240802_5_dialog_content = "Aku belum pernah lihat Theater ini menculik orang sebelumnya.",
  ui_story_5024_50240802_6_dialog_content = "Theater ini hidup… Pasti begitu.",
  ui_story_5024_50240802_7_dialog_content = "Dia menginginkan gadis maneken itu…",
  ui_story_5024_50240802_8_dialog_content = "Namun, kenapa?",
  ui_story_5024_50240802_9_dialog_content = "Apa kalian lihat maneken-maneken yang menariknya tadi itu?",
  ui_story_5024_50240802_10_dialog_content = "Tidakkah kalian merasa bahwa mereka agak mirip dengan Lenore?",
  ui_story_5024_50240802_11_dialog_content = "Maneken hidup di teater yang dipenuhi maneken…",
  ui_story_5024_50240802_12_dialog_content = "Mungkin saja sejak awal dia memang bagian dari Theater…",
  ui_story_5024_50240802_13_dialog_content = "Cukup… Ayo kita cari cara untuk menjadi aktornya.",
  ui_story_5024_50240802_14_dialog_content = "May…",
  ui_story_5024_50240802_14X1_dialog_content = "Baru pertama kali ini aku melihatmu begitu cemas… Kau pasti mengkhawatirkan Lenore.",
  ui_story_5024_50240802_14X2_dialog_content = "Tidak mungkin!",
  ui_story_5024_50240802_14X3_dialog_content = "Hanya saja……",
  ui_story_5024_50240802_15_dialog_content = "Lagi-lagi dia mendahuluiku. Mestinya aku jadi yang pertama menemukan Ibu.",
  ui_story_5024_50240802_16_dialog_content = "Aku harus jadi yang pertama menemukan Ibu…",
  ui_story_5024_50240802_17_dialog_content = "Yah, tak ada gunanya berdiri di sini dan merasa frustrasi.",
  ui_story_5024_50240802_18_dialog_content = "Tanyai si kucing, bantu si anak domba, kalahkan si burung hantu salju… begitu, 'kan?",
  ui_story_5024_50240802_19_dialog_content = "Setidaknya, tak sulit menemukan ketiga hewan itu. Ikuti aku.",
  ui_story_5024_50240802_20_dialog_content = "\"Pus, pus, meong, kucing cantik, terangi semua tempat ini!\"",
  ui_story_5024_50240802_21_dialog_content = "\"Nyala lilin, bayangan hidup, bernyanyi bersama sampai fajar!\"",
  ui_story_5024_50240802_22_dialog_content = "Giles… Tak bisakah kau tak menyanyi di perpustakaan?",
  ui_story_5024_50240802_23_dialog_content = "Oh, Faust! Kalian semua juga… Kalian kemari untuk belajar?",
  ui_story_5024_50240802_24_dialog_content = "Beryl anggota Second Faction. Apa dia memenuhi kriteria untuk jadi si Kucing?",
  ui_story_5024_50240802_25_dialog_content = "Tentu saja iya!",
  ui_story_5024_50240802_26_dialog_content = "<color=#FFB400>Tanyai si kucing</color>, <color=#FFB400>tanyai si kucing</color>…",
  ui_story_5024_50240802_27_dialog_content = "…",
  ui_story_5024_50240802_28_dialog_content = "Anu… Beryl?",
  ui_story_5024_50240802_29_dialog_content = "Oh, May. Ada apa?",
  ui_story_5024_50240802_30_dialog_content = "Apa kau bisa memberitahuku cara memerankan seekor kucing…?",
  ui_story_5024_50240802_31_dialog_content = "…",
  ui_story_5024_50240802_32_dialog_content = "Meong?",
  ui_story_5024_50240802_33_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5024_50240802_34_dialog_content = "Bukan begitu maksudku… Maksudku…",
  ui_story_5024_50240802_35_dialog_content = "Coba bilang lebih spesifik. Logika Giles tak akan bisa dipahami oleh Beryl.",
  ui_story_5024_50240802_36_dialog_content = "Itu benar…",
  ui_story_5024_50240802_37_dialog_content = "Apa kau tahu cara masuk ke Theater, Beryl?",
  ui_story_5024_50240802_38_dialog_content = "Oh, itu… Aku sedang mencari caranya.",
  ui_story_5024_50240802_39_dialog_content = "Namun, aku belum yakin apa aku sudah menemukan solusi yang masuk akal…",
  ui_story_5024_50240802_40_dialog_content = "Untungnya, sekarang ini kita tak bisa keluar dari sini.",
  ui_story_5024_50240802_41_dialog_content = "Hah? Untungnya?",
  ui_story_5024_50240802_42_dialog_content = "Kita bisa terus membaca sambil minum teh di sini.",
  ui_story_5024_50240802_43_dialog_content = "Kita bahkan tak perlu mencuci cangkir dan piringnya.",
  ui_story_5024_50240802_44_dialog_content = "Kalau alat makannya kotor, kita hanya perlu pindah ke meja berikutnya.",
  ui_story_5024_50240802_45_dialog_content = "Jadi, terperangkap di Manor of Truth justru membuatmu merasa santai dan rileks…?",
  ui_story_5024_50240802_46_dialog_content = "Aku harus membaca lebih banyak buku… Ada banyak hal yang harus kupahami.",
  ui_story_5024_50240802_47_dialog_content = "Perpustakaan ini agak gelap. Tidak nyaman membaca di sini.",
  ui_story_5024_50240802_48_dialog_content = "Harus menyalakan banyak lilin agar perpustakaan ini terang!",
  ui_story_5024_50240802_49_dialog_content = "Woah! Kau mau membakar tempat ini, ya!?",
  ui_story_5024_50240802_50_dialog_content = "Cahaya lilin temaram hanya akan membutakan kita terhadap kebenaran.",
  ui_story_5024_50240802_51_dialog_content = "Aku butuh cahaya terang agar bisa melihat setiap kata dan setiap sudut dengan jelas.",
  ui_story_5024_50240802_52_dialog_content = "Begitu rupanya… Jadi, seperti itulah cara yang tepat untuk membaca, ya?",
  ui_story_5024_50240802_53_dialog_content = "Hmm… Dengan cara itulah kita bisa mencari jawaban agar bisa masuk ke Theater.",
  ui_story_5024_50240802_54_dialog_content = "Aku punya banyak lilin. Bisa kupinjamkan sebatang untuk May.",
  ui_story_5024_50240802_55_dialog_content = "Bawa ini. Cari buku yang ingin kaubaca.",
  ui_story_5024_50240802_56_dialog_content = "Kalau mau, kau boleh duduk bersamaku.",
  ui_story_5024_50240802_57_dialog_content = "Baiklah! Terima kasih, Beryl!",
  ui_story_5024_50240802_58_dialog_content = "Beryl memang luar biasa…",
  ui_story_5024_50240802_59_dialog_content = "Dia menyuruhku mencari buku yang ingin kubaca…",
  ui_story_5024_50240802_60_dialog_content = "Pasti buku itu berisi cara masuk ke Theater!",
  ui_story_5024_50240802_61_dialog_content = "Namun, yang mana bukunya…?",
  ui_story_5024_50240802_62_dialog_content = "Buku? Kenapa sekarang kita malah mencari buku?",
  ui_story_5024_50240802_63_dialog_content = "Hah? Memangnya bagaimana lagi kita bisa mencari jalan masuk ke Theater…?",
  ui_story_5024_50240802_64_dialog_content = "Kau sudah bisa masuk ke Theater sebagai pemeran si \"<color=#FFB400>Kucing</color>.\"",
  ui_story_5024_50240802_65_dialog_content = "Apa?!",
  ui_story_5024_50240802_66_dialog_content = "Kau kan sudah bertanya kepada si kucing, dan si kucing memberimu sebatang lilin.",
  ui_story_5024_50240802_67_dialog_content = "Lilin ini adalah simbol si kucing.",
  ui_story_5024_50240802_68_dialog_content = "Begitukah…? Bagiku saja, itu konyol.",
  ui_story_5024_50240802_69_dialog_content = "Ayo kita lanjutkan. Masih ada dua binatang.",
  ui_story_5024_50240802_70_dialog_content = "Si anak domba yang sedang bekerja dan si burung hantu salju yang egois.",
  ui_story_5024_50240901_1_dialog_content = "Karena sekarang aku sudah memenuhi syarat untuk masuk ke Theater… Aku akan masuk duluan.",
  ui_story_5024_50240901_2_dialog_content = "Aku khawatir dengan…",
  ui_story_5024_50240901_3_dialog_content = "Tidak. Aku harus menemukan Ibu lebih dulu daripada Lenore.",
  ui_story_5024_50240901_4_dialog_content = "Itu tak akan bisa. Pintunya hanya akan terbuka saat keempat pemeran Anjing Baik yang Mengantuk sudah ada.",
  ui_story_5024_50240901_5_dialog_content = "Empat?",
  ui_story_5024_50240901_6_dialog_content = "Ya. Anak domba, kucing, burung hantu salju, dan anjing yang mengantuk.",
  ui_story_5024_50240901_7_dialog_content = "Sebentar. Kau hanya memberi kami tiga petunjuk!",
  ui_story_5024_50240901_8_dialog_content = "Tanyai si kucing, bantu si anak domba, kalahkan si burung hantu salju. Bagaimana dengan si <color=#FFB400>anjing yang mengantuk</color>?",
  ui_story_5024_50240901_9_dialog_content = "Kalian tak perlu bingung tentang si anjing yang mengantuk.",
  ui_story_5024_50240901_10_dialog_content = "Dia akan muncul kalau waktunya sudah tepat.",
  ui_story_5024_50240901_11_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5024_50240901_12_dialog_content = "Kita mau ke mana?",
  ui_story_5024_50240901_13_dialog_content = "Dapur.",
  ui_story_5024_50240901_14_dialog_content = "Tak ada yang lebih pas dengan karakteristik si \"anak domba yang sedang bekerja\" selain dia.",
  ui_story_5024_50240901_15_dialog_content = "Anak domba… Bantu si anak domba…",
  ui_story_5024_50240901_16_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5024_50240901_17_dialog_content = "Suara apa itu…?",
  ui_story_5024_50240901_18_dialog_content = "Seperti suara logam menghantam kayu.",
  ui_story_5024_50240901_19_dialog_content = "Karena ini dapur, mungkin dia sedang memotongi sayuran.",
  ui_story_5024_50240901_20_dialog_content = "\"Si anak domba yang polos itu dungu.\"",
  ui_story_5024_50240901_21_dialog_content = "\"Terus mengenyangkan perutnya, padahal ada perut lapar lain yang menanti untuk menyantapnya!\"",
  ui_story_5024_50240901_22_dialog_content = "Jangan khawatir, Isaac. yang kumaksud bukan kau.",
  ui_story_5024_50240901_23_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5024_50240901_24_dialog_content = "<size=45>Woah!</size>",
  ui_story_5024_50240901_25_dialog_content = "Maaf! Aku membuat kalian takut, ya?",
  ui_story_5024_50240901_X25_dialog_content = "Nails, aku membawa beberapa tamu yang ingin menemuimu.",
  ui_story_5024_50240901_26_dialog_content = "Oh, rupanya PlayerName dan kawan-kawannya…",
  ui_story_5024_50240901_27_dialog_content = "Maaf, aku tak punya hidangan untuk menjamu kalian.",
  ui_story_5024_50240901_28_dialog_content = "Tak usah repot-repot! Namun…",
  ui_story_5024_50240901_29_dialog_content = "Kenapa kau berisik seperti itu?",
  ui_story_5024_50240901_30_dialog_content = "Kenapa kau berisik seperti itu?",
  ui_story_5024_50240901_31_dialog_content = "Aku sedang menyiapkan hidangan untuk jamuan makan.",
  ui_story_5024_50240901_32_dialog_content = "Kemarin, hidangannya tak berhasil membuka pintu Theater. Hidangannya salah.",
  ui_story_5024_50240901_33_dialog_content = "Aku harus menyiapkan hidangan yang tepat untuk semua orang…",
  ui_story_5024_50240901_34_dialog_content = "Memangnya ada hidangan yang salah dan yang tepat?",
  ui_story_5024_50240901_35_dialog_content = "\"Makan\" adalah ritual suci.",
  ui_story_5024_50240901_36_dialog_content = "Dewa memberi kita kehidupan dan membuat kita bisa bertahan hidup dengan cara makan.",
  ui_story_5024_50240901_37_dialog_content = "Jadi, kita harus memenuhi tugas suci ini dan bersyukur dengan memberikan persembahan bagi Dewa.",
  ui_story_5024_50240901_38_dialog_content = "\"Makan\" adalah satu-satunya hal yang paling dekat dengan sumber kehidupan dan Dewa.",
  ui_story_5024_50240901_39_dialog_content = "Makan tak boleh disalahgunakan semata untuk memuaskan nafsu. Makan adalah cara untuk menyempurnakan diri kita.",
  ui_story_5024_50240901_40_dialog_content = "Lalu, apa yang menentukan tepat atau tidaknya hidangan?",
  ui_story_5024_50240901_41_dialog_content = "Bahannya… Makanan yang dimasak dengan bahan-bahan surgawi.",
  ui_story_5024_50240901_42_dialog_content = "Bahan-bahan surgawi? Abstrak sekali… Bagaimana kita bisa menemukannya?",
  ui_story_5024_50240901_43_dialog_content = "Aku sudah menemukannya.",
  ui_story_5024_50240901_44_dialog_content = "Namun, mengubahnya menjadi bahan masakan mungkin akan agak sulit…",
  ui_story_5024_50240901_45_dialog_content = "Tak masalah buatku!",
  ui_story_5024_50240901_46_dialog_content = "Hal yang bagus memang biasanya tak mudah, 'kan?",
  ui_story_5024_50240901_47_dialog_content = "Kau mungkin tak akan percaya, tapi sebenarnya kami semua ke sini semata-mata untuk membantumu!",
  ui_story_5024_50240901_48_dialog_content = "Sungguh? Terima kasih atas kepedulianmu, Navigator…",
  ui_story_5024_50240901_49_dialog_content = "Namun, aku harus memperingatkan kalian. Berkutat di dapur kadang sangat melelahkan.",
  ui_story_5024_50240901_50_dialog_content = "Bukan masalah! Semangatku besar, kok!",
  ui_story_5024_50240901_51_dialog_content = "Bagus sekali. Kalau begitu, akan kubiarkan mereka keluar.",
  ui_story_5024_50240901_52_dialog_content = "M-Membiarkan mereka keluar…?",
  ui_story_5024_50240901_53_dialog_content = "<color=#e8d9bb>Kriek…</color>",
  ui_story_5024_50240901_54_dialog_content = "<anim type=Shake><size=45>*Meraung*</size></anim>",
  ui_story_5024_50240901_55_dialog_content = "Sebentar… Itu Eclipsite, 'kan?! Kau mau menjadikan Eclipsite sebagai bahan masakan?!",
  ui_story_5024_50240901_56_dialog_content = "Memang, monster-monster mengerikan ini mungkin adalah makhluk kelam ciptaan para dewa, tapi tetap saja mereka ini ciptaan yang istimewa.",
  ui_story_5024_50240901_57_dialog_content = "Nah, kalau begitu, PlayerName… Mari mulai.",
  ui_story_5024_50240901_58_dialog_content = "C-Carleen! Bersiaplah untuk bertarung!",
  ui_story_5024_50240901_59_dialog_content = "Kenapa harus aku…",
  ui_story_5024_50240902_1_dialog_content = "<anim type=Shake>Graah!</anim>",
  ui_story_5024_50240902_2_dialog_content = "Aku sangat menghargai bantuan kalian, kawan-kawan. Terima kasih.",
  ui_story_5024_50240902_3_dialog_content = "Sekarang kita tinggal menyesuaikan rasanya. Sekarang, serahkan saja sisanya kepadaku.",
  ui_story_5024_50240902_4_dialog_content = "Saat jamuan makannya dimulai, sepenuh hati kuminta kalian untuk mencicipi sendiri hidangan menakjubkan ini. Lagi pula, ini kan hasil dari upaya bersama kita…",
  ui_story_5024_50240902_5_dialog_content = "T-Namun… Apa kami harus mencicipinya? Maksudku, bahannya kan Eclipsite…",
  ui_story_5024_50240902_6_dialog_content = "Kalau kalian lebih suka yang lain, di dapur ini ada berbagai hidangan lain, sih…",
  ui_story_5024_50240902_7_dialog_content = "Misalnya hidangan di set peralatan makan dari perak ini. Anggap saja ini bayaran karena kalian sudah membantu.",
  ui_story_5024_50240902_8_dialog_content = "B-Baiklah! Terima kasih!",
  ui_story_5024_50240902_9_dialog_content = "Eh, Giles? Apa ini berarti…?",
  ui_story_5024_50240902_10_dialog_content = "Benar. Kau sudah memenuhi syarat untuk memerankan si <color=#FFB400>anak domba</color> dalam pertunjukan mendatang.",
  ui_story_5024_50240902_11_dialog_content = "Keren! Berarti, tinggal cari si burung hantu salju saja, 'kan?",
  ui_story_5024_50240902_12_dialog_content = "Yap.",
  ui_story_5024_50240902_13_dialog_content = "Ya, tapi… Yang ini mungkin agak sulit ditangani…",
  ui_story_5024_50240902_14_dialog_content = "Salah, salah, salah…",
  ui_story_5024_50240902_15_dialog_content = "Semuanya salah…",
  ui_story_5024_50240902_16_dialog_content = "Semuanya sungguh… Sangat biasa! Sangat biasa sampai-sampai aku tak tahan melihatnya! Kenapa dewa kami mau…",
  ui_story_5024_50240902_17_dialog_content = "Siapa itu?!",
  ui_story_5024_50240902_18_dialog_content = "Ketuk pintu dulu tiga kali sebelum masuk!",
  ui_story_5024_50240902_19_dialog_content = "<color=#e8d9bb>Tok, tok, tok…</color>",
  ui_story_5024_50240902_20_dialog_content = "Kenapa kita tetap harus mengetuk pintu padahal dia sudah tahu kita mau masuk…?",
  ui_story_5024_50240902_21_dialog_content = "Memang seperti itulah Telamont. Dia sangat mengutamakan ketertiban di atas segala hal.",
  ui_story_5024_50240902_X21_dialog_content = "Ayo masuk.",
  ui_story_5024_50240902_X22_dialog_content = "Cih… Ternyata kau, Giles.",
  ui_story_5024_50240902_22_dialog_content = "Akan kubereskan perkara kita sebentar lagi.",
  ui_story_5024_50240902_23_dialog_content = "Kalian semua… Sebenarnya, siapa kalian?",
  ui_story_5024_50240902_24_dialog_content = "Lalu kenapa kalian kemari dan mengganggu pekerjaanku?",
  ui_story_5024_50240902_25_dialog_content = "Aku, anu… Tak tahu harus bilang apa…",
  ui_story_5024_50240902_26_dialog_content = "Sekarang, aku hanya perlu <color=#FFB400>mengalahkan si burung hantu</color>… Iya, 'kan?",
  ui_story_5024_50240902_27_dialog_content = "K-Kurasa kami harus menantangmu… Atau semacam itu, lah.",
  ui_story_5024_50240902_28_dialog_content = "Kau? Menantangku? Hah!",
  ui_story_5024_50240902_29_dialog_content = "Sekumpulan orang tak karuan seperti kalian, dengan pakaian paling biasa-biasa saja…",
  ui_story_5024_50240902_30_dialog_content = "Jelas, tak ada gunanya kita bertarung.",
  ui_story_5024_50240902_31_dialog_content = "… Memangnya apa yang salah dengan pakaian kami?",
  ui_story_5024_50240902_32_dialog_content = "Oh, sama sekali tak ada yang salah… kalau tujuan kalian memang sebatas menutupi tubuh dan bertahan hidup.",
  ui_story_5024_50240902_33_dialog_content = "Namun, selera kalian… Yah, bisa dibilang selera kalian tak mungkin bisa menang.",
  ui_story_5024_50240902_34_dialog_content = "Kalau kalian menghadiri jamuan makan dengan pakaian compang-camping seperti itu… Bisa-bisa kalian dimakan hidup-hidup.",
  ui_story_5024_50240902_35_dialog_content = "Atau lebih buruk lagi… Bisa jadi mereka bahkan tak akan mengizinkan kalian menghadiri jamuan makan itu.",
  ui_story_5024_50240902_36_dialog_content = "Hah? Aku tak tahu, ternyata ada aturan berpakaian untuk menghadiri jamuan makan itu…",
  ui_story_5024_50240902_37_dialog_content = "Tidak, tidak, tidak, ini sama sekali tak pantas. Wol, katun, sutra… Apa pun jenis kainnya, semua pakaian ini tak tepat!",
  ui_story_5024_50240902_38_dialog_content = "Semuanya terlalu biasa-biasa saja… Apa pun yang kulakukan, aroma biasa-biasa saja yang tak menarik dari pakaian ini tetap tak akan bisa dihilangkan.",
  ui_story_5024_50240902_39_dialog_content = "Dewa tak akan mau hadir dalam jamuan makan itu kalau kalian mengenakan pakaian compang-camping seperti ini!",
  ui_story_5024_50240902_40_dialog_content = "Lagi pula, tak mungkin ada orang waras yang sengaja memilih untuk bersantap bersama babi, 'kan?",
  ui_story_5024_50240902_41_dialog_content = "Hoi! Apa maksudmu?!",
  ui_story_5024_50240902_42_dialog_content = "Semua Aurorian adalah ciptaan God of Light! Dewa kami tak akan memandang rendah kepada kami seperti itu!",
  ui_story_5024_50240902_43_dialog_content = "Cih… Rupanya kau pengikut White Night, ya? Kalau begitu, tak ada gunanya membahasnya denganmu.",
  ui_story_5024_50240902_44_dialog_content = "Lagi pula, kau dan seluruh jemaatmu memang sangat suka membohongi diri sendiri.",
  ui_story_5024_50240902_45_dialog_content = "Apa-apaan kau…",
  ui_story_5024_50240902_46_dialog_content = "Uhh… Baiklah! Kalau begitu, menurutMU, kami harus berpakaian seperti apa untuk menghadiri jamuan makan itu?",
  ui_story_5024_50240902_47_dialog_content = "Tentu saja, kalau kalian berharap dewa akan menampakkan diri dalam jamuan makan itu… Kalian harus mengenakan pakaian yang mulia.",
  ui_story_5024_50240902_48_dialog_content = "Dewa tak mungkin mau menampakkan diri dalam urusan sepele manusia. Kecuali, tentu saja, kita berusaha semampu kita agar kita bisa mendekati citranya.",
  ui_story_5024_50240902_49_dialog_content = "Satu-satunya masalah adalah… tak ada seorang pun yang pernah melihat dewa secara langsung, apalagi pakaian yang dikenakannya…",
  ui_story_5024_50240902_50_dialog_content = "Apa dewa sungguh butuh pakaian?",
  ui_story_5024_50240902_51_dialog_content = "Mereka kan lebih jauh lebih mulia daripada kita… Jadi, untuk apa mereka butuh pakaian? Untuk menghangatkan badan?",
  ui_story_5024_50240902_52_dialog_content = "Jangan berpikiran picik begitu, Nona!",
  ui_story_5024_50240902_53_dialog_content = "Apa pun yang menyelubungi dewa kita, menyamarkannya dari mata manusia… Itulah yang kita sebut pakaian dewa kita!",
  ui_story_5024_50240902_54_dialog_content = "Oh…",
  ui_story_5024_50240902_55_dialog_content = "Kalau begitu, bukankah itu berarti bahwa keberadaan semua makhluk adalah pakaian dewamu?",
  ui_story_5024_50240902_56_dialog_content = "Semua hal terlahir dari dewamu, tapi sang dewa sendiri tak terlihat di mana pun…",
  ui_story_5024_50240902_57_dialog_content = "Ia menciptakan langit di atas, laut di bawah, dan segala yang ada di antaranya, tapi ia sendiri justru bersembunyi di tengah-tengah semua ciptaannya itu…",
  ui_story_5024_50240902_58_dialog_content = "Kata-katamu lumayan indah, tapi pada praktiknya tak berguna. Kecuali, tentu saja, kalau kau berniat membuat pakaian dari langit atau laut?",
  ui_story_5024_50240902_59_dialog_content = "Tentu saja tidak. Hanya dewalah yang bisa melakukan hal seperti itu, dan kau bukan dewa.",
  ui_story_5024_50240902_60_dialog_content = "… Jangan-jangan, kau mencoba mengejekku, ya?",
  ui_story_5024_50240902_61_dialog_content = "Namun… Tak sulit kalau kita sebatas ingin meniru dewa.",
  ui_story_5024_50240902_62_dialog_content = "Langit dan laut memang luas, tapi kadang keduanya hadir lebih dekat dan dalam rupa yang lebih berwujud.",
  ui_story_5024_50240902_63_dialog_content = "Misalnya, lukisan di dinding itu.",
  ui_story_5024_50240902_64_dialog_content = "!!!",
  ui_story_5024_50240902_65_dialog_content = "Kalau kita bisa memotong beberapa bagiannya dan menjahitnya jadi satu…",
  ui_story_5024_50240902_66_dialog_content = "Lihat, 'kan? Dengan begini, kita bisa mengenakan langit dan laut sebagai pakaian.",
  ui_story_5024_50240902_67_dialog_content = "Ya… Ya…",
  ui_story_5024_50240902_68_dialog_content = "Mengenakan langit dan laut…",
  ui_story_5024_50240902_69_dialog_content = "Ternyata kau sama sekali tak mengejeknya!",
  ui_story_5024_50240902_70_dialog_content = "Luar biasa, Carleen!",
  ui_story_5024_50240902_71_dialog_content = "*Batuk-batuk*",
  ui_story_5024_50240902_72_dialog_content = "Bisa dibilang, aku menang sedangkan kau gagal. Iya, 'kan?",
  ui_story_5024_50240902_73_dialog_content = "Cih, masih saja bersikeras dengan persaingan kecilmu, ya?",
  ui_story_5024_50240902_X73_dialog_content = "Segala yang kaukatakan barusan sama sekali bukanlah hal yang tak bisa kupahami.",
  ui_story_5024_50240902_X74_dialog_content = "Dari waktu ke waktu, orang-orang biasa seperti kalian memang mungkin diberi kehormatan untuk melihat Truth.",
  ui_story_5024_50240902_X75_dialog_content = "Namun, tanpa metode yang layak, mereka tak akan pernah bisa mengalami sendiri penampakan Truth yang mulia.",
  ui_story_5024_50240902_X76_dialog_content = "Maksudmu?",
  ui_story_5024_50240902_X77_dialog_content = "Sama halnya dengan barang di tangan kalian, yang kalian sebut \"pakaian\" itu.",
  ui_story_5024_50240902_X78_dialog_content = "Benda itu tak lebih dari sekadar potongan-potongan lukisan tak bermakna yang dijahit jadi satu.",
  ui_story_5024_50240902_X79_dialog_content = "Namun, makna Truth tersembunyi dalam pesan yang dibawanya.",
  ui_story_5024_50240902_X80_dialog_content = "Makna suatu simbol jauh lebih luas dari sekadar wujud kebendaannya yang nyata.",
  ui_story_5024_50240902_X81_dialog_content = "Langit di atas, laut di bawah… Itu adalah simbol.",
  ui_story_5024_50240902_X82_dialog_content = "Yang kita sebut \"pakaian yang menyerupai dewa\"… Itu pun hanyalah simbol yang mencerminkan dewa kita.",
  ui_story_5024_50240902_X83_dialog_content = "Simbol? Namun, kalau begitu…",
  ui_story_5024_50240902_X84_dialog_content = "Kalian tak akan bisa paham. Kalian tak akan bisa memahaminya dengan pengetahuan kalian yang rendah dan mentah tentang Truth.",
  ui_story_5024_50240902_X85_dialog_content = "Nah, keluarlah, kalian semua! Aku harus membuat pakaian dan tak punya waktu untuk meladeni kalian!",
  ui_story_5024_50240902_74_dialog_content = "Kau hanya tak mau mengakui bahwa kau sudah kalah, 'kan?",
  ui_story_5024_50240902_75_dialog_content = "Sudahlah… Lukisanmu saja sudah cukup.",
  ui_story_5024_50240902_76_dialog_content = "Nah, Giles? Apa sekarang Carleen bisa memerankan si burung hantu salju?",
  ui_story_5024_50240902_77_dialog_content = "Tentu saja! Siapa pun yang bisa menjatuhkan Telamont dari kecongkakannya adalah orang yang pantas memerankan si <color=#FFB400>burung hantu salju</color>!",
  ui_story_5024_50241001_1_dialog_content = "<color=#e8d9bb>Gong, gong, gong, gong…</color>",
  ui_story_5024_50241001_2_dialog_content = "Sebentar, suara itu… Apa jamuan makannya sudah dimulai?",
  ui_story_5024_50241001_3_dialog_content = "Di mana si aktor terakhir, Giles? Kita harus segera menuju ke panggung.",
  ui_story_5024_50241001_4_dialog_content = "Kalau pertunjukannya jadi seperti kemarin malam, kita harus menundanya lagi untuk besok.",
  ui_story_5024_50241001_5_dialog_content = "(Memang salah kalau kami membuat Carleen terpaksa tinggal di rumah aneh ini selama ini… Kami harus segera menyelesaikan urusan di sini.)",
  ui_story_5024_50241001_6_dialog_content = "Aku setuju. Giles, bisakah kau—",
  ui_story_5024_50241001_7_dialog_content = "Tidak semudah itu—",
  ui_story_5024_50241001_8_dialog_content = "Waktu bermain sudah habis, Giles.",
  ui_story_5024_50241001_9_dialog_content = "Apa pun alasanmu, kurasa kau tahu pasti setelah ini kau harus pergi ke mana… Benar, 'kan?",
  ui_story_5024_50241001_10_dialog_content = "… Ha… Hahahahaha!",
  ui_story_5024_50241001_11_dialog_content = "Baiklah! Akhirnya kita akan melakukannya, nih?",
  ui_story_5024_50241001_12_dialog_content = "A-apa?",
  ui_story_5024_50241001_13_dialog_content = "Benar. Kami sudah menyiapkan <color=#FFB400>pertunjukan istimewa</color> untuk jamuan makan malam ini…",
  ui_story_5024_50241001_14_dialog_content = "Pakailah ini, Giles. Toh ini memang sudah tradisi, 'kan…",
  ui_story_5024_50241001_15_dialog_content = "Lagi pula, aku tak suka memaksa orang lain.",
  ui_story_5024_50241001_16_dialog_content = "Ah, tak usah. Tunjukkan saja jalannya.",
  ui_story_5024_50241001_17_dialog_content = "Pertunjukan istimewa…?",
  ui_story_5024_50241001_18_dialog_content = "(Seingatku, aku tak pernah dengar tentang hal ini…)",
  ui_story_5024_50241001_19_dialog_content = "(Pasti karena mereka membenciku… Aku yakin itu…)",
  ui_story_5024_50241001_20_dialog_content = "Langsung saja ke intinya, Telamont. Beri tahu kami tentang pertunjukan istimewa ini.",
  ui_story_5024_50241001_21_dialog_content = "*Tertawa kecil* Yah… Bisa dibilang, kami sudah cukup lama menyiapkan \"pertunjukan\" ini.",
  ui_story_5024_50241001_22_dialog_content = "Sebenarnya, True Order sudah merencanakannya sejak <color=#FFB400>kelompok orang terakhir</color> itu masuk ke Theater.",
  ui_story_5024_50241001_23_dialog_content = "Kelompok terakhir? Apa itu termasuk…",
  ui_story_5024_50241001_24_dialog_content = "Giles?",
  ui_story_5024_50241001_25_dialog_content = "Yap.",
  ui_story_5024_50241001_26_dialog_content = "Black Magma Giles adalah satu-satunya orang yang berhasil keluar dari Theater setelah masuk ke sana.",
  ui_story_5024_50241001_27_dialog_content = "Namun, sejak dia keluar dari sana…",
  ui_story_5024_50241001_28_dialog_content = "Dia selalu saja tak mau menjawab anggota lain True Order yang menanyakan cara masuk ke Theater.",
  ui_story_5024_50241001_29_dialog_content = "Menipu orang lain bukanlah tindakan yang jantan.",
  ui_story_5024_50241001_30_dialog_content = "Nah, Giles. Sudah saatnya kaubagikan pengetahuanmu dengan semua orang, bukan?",
  ui_story_5024_50241001_X30_dialog_content = "…",
  ui_story_5024_50241001_31_dialog_content = "Lagi pula, Lady Victoria sampai repot-repot menyiapkan panggung ini untukmu.",
  ui_story_5024_50241001_32_dialog_content = "Jangan lupa, Faust, kau di sini untuk bertindak sebagai hakim.",
  ui_story_5024_50241001_33_dialog_content = "Kalian semua… Kalau memang mau, kalian boleh menonton.",
  ui_story_5024_50241001_34_dialog_content = "Anu, Faust? Ada apa ini sebenarnya…?",
  ui_story_5024_50241001_35_dialog_content = "Ini bukan keputusanku. Ini sudah diputuskan sejak dulu.",
  ui_story_5024_50241001_36_dialog_content = "Nah, sekarang, kau tak akan bisa mulai kalau belum menemukan aktor terakhir.",
  ui_story_5024_50241001_37_dialog_content = "Bagaimana kalau kubantu kau mencarinya?",
  ui_story_5024_50241001_38_dialog_content = "…Ba-baiklah.",
  ui_story_5024_50241001_39_dialog_content = "(Sikapnya yang kelewat ramah itu justru membuatku merasa ngeri…)",
  ui_story_5024_50241001_40_dialog_content = "<color=#e8d9bb>Cuit… Cuit…</color>",
  ui_story_5024_50241001_41_dialog_content = "Hadirin sekalian, harap tenang!",
  ui_story_5024_50241001_42_dialog_content = "Oh, dan PlayerName? Kau dan teman-temanmu bisa duduk di meja Giles. Di sana, di sebelah kiri.",
  ui_story_5024_50241001_43_dialog_content = "Pastikan kalian duduk di sebelah kiri. Bagian kanannya akan kami gunakan sebagai tempat untuk pihak penuntut.",
  ui_story_5024_50241001_44_dialog_content = "P-Penuntut?",
  ui_story_5024_50241001_45_dialog_content = "Di Hall of Justice di Lumopolis, kami menggunakan istilah itu untuk menyebut pihak penggugat dalam persidangan.",
  ui_story_5024_50241001_46_dialog_content = "Namun, aku sendiri tak yakin apa yang sebenarnya sedang terjadi di sini…",
  ui_story_5024_50241001_47_dialog_content = "Kurasa True Order melayangkan suatu tuduhan kepada Giles.",
  ui_story_5024_50241001_48_dialog_content = "(Karena kau menyebutkannya, aku jadi sadar bahwa setengah bagian ruangan ini memang seluruhnya diisi oleh para anggota True Order…)",
  ui_story_5024_50241001_49_dialog_content = "(Ada pula banyak orang yang tidak duduk menghadap meja… Mungkinkah mereka itu yang disebut \"hakim\" dalam persidangan pengadilan?)",
  ui_story_5024_50241001_50_dialog_content = "Aku hanya berharap pertunjukan mereka ini tak bertele-tele. Sekarang saja, waktu kita sudah tak banyak…",
  ui_story_5024_50241001_51_dialog_content = "<color=#e8d9bb>Kruuk…</color>",
  ui_story_5024_50241001_52_dialog_content = "Ehem… Belum lagi, aku yakin sebagian dari kita sudah mulai lapar.",
  ui_story_5024_50241001_53_dialog_content = "… Ada apa ini, Giles? Tuduhan apa yang dilontarkan kepadamu?",
  ui_story_5024_50241001_54_dialog_content = "Haha! Saatnya bermain teka-teki, kawan-kawan. Kelelawar punya mata, tapi tak bisa melihat. Ular gua punya telinga, tapi tak bisa mendengar…",
  ui_story_5024_50241001_55_dialog_content = "Nah, coba jawab. Punya mulut, tapi tak bisa bicara. Apakah itu?",
  ui_story_5024_50241001_56_dialog_content = "Eee… Apa?",
  ui_story_5024_50241001_57_dialog_content = "Jawabannya adalah… kau, PlayerName.",
  ui_story_5024_50241001_58_dialog_content = "Nah, duduk dan diamlah. Pertunjukannya akan segera dimulai.",
  ui_story_5024_50241001_59_dialog_content = "Lagi pula, tujuanmu masuk ke Theater sebenarnya adalah untuk menyelamatkan orang lain, 'kan?",
  ui_story_5024_50241001_60_dialog_content = "Pihak pembela diharap diam.",
  ui_story_5024_50241001_61_dialog_content = "<size=33>Bagus, sepertinya Lady Victoria ada di sini.</size>",
  ui_story_5024_50241001_62_dialog_content = "Sepertinya semua orang sudah hadir dan siap mengikuti persidangan.",
  ui_story_5024_50241001_63_dialog_content = "Awalnya, aku menentang penerapan cara ini untuk memutuskan perkara resmi True Order.",
  ui_story_5024_50241001_64_dialog_content = "Lagi pula, yang sungguh benar dan pasti hanyalah pengetahuan dan Truth.",
  ui_story_5024_50241001_65_dialog_content = "Namun, Giles… Sepertinya tindakanmu membuat banyak anggota True Order berang.",
  ui_story_5024_50241001_66_dialog_content = "Sebelum mengambil keputusan, aku ingin mendengar detail perkaranya terlebih dulu.",
  ui_story_5024_50241001_67_dialog_content = "Panitera acara, bisa tolong bacakan tuduhannya?",
  ui_story_5024_50241001_68_dialog_content = "*Ehem* Semoga musik memberkati hidup kalian semua!",
  ui_story_5024_50241001_69_dialog_content = "\"Setelah keluar dari Theater, Giles menyebarkan lagu anak-anaknya ke seluruh rumah ini!\"♪",
  ui_story_5024_50241001_70_dialog_content = "\"Namun, satu-satunya hal yang tak diberitahukannya, yang tak berani disebutnya… adalah cara masuk ke Theater!\"♪",
  ui_story_5024_50241001_71_dialog_content = "\"Sebagian orang bilang, di dalamnya ada kitab bernilai tak terhingga. Sebagian lagi bilang Truth bersembunyi di ceruk-ceruk Theater!\"♪",
  ui_story_5024_50241001_72_dialog_content = "\"Namun, tetap saja dia tak mau berbagi pengetahuan dengan kita semua. Apa pun yang terjadi, dia tak mau memberitahukannya, begitulah katanya!\"♪",
  ui_story_5024_50241001_73_dialog_content = "Terima kasih, semuanya!",
  ui_story_5024_50241001_74_dialog_content = "Baiklah. Sekarang, kita dengarkan putusan hakim.",
  ui_story_5024_50241001_75_dialog_content = "S-Sebentar, Lady Victoria! Apa menurutmu ini tak terlalu terburu-buru?",
  ui_story_5024_50241001_76_dialog_content = "Oh? Apa ada tambahan untuk tuntutannya?",
  ui_story_5024_50241001_77_dialog_content = "… Karena bagiku, sepertinya duduk perkaranya sudah jelas. Giles menolak memberitahukan cara masuk ke Theater kepada para anggota lain True Order. Benar demikian?",
  ui_story_5024_50241001_78_dialog_content = "Y-Ya, benar, bisa dibilang begitu… Namun, itu membuat tindak kejahatan yang dilakukannya terdengar terlalu sepele, Lady Victoria! Padahal, tindak kejahatannya ini harus diganjar dengan hukuman!",
  ui_story_5024_50241001_79_dialog_content = "Misi True Order adalah menyebarkan pengetahuan tentang Lord of Truth ke seluruh penjuru negeri.",
  ui_story_5024_50241001_80_dialog_content = "Apa pun latar belakang asal-usul, jenis kelamin, atau status sosial kita, kita berkumpul bersama dengan niat baik untuk saling berbagi pengetahuan tentang Truth…",
  ui_story_5024_50241001_81_dialog_content = "Dengan menahan informasi sangat penting yang mungkin saja berkaitan dengan Truth, Giles jelas-jelas melanggar ajaran paling mendasar dari True Order!",
  ui_story_5024_50241001_82_dialog_content = "… Adakah tanggapan yang ingin disampaikan pihak pembela terhadap tuduhan ini?",
  ui_story_5024_50241001_83_dialog_content = "(Giles sama sekali bukan seperti yang kautuduhkan itu!)",
  ui_story_5024_50241001_84_dialog_content = "Ya!",
  ui_story_5024_50241001_85_dialog_content = "…Hah?",
  ui_story_5024_50241001_86_dialog_content = "Aku tak sepenuhnya yakin apa alasan Giles menolak memberi tahu True Order tentang cara masuk ke Theater…",
  ui_story_5024_50241001_87_dialog_content = "Namun, untuk saat ini, aku hanya bisa bilang…",
  ui_story_5024_50241001_88_dialog_content = "Giles sudah membagikan pengetahuannya itu kepada kami.",
  ui_story_5024_50241001_89_dialog_content = "Benar begitu, 'kan, PlayerName?",
  ui_story_5024_50241001_90_dialog_content = "Ya!",
  ui_story_5024_50241001_91_dialog_content = "Menurut Giles, tinggal satu hal lagi yang harus kami lakukan agar bisa memenuhi syarat untuk masuk ke Theater…",
  ui_story_5024_50241001_92_dialog_content = "Kalau kami bisa melakukannya, berarti kami bisa membuktikan bahwa Giles sama sekali tak bersalah!",
  ui_story_5024_50241001_93_dialog_content = "Namun, yang ingin kuketahui…",
  ui_story_5024_50241001_94_dialog_content = "Adalah kenapa dia justru mau membantu kami masuk ke Theater. Giles?",
  ui_story_5024_50241001_95_dialog_content = "…",
  ui_story_5024_50241001_96_dialog_content = "Itu karena… yang ada di dalam Theater sama sekali bukan seperti dugaan kalian. Di dalamnya adalah ruang yang dipenuhi Truth…",
  ui_story_5024_50241001_97_dialog_content = "Tempat yang dipenuhi bahaya yang tak terbayangkan.",
  ui_story_5024_50241001_98_dialog_content = "Begitu masuk ke dalam Theater, kalau kalian tak mampu menyajikan pertunjukan Anjing Baik yang Mengantuk dengan sempurna di atas panggung…",
  ui_story_5024_50241001_99_dialog_content = "Kalian tak akan pernah diizinkan keluar dari sana.",
  ui_story_5024_50241001_100_dialog_content = "…!",
  ui_story_5024_50241001_101_dialog_content = "Orang-orang yang terperangkap di dalam tembok Theater akan pelan-pelan kehilangan akal sehat mereka, sedikit demi sedikit…",
  ui_story_5024_50241001_102_dialog_content = "Hingga akhirnya mereka sama sekali tak bisa mengenali diri mereka sendiri, dan saat itu… yang mereka tahu hanyalah peran yang diberikan kepada mereka.",
  ui_story_5024_50241001_103_dialog_content = "Yang terjadi padaku setelah itu… adalah misteri, bahkan bagi diriku sendiri.",
  ui_story_5024_50241001_104_dialog_content = "… Mungkin, aku berhasil lolos dari sana semata-mata karena takdir berbelok tanpa terduga, tapi hanya akulah yang berhasil keluar dari sana.",
  ui_story_5024_50241001_105_dialog_content = "Aku sudah hafal lirik Anjing Baik yang Mengantuk bahkan sebelum aku mulai belajar bicara.",
  ui_story_5024_50241001_106_dialog_content = "Aku cukup beruntung bisa masuk ke Theater, tapi penampilanku tak sempurna…",
  ui_story_5024_50241001_107_dialog_content = "Walau begitu, aku tetap berhasil menjaga kewarasanku dan bisa keluar dari sana hidup-hidup.",
  ui_story_5024_50241001_108_dialog_content = "Sampai sekarang pun, aku masih tak tahu pertunjukan seperti apa yang layak disebut \"pertunjukan yang sempurna\" di Theater…",
  ui_story_5024_50241001_109_dialog_content = "Atas alasan itulah, aku tak mau membiarkan seorang pun masuk ke Theater dan membahayakan nyawa mereka semata-mata demi memuaskan rasa ingin tahu.",
  ui_story_5024_50241001_110_dialog_content = "Lalu, tentang PlayerName dan teman-temannya…",
  ui_story_5024_50241001_111_dialog_content = "Mereka punya alasan yang sangat bagus untuk masuk ke Theater, yaitu untuk menyelamatkan teman dan keluarga mereka agar tak terkurung di sana.",
  ui_story_5024_50241001_112_dialog_content = "Dan aku berniat terus membantu mereka dengan segala cara yang bisa kulakukan.",
  ui_story_5024_50241001_113_dialog_content = "… Kalau begitu, Giles, kenapa baru sekarang kau memberitahukannya kepada kami?",
  ui_story_5024_50241001_114_dialog_content = "Karena…",
  ui_story_5024_50241001_115_dialog_content = "(Karena kalian sama sekali tak mungkin bisa memahami betapa besarnya kengerian yang kualami di sana…)",
  ui_story_5024_50241001_116_dialog_content = "Apa pun alasannya, cukup sekian pembelaanku.",
  ui_story_5024_50241001_117_dialog_content = "Lalu, PlayerName? Sepertinya sekarang tiket untuk <color=#FFB400>pertunjukan di Theater itu sudah terjual habis</color>.",
  ui_story_5024_50241001_118_dialog_content = "<color=#FFB400>Rantai</color> yang kupakai ini adalah perlengkapan terakhir yang kaubutuhkan untuk pertunjukan itu.",
  ui_story_5024_50241001_119_dialog_content = "Mohon maaf, Lady Victoria, tapi bisakah kausampaikan putusanmu sekarang?",
  ui_story_5024_50241001_120_dialog_content = "… Faust, lepaskan rantai yang mengikat Giles.",
  ui_story_5024_50241001_121_dialog_content = "Pertunjukan sidang pengadilan kita sudah selesai.",
  ui_story_5024_50241001_122_dialog_content = "Kalau kau dan teman-temanmu itu memang adalah orang-orang yang diizinkan menjelajahi Manor of Truth…",
  ui_story_5024_50241001_123_dialog_content = "PlayerName, semoga Truth memberkatimu! Aku akan berusaha semampuku untuk membantumu.",
  ui_story_5024_50241101_1_dialog_content = "Semoga pertunjukanmu berhasil, PlayerName!",
  ui_story_5024_50241101_2_dialog_content = "Semoga berhasil, PlayerName. Nikmatilah setiap momen ketakutan dan sukacita di atas panggung selagi kau bisa.",
  ui_story_5024_50241101_3_dialog_content = "Tampilkan pertunjukan yang istimewa, PlayerName…",
  ui_story_5024_50241101_4_dialog_content = "Aku tak menemukan Hunting Stone milikku di mana pun, tapi kalau ia berniat mengganggu pertunjukanmu… Berusahalah agar tak terlalu kaget, ya.",
  ui_story_5024_50241101_5_dialog_content = "PlayerName, kau dan teman-temanmu mungkin adalah orang paling dungu yang pernah kukenal… Walau begitu, semoga berhasil.",
  ui_story_5024_50241101_6_dialog_content = "… Oh ya, omong-omong, Pact bohong. Sebenarnya, dia sendirilah yang berniat menerobos masuk ke Theater, bukan batu miliknya.",
  ui_story_5024_50241101_7_dialog_content = "Dia terlalu keras kepala dan terus saja mengira bahwa Manor of Truth menyembunyikan sesuatu yang istimewa… Misalnya sumber pengetahuan besar, atau sesuatu yang bisa meningkatkan pemahamannya tentang Truth.",
  ui_story_5024_50241101_8_dialog_content = "PlayerName, aku hanya bisa mengantarmu dan teman-temanmu sampai sini.",
  ui_story_5024_50241101_9_dialog_content = "Aku sungguh mengagumi tekadmu. Setelah kau kembali nanti, aku berjanji akan merayakan \"kelahiran kembali\"-mu dengan penuh sukacita.",
  ui_story_5024_50241101_10_dialog_content = "Semoga Truth memberkatimu.",
  ui_story_5024_50241101_11_dialog_content = "Biar kuberi tahu sejujurnya, PlayerName… Dalam naskah-naskah kuno kami, disebutkan suatu ramalan tentang dirimu dan Theater…",
  ui_story_5024_50241101_12_dialog_content = [[
"Satu-satunya Truth terkandung dalam lagu anak-anak yang harus dilantunkan berulang kali. 
Nasib si pemeran tetap tak diketahui, ibarat syair yang belum selesai dalam halaman naskahnya."]],
  ui_story_5024_50241101_13_dialog_content = "\"Sebelum tirai panggung diturunkan saat adegan akhir akbar, tak seorang pun boleh pergi.\"",
  ui_story_5024_50241101_14_dialog_content = "Tentang maknanya, aku sendiri tak terlalu yakin… Namun, siapa tahu salah satu temanmu bisa memberikan petunjuk lebih banyak, 'kan?",
  ui_story_5024_50241101_15_dialog_content = "Aku dan seluruh anggota True Order akan menunggu di pintu masuk, dan membantu kalian semampu kami.",
  ui_story_5024_50241101_16_dialog_content = "Semoga kalian semua berhasil.",
  ui_story_5024_50241101_17_dialog_content = "T-Terima kasih, semuanya…!",
  ui_story_5024_50241101_18_dialog_content = "(Ini sungguh aneh…)",
  ui_story_5024_50241101_19_dialog_content = "(Kurasa aku tak akan pernah bisa memahami orang-orang ini…)",
  ui_story_5024_50241101_20_dialog_content = "Theater akan segera terbuka. Semuanya, siapkan perlengkapan kalian!",
  ui_story_5024_50241101_21_dialog_content = "Si <color=#FFB400>anak domba</color> dengan alat makan berbahan perak…",
  ui_story_5024_50241101_22_dialog_content = "Si <color=#FFB400>kucing</color> dengan sebatang lilin…",
  ui_story_5024_50241101_23_dialog_content = "Si <color=#FFB400>burung hantu</color> dengan pakaian dari lukisan…",
  ui_story_5024_50241101_24_dialog_content = "Dan si <color=#FFB400>anjing</color>, dengan rantainya…",
  ui_story_5024_50241101_25_dialog_content = "Sepertinya semua persiapan sudah selesai, ya?",
  ui_story_5024_50241101_26_dialog_content = "Benar! Semua aktor sudah siap, jadi mestinya tirainya akan segera terbuka…",
  ui_story_5024_50241101_27_dialog_content = "Nah, semuanya, bersiaplah untuk beraksi di atas panggung!",
  ui_story_5024_50241101_28_dialog_content = "Saatnya masuk ke Theater…",
  ui_story_5024_50241101_29_dialog_content = "Namun, sebenarnya, aku belum tahu pasti seperti apa \"pertunjukan yang sempurna\" itu…",
  ui_story_5024_50241101_30_dialog_content = "Kita akan cari tahu sambil jalan. Biasanya, itulah cara yang kami gunakan.",
  ui_story_5024_50241101_31_dialog_content = "PlayerName benar. Lagi pula, kalau tak masuk ke sana, kita tak akan punya kesempatan untuk menampilkan pertunjukannya.",
  ui_story_5024_50241101_32_dialog_content = "Bagus sekali! Ayo masuk dan tampilkan pertunjukan Anjing Baik yang Mengantuk yang paling bagus, lalu kita keluar dari sana!",
  ui_story_5024_50241101_33_dialog_content = "<color=#e8d9bb>Tak-tuk… Tak-tuk…</color>",
  ui_story_5024_50241101_34_dialog_content = "(Di sini gelap sekali… Namun, dari suara gemanya, sepertinya tempat ini sangat luas…)",
  ui_story_5024_50241101_35_dialog_content = "(Betapa pun kerasnya aku berusaha, aku tak bisa merasakan kehadiran siapa pun atau apa pun selain kami sendiri…)",
  ui_story_5024_50241101_36_dialog_content = "(Aku merasakan firasat buruk tentang tempat ini…)",
  ui_story_5024_50241101_37_dialog_content = "M-Mungkinkah mereka benar ada di dalam sini…? Lenore, Gretel… Dan ibu Lenore dan May?",
  ui_story_5024_50241101_38_dialog_content = "Ah… Ahhh… AHHH…",
  ui_story_5024_50241101_39_dialog_content = "<size=45>HAAAAT-SYIIIH!!</size>",
  ui_story_5024_50241101_40_dialog_content = "Aduh… Di dalam sini sangat berdebu…",
  ui_story_5024_50241101_41_dialog_content = "Sepertinya tempat ini sudah lama sekali tak dijamah seorang pun…",
  ui_story_5024_50241101_42_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5024_50241101_43_dialog_content = "Apa itu barusan?!",
  ui_story_5024_50241101_44_dialog_content = "May! Kau baik-baik saja?!",
  ui_story_5024_50241101_45_dialog_content = "Aduh… Sakit sekali…",
  ui_story_5024_50241101_46_dialog_content = "Sepertinya kakiku terpaksa harus dijahit lagi…",
  ui_story_5024_50241101_47_dialog_content = "Perhatikan langkah kalian, teman-teman. Jangan sampai tersandung apa pun…",
  ui_story_5024_50241101_48_dialog_content = "Bagaimana kalau kaunyalakan saja lilinmu untuk menerangi jalan kita? Lalu, kita tinggal mengikuti Giles dan melangkah dengan hati-hati.",
  ui_story_5024_50241101_49_dialog_content = "Menerangi jalan…?",
  ui_story_5024_50241101_50_dialog_content = "Benar, rasanya memang seperti ada sesuatu di tanah yang menghambat gerakan kita…",
  ui_story_5024_50241101_51_dialog_content = "Apa-apaan ini?",
  ui_story_5024_50241101_52_dialog_content = "<color=#e8d9bb>Krusuk, krusuk, krusuk…</color>",
  ui_story_5024_50241101_53_dialog_content = "Hmm… Bentuknya keras dan seperti tabung, tapi aku tak yakin benda apa ini…",
  ui_story_5024_50241101_54_dialog_content = "S-Sini, coba kulihat…",
  ui_story_5024_50241101_55_dialog_content = "…!",
  ui_story_5024_50241101_56_dialog_content = "<anim type=Shake><size=45>Aaaaaaahhhhhhhh!!!</size></anim>",
  ui_story_5024_50241101_57_dialog_content = "D-D-Di tanah… Itu… Itu…!",
  ui_story_5024_50241101_58_dialog_content = "(Hah?!)",
  ui_story_5024_50241101_59_dialog_content = "… Jangan panik.",
  ui_story_5024_50241101_60_dialog_content = "Itu bukan badan manusia betulan, tapi badan boneka.",
  ui_story_5024_50241101_61_dialog_content = "Boneka?",
  ui_story_5024_50241101_62_dialog_content = "Namun, kenapa mereka tampak seperti Lenore?",
  ui_story_5024_50241101_63_dialog_content = "Huh… Tampaknya, mereka hanya boneka biasa saja. Sama sekali tak punya kesadaran…",
  ui_story_5024_50241101_64_dialog_content = "Oh… Oh, tidak…",
  ui_story_5024_50241101_65_dialog_content = "Wajah boneka yang itu… Mustahil…!",
  ui_story_5024_50241101_66_dialog_content = "Ada apa, Giles? Tampangmu seperti baru saja melihat hantu…",
  ui_story_5024_50241101_67_dialog_content = "J-Jangan lihat, May!!!",
  ui_story_5024_50241101_68_dialog_content = "Oh!",
  ui_story_5024_50241101_69_dialog_content = "Sebentar… Boneka ini tampak persis dengan…",
  ui_story_5024_50241101_70_dialog_content = "<size=33><color=#FFB400>Ibu</color>?</size>",
  ui_story_5024_50241101_71_dialog_content = "Oh, begitu…",
  ui_story_5024_50241101_72_dialog_content = "Ini pastilah… apa yang terjadi pada orang-orang yang gagal menampilkan pertunjukan yang sempurna…",
  ui_story_5024_50241101_73_dialog_content = "Pertama-tama, mereka terkurung di sini, lalu pelan-pelan kehilangan akal sehat…",
  ui_story_5024_50241101_74_dialog_content = "Hingga akhirnya, mereka lupa siapa diri mereka, dan berubah menjadi tokoh yang mereka perankan…",
  ui_story_5024_50241101_75_dialog_content = "Lalu, mereka jadi seperti ini…",
  ui_story_5024_50241101_76_dialog_content = "Boneka… Boneka tak bernyawa dalam wujud diri mereka yang dulu…",
  ui_story_5024_50241101_77_dialog_content = "I-Ibu…",
  ui_story_5024_50241101_78_dialog_content = "Tidak… Ibu, Ibu tak boleh…",
  ui_story_5024_50241101_79_dialog_content = "Ini… Mestinya tak begini!",
  ui_story_5024_50241101_80_dialog_content = "(Sungguh kejam…)",
  ui_story_5024_50241101_81_dialog_content = "(Semoga God of Light menolong jiwa-jiwa malang ini agar menemukan kedamaian…)",
  ui_story_5024_50241101_82_dialog_content = "<anim type=Shake>Kriek…</anim>",
  ui_story_5024_50241101_83_dialog_content = "<anim type=Shake>Klik…</anim>",
  ui_story_5024_50241101_84_dialog_content = "Semuanya, waspada! Aku merasakan ada gerakan di dekat kita!",
  ui_story_5024_50241101_85_dialog_content = "<anim type=Shake><size=45>Klik… Klik…</size></anim>",
  ui_story_5024_50241101_86_dialog_content = "Apa ini mimpi buruk itu lagi…?",
  ui_story_5024_50241101_87_dialog_content = "Kalian semua sudah siap? PlayerName?",
  ui_story_5024_50241101_88_dialog_content = "Asalkan ini bisa memberikan kedamaian bagi boneka-boneka malang ini…",
  ui_story_5024_50241102_1_dialog_content = "<anim type=Shake>Klik… Tik…</anim>",
  ui_story_5024_50241102_2_dialog_content = "*Terkesiap* PlayerName… Di sini terlalu berbahaya…",
  ui_story_5024_50241102_3_dialog_content = "Kita harus bergegas mencari Lenore dan Gretel.",
  ui_story_5024_50241102_4_dialog_content = "Itu pun kalau mereka masih…",
  ui_story_5024_50241102_5_dialog_content = "Tidak… Mereka pasti baik-baik saja. Aku yakin itu.",
  ui_story_5024_50241102_6_dialog_content = "Yah, karena mereka tak ada di bangku penonton atau di koridor antara baris tempat duduk…",
  ui_story_5024_50241102_7_dialog_content = "Berarti, kemungkinannya hanya dua tempat. Area belakang panggung… dan di atas panggung itu sendiri.",
  ui_story_5024_50241102_8_dialog_content = "Begitu kita menginjakkan kaki di sana… suatu kekuatan tak dikenal akan pelan-pelan mulai menggerogoti akal sehat kita.",
  ui_story_5024_50241102_9_dialog_content = "Kalau Lenore dan Gretel terkurung di sini…",
  ui_story_5024_50241102_10_dialog_content = "…",
  ui_story_5024_50241102_11_dialog_content = "PlayerName… Carleen… May…",
  ui_story_5024_50241102_12_dialog_content = "Apa pun yang terjadi, kita harus mengingat nama-nama ini dan siapa orangnya. Paham?",
  ui_story_5024_50241102_13_dialog_content = "Ya.",
  ui_story_5024_50241102_14_dialog_content = "Jangan khawatir, aku akan terus mengawasi kesadaran semua orang selama kita di sini. Tak akan kubiarkan apa pun terjadi pada kita.",
  ui_story_5024_50241102_15_dialog_content = "Itu menenangkan. Nah, kalau begitu… Ikuti aku.",
  ui_story_5024_50241102_16_dialog_content = "<color=#e8d9bb>Di area belakang panggung di Theater…</color>",
  ui_story_5024_50241102_17_dialog_content = "Tempat ini sungguh aneh…",
  ui_story_5024_50241102_18_dialog_content = "Aku merasakan ada gangguan kuat di lubuk hatiku…",
  ui_story_5024_50241102_19_dialog_content = "Kalau kau takut, mungkin sebaiknya kita panggil saja nama mereka?",
  ui_story_5024_50241102_20_option_content = "Lenore!",
  ui_story_5024_50241102_21_dialog_content = "Lenore! Apa kau di sini?",
  ui_story_5024_50241102_22_dialog_content = "Kami berhasil masuk ke Theater! Kami kemari untuk menyelamatkanmu…",
  ui_story_5024_50241102_23_option_content = "Gretel!",
  ui_story_5024_50241102_24_dialog_content = "Gretel! Apa kau di sini?",
  ui_story_5024_50241102_25_dialog_content = "Tempat ini berbahaya! Kami mengkhawatirkanmu, jadi…",
  ui_story_5024_50241102_26_dialog_content = "<color=#e8d9bb>Kresek… Kresek…</color>",
  ui_story_5024_50241102_27_dialog_content = "Memang ada seseorang di sini!",
  ui_story_5024_50241102_28_dialog_content = "Persis di depan kita!",
  ui_story_5024_50241102_29_dialog_content = "Maaf membuat kalian menunggu lama…",
  ui_story_5024_50241102_30_dialog_content = "Oh… Rupanya kau, PlayerName… Dan… kalian semua juga…",
  ui_story_5024_50241102_31_dialog_content = "Akhirnya kalian datang untuk menyelamatkanku… Aku… aku senang sekali sampai-sampai ingin menangis…!",
  ui_story_5024_50241102_32_dialog_content = "(Bagus, sepertinya Lenore masih waras!)",
  ui_story_5024_50241102_33_dialog_content = "(Sebentar… Tubuhnya…)",
  ui_story_5024_50241102_34_dialog_content = "Ah… Maaf, ini agak memalukan…",
  ui_story_5024_50241102_35_dialog_content = "Namun, aku tak menyangka akan ada yang datang… Jadi, aku tak menyiapkan apa pun…",
  ui_story_5024_50241102_36_dialog_content = "Lagi pula… aku masih kesulitan menyesuaikan diri dengan <color=#FFB400>tubuh baruku</color> ini.",
  ui_story_5024_50241102_37_dialog_content = "Oh, tidak… Jangan bilang…",
  ui_story_5024_50241102_38_dialog_content = "Setelah kita berpisah, aku tak sadarkan diri cukup lama.",
  ui_story_5024_50241102_39_dialog_content = "Saat aku bangun, aku mendapati diriku duduk di tempat ini.",
  ui_story_5024_50241102_40_dialog_content = "Anak-anak di sana itu… Mereka juga sepertiku. Atau, setidaknya… Seperti diriku yang dulu.",
  ui_story_5024_50241102_41_dialog_content = "\"Bahagia adalah saat senar digulung lagi. Derita adalah saat sendi-sendi mengendur…\"",
  ui_story_5024_50241102_42_dialog_content = "Hanya itu yang mereka tahu. Mereka sama sekali tak punya emosi lagi.",
  ui_story_5024_50241102_43_dialog_content = "Aku juga tahu seperti apa rasanya…",
  ui_story_5024_50241102_44_dialog_content = "Aku tak punya kekuatan istimewa seperti Aurorian, tapi juga tak punya kekuatan dan ketangguhan seperti Eclipsite…",
  ui_story_5024_50241102_45_dialog_content = "Aku bahkan tak punya tubuh yang nyata.",
  ui_story_5024_50241102_46_dialog_content = "Dan sekarang… Karena sendi dan mesin penggerakku <color=#FFB400>sudah hilang semua</color>, aku jadi bertanya-tanya… Apa jadinya diriku nanti?",
  ui_story_5024_50241102_47_dialog_content = "PlayerName… kuharap kau bisa menunjukkannya kepadaku.",
  ui_story_5024_50241102_48_dialog_content = "(Lenore… Inikah yang terjadi pada orang-orang yang terlalu lama terkurung di sini?)",
  ui_story_5024_50241102_49_dialog_content = "Lenore… Kau hanya perlu… mengikuti kata hatimu sendiri.",
  ui_story_5024_50241102_50_dialog_content = "Ikuti… kata hatiku sendiri?",
  ui_story_5024_50241102_51_dialog_content = "Tak ada yang bilang bahwa kau terlahir sebagai boneka dan tak ada pula yang bilang bahwa kau harus menjadi seorang Aurorian.",
  ui_story_5024_50241102_52_dialog_content = "Kalau selama ini yang kauinginkan adalah punya tubuh sungguhan…",
  ui_story_5024_50241102_53_dialog_content = "Kenapa tak kaubuang saja keraguanmu dan terima jati dirimu yang baru ini?",
  ui_story_5024_50241102_54_dialog_content = "Begitu rupanya…",
  ui_story_5024_50241102_55_dialog_content = "Aku… aku akan berusaha semampuku untuk memahami kata-katamu.",
  ui_story_5024_50241102_56_dialog_content = "... Begitu, ya.",
  ui_story_5024_50241102_57_dialog_content = "Sepertinya… akhirnya, harapan ibunya terwujud…",
  ui_story_5024_50241102_58_dialog_content = "Harapan ibunya?",
  ui_story_5024_50241102_59_dialog_content = "Ya…",
  ui_story_5024_50241102_60_dialog_content = "Saat pertama kali aku melihat ibunya, dia putus asa… Putus asa dan tak tahu lagi harus berbuat apa…",
  ui_story_5024_50241102_61_dialog_content = "Dia bilang, dia mencari sesuatu yang kemungkinan besar memang tak pernah ada…",
  ui_story_5024_50241102_62_dialog_content = "Suatu cara untuk mengubah putri sulungnya, yang kehilangan tubuhnya, kembali menjadi Aurorian seperti wajarnya.",
  ui_story_5024_50241102_63_dialog_content = "Hal seperti itu tak mungkin bisa terwujud di dunia kita, tapi di tempat ini…",
  ui_story_5024_50241102_64_dialog_content = "Sekecil apa pun kemungkinannya, bisa saja harapan itu akan terwujud.",
  ui_story_5024_50241102_65_dialog_content = "Jadi, maksudnya adalah membiarkan Lenore melupakan seluruh jati dirinya yang dulu… agar dia bisa menerima jati diri barunya sebagai seorang Aurorian?",
  ui_story_5024_50241102_66_dialog_content = "Yap.",
  ui_story_5024_50241102_67_dialog_content = "Sejak awal, dia memang tak ingin pergi dari tempat ini.",
  ui_story_5024_50241102_68_dialog_content = "Dia harus tetap berada di sini selama mungkin sampai jati diri baru itu bisa tertanam dalam jiwa putrinya.",
  ui_story_5024_50241102_69_dialog_content = "Bayangan yang tadi menarik Lenore masuk ke sini… Pasti itu sisa-sisa kesadaran ibunya.",
  ui_story_5024_50241102_70_dialog_content = "Ini sulit dipahami…",
  ui_story_5024_50241102_71_dialog_content = "Dia berdiri di atas panggung dan melantunkan lagu anak-anak untuk menghibur mereka, padahal dia sendiri menanggung beban begitu berat di dalam hatinya…",
  ui_story_5024_50241102_72_dialog_content = "(Seperti itukah… seorang ibu?)",
  ui_story_5024_50241102_73_dialog_content = "Sebenarnya, setelah mendengarkan kisah Giles kemarin…",
  ui_story_5024_50241102_74_dialog_content = "Dulu, Lenore takut dengan hasil semacam itu…",
  ui_story_5024_50241102_75_dialog_content = "Namun, begitu Lenore merasakan sisa-sisa kesadaran Ibu…",
  ui_story_5024_50241102_76_dialog_content = "Tak ada lagi duka atau rasa takut…",
  ui_story_5024_50241102_77_dialog_content = "Lenore merasa…",
  ui_story_5024_50241102_78_dialog_content = "Suatu perasaan menggelitik di dalam hati, dan kehangatan yang mengalir…",
  ui_story_5024_50241102_79_dialog_content = "…",
  ui_story_5024_50241102_80_dialog_content = "…",
  ui_story_5024_50241102_81_dialog_content = "Lenore… Kau…",
  ui_story_5024_50241102_82_dialog_content = "Kau menangis?",
  ui_story_5024_50241102_83_dialog_content = "Lenore tidak tahu… Lenore belum pernah merasa seperti ini…",
  ui_story_5024_50241102_84_dialog_content = "May, apa kau juga merasakan hal yang sama?",
  ui_story_5024_50241102_85_dialog_content = "Tolong izinkan Lenore memelukmu.",
  ui_story_5024_50241102_86_dialog_content = "*Sroot*",
  ui_story_5024_50241102_87_dialog_content = "*Hiks* Kakak…",
  ui_story_5024_50241102_88_dialog_content = "<color=#e8d9bb>Klik… Klik…</color>",
  ui_story_5024_50241102_89_dialog_content = "Usap air matamu, anak domba yang tersesat…",
  ui_story_5024_50241102_90_dialog_content = "Panggung memanggilmu.",
  ui_story_5024_50241102_91_dialog_content = "Kalau tak segera menemukan Gretel, kita akan terlambat untuk pertunjukannya.",
  ui_story_5024_50241102_92_dialog_content = "Lenore… Silakan duduk di auditorium.",
  ui_story_5024_50241102_93_dialog_content = "Nikmatilah pertunjukan Anjing Baik yang Mengantuk demi ibumu…",
  ui_story_5024_50241102_94_dialog_content = "Ini cukup bermakna.",
  ui_story_5024_50241102_95_dialog_content = "<color=#e8d9bb>Duk, duk, duk…</color>",
  ui_story_5024_50241102_96_dialog_content = "Hah???",
  ui_story_5024_50241102_97_dialog_content = "Itu seperti suara langkah kaki!",
  ui_story_5024_50241102_98_dialog_content = "Apa masih ada Eclipsite lagi?",
  ui_story_5024_50241102_99_dialog_content = "PlayerName, ayo periksa panggungnya!",
  ui_story_5024_50241201_1_dialog_content = "<color=#e8d9bb>Theater, di depan panggung</color>",
  ui_story_5024_50241201_2_dialog_content = "<color=#e8d9bb>Duk, duk… Duk, duk…</color>",
  ui_story_5024_50241201_3_dialog_content = "(Makin mendekat…)",
  ui_story_5024_50241201_4_dialog_content = "<size=33>PlayerName, bersiaplah…</size>",
  ui_story_5024_50241201_5_dialog_content = "Ayo kita habisi nyawa kawanan Eclipsite itu.",
  ui_story_5024_50241201_6_dialog_content = "Lenore akan bantu.",
  ui_story_5024_50241201_7_dialog_content = "<color=#e8d9bb>Tak-tuk… Tak-tuk…</color>",
  ui_story_5024_50241201_8_dialog_content = "Siapa yang tadi berteriak keras-keras di sini?",
  ui_story_5024_50241201_9_dialog_content = "<size=45>Gretel?</size>",
  ui_story_5024_50241201_10_dialog_content = "Gretel!",
  ui_story_5024_50241201_11_dialog_content = "<size=33>… Hati-hati, PlayerName. Kita harus lebih dulu memastikan kondisi mentalnya.</size>",
  ui_story_5024_50241201_12_dialog_content = "(Biar aku saja…)",
  ui_story_5024_50241201_13_dialog_content = "Apa-apaan kau…",
  ui_story_5024_50241201_14_dialog_content = "Apa kau tahu siapa dirimu dan apa yang kaulakukan di sini?",
  ui_story_5024_50241201_15_dialog_content = "(Sungguh lugas dan tanpa basa-basi!)",
  ui_story_5024_50241201_16_dialog_content = "Kau Carleen? Dan…",
  ui_story_5024_50241201_17_dialog_content = "PlayerName?",
  ui_story_5024_50241201_18_dialog_content = "(Syukurlah, sepertinya dia masih sadar… Matanya tak menyiratkan ketakutan…)",
  ui_story_5024_50241201_19_dialog_content = "Bagaimana kalian bisa masuk ke sini?",
  ui_story_5024_50241201_20_dialog_content = "Ceritanya panjang… Menurutmu, tempat ini… agak seram, tidak?",
  ui_story_5024_50241201_21_dialog_content = "Tidak terlalu buruk. Aku sudah melakukan banyak riset dan perencanaan sebelum ke sini.",
  ui_story_5024_50241201_22_dialog_content = "Rumah ini mungkin memang aneh, tapi aku berhasil menemukannya.",
  ui_story_5024_50241201_23_dialog_content = "Dengan begitu, tempat ini justru jadi tempat paling aman di dunia…",
  ui_story_5024_50241201_24_dialog_content = "Kau masih ingat bagaimana kau bisa masuk ke sini?",
  ui_story_5024_50241201_25_dialog_content = "…",
  ui_story_5024_50241201_26_dialog_content = "Kapan pertunjukannya akan dimulai?",
  ui_story_5024_50241201_27_dialog_content = "(Dia mengalihkan topik pembicaraan!)",
  ui_story_5024_50241201_28_dialog_content = "Barangkali, Gretel terlalu sombong untuk mengakui bahwa sebenarnya dia tak tahu cara dia bisa masuk ke sini.",
  ui_story_5024_50241201_29_dialog_content = "(Terserah, deh. Sekarang ini, prioritas utama kita adalah menuntaskan pertunjukannya!)",
  ui_story_5024_50241201_30_dialog_content = "Gretel, kau kan sangat cerdas. Aku yakin kau pasti bisa memahami apa yang akan kusampaikan setelah ini…",
  ui_story_5024_50241201_31_dialog_content = "Jangan bertele-tele.",
  ui_story_5024_50241201_32_dialog_content = "(PlayerName, sabarlah, bersikaplah toleran, dan lembut…)",
  ui_story_5024_50241201_33_dialog_content = "Saat ini, kita berada di Theater, dan para pengunjungnya bisa pergi dengan leluasa.",
  ui_story_5024_50241201_34_dialog_content = "Manor of Truth di luar Theater ini adalah milik True Order…",
  ui_story_5024_50241201_35_dialog_content = "Bahkan mereka sendiri saja tak bisa dengan mudah masuk ke sini. Namun, Gretel…",
  ui_story_5024_50241201_36_dialog_content = "… Kau adalah orang terpilih yang beruntung!",
  ui_story_5024_50241201_37_dialog_content = "Aku orang terpilih? Bagaimana denganmu?",
  ui_story_5024_50241201_38_dialog_content = "Ya, kita harus bekerja sama untuk menuntaskan pertunjukan Anjing Baik yang Mengantuk!",
  ui_story_5024_50241201_39_dialog_content = "Itu satu-satunya cara agar kita bisa keluar dari tempat ini.",
  ui_story_5024_50241201_40_dialog_content = "Kakakmu mencari-carimu. Aku tahu, kau pasti sangat merindukannya!",
  ui_story_5024_50241201_41_dialog_content = "…",
  ui_story_5024_50241201_42_dialog_content = "Kaulah yang pertama masuk ke Theater ini. Jadi, kau akan memerankan sang <color=#FFB400>Tuan</color>.",
  ui_story_5024_50241201_43_dialog_content = "Bisa, 'kan, Gretel?",
  ui_story_5024_50241201_44_dialog_content = "… Aku akan memerankan sang Tuan…",
  ui_story_5024_50241201_45_dialog_content = "… Gretel, apa ada yang ingin kautanyakan atau yang membuatmu ragu?",
  ui_story_5024_50241201_46_dialog_content = "Tidak. Ayo kita mulai.",
  ui_story_5024_50241201_47_dialog_content = "(Ini… sepertinya kok terlalu mudah?)",
  ui_story_5024_50241201_48_dialog_content = "Giles, semua pemeran sudah siap.",
  ui_story_5024_50241201_49_dialog_content = "Para aktor, perlengkapan, dan penonton…",
  ui_story_5024_50241201_50_dialog_content = "Lenore akan bertepuk tangan untuk kalian!",
  ui_story_5024_50241201_51_dialog_content = "Berdasarkan pengalamanku dulu, ada beberapa hal yang perlu kusampaikan…",
  ui_story_5024_50241201_52_dialog_content = "Pertama, begitu pertunjukannya dimulai, tak ada jeda dan kita tak boleh berhenti di tengah jalan…",
  ui_story_5024_50241201_53_dialog_content = "Apa pun yang terjadi selama pertunjukan, kita harus terus menyesuaikan diri dan mengatasinya.",
  ui_story_5024_50241201_54_dialog_content = "Kedua, bagian yang tak terlalu jelas dari lagu anak-anaknya bisa diperlakukan biasa saja selama pertunjukan…",
  ui_story_5024_50241201_55_dialog_content = "Improvisasi kita harus tepat dan kita tak boleh sampai bengong karena tak tahu apa yang harus dilakukan.",
  ui_story_5024_50241201_56_dialog_content = "Terakhir, tapi yang terpenting, ini bukan permainan…",
  ui_story_5024_50241201_57_dialog_content = "Yakinlah pada tokoh yang kalian perankan, dan percayailah keyakinan kalian itu.",
  ui_story_5024_50241201_58_dialog_content = "Paham. Kalau harus serius, aku tak pernah gagal, kok.",
  ui_story_5024_50241201_59_dialog_content = "Aku… Aku tidak takut.",
  ui_story_5024_50241201_60_dialog_content = "…",
  ui_story_5024_50241201_61_dialog_content = "Ya! Kerja sama tim yang bagus adalah kunci agar kita berhasil.",
  ui_story_5024_50241201_62_dialog_content = "Hahahah. Semuanya, bersiaplah! Tirai akan segera diangkat…",
  ui_story_5024_50241201_63_dialog_content = "<color=#e8d9bb>Klik… Klik…</color>",
  ui_story_5024_50241201_64_dialog_content = "<color=#e8d9bb>Dengan bangga kami persembahkan Anjing Baik yang Mengantuk. Selamat menikmati!</color>",
  ui_story_5024_50241201_65_dialog_content = "<color=#e8d9bb>\"Bangunlah… Bangunlah…\"</color>",
  ui_story_5024_50241201_66_dialog_content = "<color=#e8d9bb>\"Bangun rumah yang indah.\"</color>",
  ui_story_5024_50241201_67_dialog_content = "<color=#e8d9bb>\"Bukan untuk Jenderal atau Tuan…\"</color>",
  ui_story_5024_50241201_68_dialog_content = "<color=#e8d9bb>Namun untuk si anjing baik yang mengantuk di dekat perapian.</color>",
  ui_story_5024_50241201_69_dialog_content = "<color=#e8d9bb>Bukalah, bukalah…</color>",
  ui_story_5024_50241201_70_dialog_content = "<color=#e8d9bb>Buka pintu masuk ke rumah.</color>",
  ui_story_5024_50241201_71_dialog_content = "<color=#e8d9bb>Si anak domba, si kucing, dan si burung hantu salju gelandangan…</color>",
  ui_story_5024_50241201_72_dialog_content = "<color=#e8d9bb>Mengitari si anjing baik yang mengantuk di dekat perapian.</color>",
  ui_story_5024_50241201_73_dialog_content = "<color=#e8d9bb>Kurung mereka, kurung mereka…</color>",
  ui_story_5024_50241201_74_dialog_content = "<color=#e8d9bb>Kuncilah pintu depan rumah.</color>",
  ui_story_5024_50241201_75_dialog_content = "<color=#e8d9bb>Gelak tawa pesta mengalun keluar dari jendela…</color>",
  ui_story_5024_50241201_76_dialog_content = "<color=#e8d9bb>Namun tak bisa membangunkan si anjing baik yang tidur di dekat perapian.</color>",
  ui_story_5024_50241201_77_dialog_content = "<color=#e8d9bb>Kurung mereka, kurung mereka…</color>",
  ui_story_5024_50241201_78_dialog_content = "<color=#e8d9bb>Kuncilah pintu depan rumah.</color>",
  ui_story_5024_50241201_79_dialog_content = "<color=#e8d9bb>Di dalam hangat dan nyaman, meski tanpa kehadiran tuan…</color>",
  ui_story_5024_50241201_80_dialog_content = "<color=#e8d9bb>Tak usah hiraukan si anjing tua baik yang mengantuk di dekat perapian.</color>",
  ui_story_5024_50241201_81_dialog_content = "<color=#e8d9bb>Kurung, kurung mereka…</color>",
  ui_story_5024_50241201_82_dialog_content = "<anim type=Shake>Groar…</anim>",
  ui_story_5024_50241201_83_dialog_content = "<anim type=Shake>Gaar…</anim>",
  ui_story_5024_50241201_84_dialog_content = "<anim type=Shake><size=45>*Meraung*</size></anim>",
  ui_story_5024_50241201_85_dialog_content = "Kenapa harus sekarang, sih?",
  ui_story_5024_50241201_86_dialog_content = "May! Fokus!",
  ui_story_5024_50241201_87_dialog_content = "PlayerName, ini peluang emas!",
  ui_story_5024_50241201_88_dialog_content = "Ayo kita kurung kawanan Eclipsite ini!",
  ui_story_5024_50241201_89_dialog_content = "Hah! Menarik!",
  ui_story_5024_50241201_90_dialog_content = "Itu ide yang sangat cemerlang! Ayo kita berikan pelajaran untuk kawanan Eclipsite ini!",
  ui_story_5024_50241402_1_dialog_content = "<anim type=Shake>Gaar…</anim>",
  ui_story_5024_50241402_2_dialog_content = "Heh, heh…",
  ui_story_5024_50241402_3_dialog_content = "Heheh…",
  ui_story_5024_50241402_4_dialog_content = "(Berhasil tidak, ya?)",
  ui_story_5024_50241402_5_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5024_50241402_6_dialog_content = "<color=#e8d9bb>Kurung mereka, kurung mereka…</color>",
  ui_story_5024_50241402_7_dialog_content = "<color=#e8d9bb>Kurung kawanan Eclipsite itu.</color>",
  ui_story_5024_50241402_8_dialog_content = "(Kita berhasil!)",
  ui_story_5024_50241402_9_dialog_content = "<color=#e8d9bb>Betapa lucunya mereka, tidur berdampingan…</color>",
  ui_story_5024_50241402_10_dialog_content = "<color=#e8d9bb>Si anak domba, si kucing, dan si burung hantu salju, bersama si anjing baik yang mengantuk.</color>",
  ui_story_5024_50241402_11_dialog_content = "<color=#e8d9bb>Anak domba, kucing, burung hantu salju, dan anjing baik yang mengantuk.</color>",
  ui_story_5024_50241402_12_dialog_content = "<color=#e8d9bb>Klik… Klik…</color>",
  ui_story_5024_50241402_13_dialog_content = "*Terengah-engah*",
  ui_story_5024_50241402_14_dialog_content = "Hiss.. Huh…",
  ui_story_5024_50241402_15_dialog_content = "(Bukan masalah… Sama sekali bukan masalah…)",
  ui_story_5024_50241402_16_dialog_content = "(Hening lama… Seakan waktu berhenti…)",
  ui_story_5024_50241402_17_dialog_content = "(Aku bisa mendengar napas mereka dan merasakan tubuh merinding setelah susah payah berhasil menyelamatkan diri…)",
  ui_story_5024_50241402_18_dialog_content = "(Apa kita berhasil?)",
  ui_story_5024_50241402_19_dialog_content = "<size=45><color=#e8d9bb>Duarr…</color></size>",
  ui_story_5024_50241402_20_dialog_content = "<size=45>Aduh!</size>",
  ui_story_5024_50241402_21_dialog_content = "Bagus sekali, PlayerName! Sungguh pertunjukan yang menakjubkan!",
  ui_story_5024_50241402_22_dialog_content = "Ayo! Beri hormat kepada para penonton!",
  ui_story_5024_50241402_23_dialog_content = "<color=#e8d9bb>*Tepuk tangan*</color>",
  ui_story_5024_50241402_24_dialog_content = "Ah!",
  ui_story_5024_50241402_25_dialog_content = "Lenore sangat khawatir saat tirainya diturunkan!",
  ui_story_5024_50241402_26_dialog_content = "May, kau pasti sangat ketakutan!",
  ui_story_5024_50241402_27_dialog_content = "Lenore…",
  ui_story_5024_50241402_28_dialog_content = "Aaaaaaaah… Tadi May takut sekali!",
  ui_story_5024_50241402_29_dialog_content = "Fyuh… Gampang sekali…",
  ui_story_5024_50241402_30_dialog_content = "PlayerName, kita berhasil!",
  ui_story_5024_50241402_31_dialog_content = "(Wajah Carleen bersimbah keringat…)",
  ui_story_5024_50241402_32_dialog_content = "Carleen, kita sudah berusaha keras.",
  ui_story_5024_50241402_33_dialog_content = "Lalu, Gretel…",
  ui_story_5024_50241402_34_dialog_content = "(…)",
  ui_story_5024_50241402_35_dialog_content = "…!!!",
  ui_story_5024_50241402_36_dialog_content = "Gretel… Mana Gretel?",
  ui_story_5024_50241402_37_dialog_content = "… Gretel! Gretel?",
  ui_story_5024_50241402_38_dialog_content = "Cukup sudah! Keluarlah sekarang. Kita akan pergi!",
  ui_story_5024_50241402_39_dialog_content = "Lenore, dari auditorium, apa kau melihat Gretel meninggalkan panggung?",
  ui_story_5024_50241402_40_dialog_content = "Tidak… Sama sekali tidak!",
  ui_story_5024_50241402_41_dialog_content = "Aku menonton pertunjukannya dengan cermat. Tak seorang pun meninggalkan panggung…",
  ui_story_5024_50241402_42_dialog_content = "Ah!",
  ui_story_5024_50241402_43_dialog_content = "Apa mungkin…",
  ui_story_5024_50241402_44_dialog_content = "<color=#e8d9bb>Gruduk…</color>",
  ui_story_5024_50241402_45_dialog_content = "<color=#e8d9bb>Gruduk… Gruduk…</color>",
  ui_story_5024_50241402_46_dialog_content = "Guncangannya keras sekali!",
  ui_story_5024_50241402_47_dialog_content = "(Tidak!)",
  ui_story_5024_50241402_48_dialog_content = "Kita harus pergi! Sekarang juga!",
  ui_story_5024_50241402_49_dialog_content = "Menjauhlah dari panggung!",
  ui_story_5024_50241501_1_dialog_content = "<color=#e8d9bb>Duarr…</color>",
  ui_story_5024_50241501_2_dialog_content = "<size=45>Di sini!</size>",
  ui_story_5024_50241501_3_dialog_content = "Bocah mana yang berniat pergi?",
  ui_story_5024_50241501_4_dialog_content = "Ada anak nakal yang berusaha menyelinap pergi dari rumah indah ini…",
  ui_story_5024_50241501_5_dialog_content = "Tuan akan mengurungnya!",
  ui_story_5024_50241501_6_dialog_content = "Apa maksudmu? Pertunjukannya sudah selesai.",
  ui_story_5024_50241501_7_dialog_content = "Selesai?",
  ui_story_5024_50241501_8_dialog_content = "Heh heh…",
  ui_story_5024_50241501_9_dialog_content = "<size=45>Sama sekali belum!</size>",
  ui_story_5024_50241501_10_dialog_content = "PlayerName, jangan buang-buang waktu!",
  ui_story_5024_50241501_11_dialog_content = "Lihat!",
  ui_story_5024_50241501_12_dialog_content = "Manor of Truth mulai runtuh…",
  ui_story_5024_50241501_13_dialog_content = "Pertunjukannya masih berlangsung!",
  ui_story_5024_50241501_14_dialog_content = "Karena kalian sudah masuk ke Theater milik sang Tuan…",
  ui_story_5024_50241501_15_dialog_content = "Aku harus menjamu kalian!",
  ui_story_5024_50241501_16_dialog_content = "Tirainya sudah terbuka begitu kita masuk ke dunia teater ini!",
  ui_story_5024_50241501_17_dialog_content = "… Apa lagi yang kalian tunggu?",
  ui_story_5024_50241501_18_dialog_content = "Apa kalian perlu diberi pelajaran oleh sang Tuan?",
  ui_story_5024_50241501_19_dialog_content = "Tuan?",
  ui_story_5024_50241501_20_dialog_content = "Oh, tidak… Gretel sudah kehilangan akal sehatnya!",
  ui_story_5024_50241501_21_dialog_content = "Dia menganggap dirinya sang Tuan di teater ini!",
  ui_story_5024_50241501_22_dialog_content = "Siapa yang tadi berteriak keras-keras di sini?",
  ui_story_5024_50241501_23_dialog_content = "…",
  ui_story_5024_50241501_24_dialog_content = "Rumah ini mungkin memang aneh, tapi aku berhasil menemukannya.",
  ui_story_5024_50241501_25_dialog_content = "(Aku khawatir, jangan-jangan sedari tadi dia memang sudah kehilangan akal sehatnya…)",
  ui_story_5024_50241501_26_dialog_content = "PlayerName, tirainya terangkat. Cepat pulihkan kesadarannya!",
  ui_story_5024_50241501_27_dialog_content = "Kalau tidak, kau tak akan bisa membawanya pergi dari sini!",
  ui_story_5024_50241501_28_dialog_content = "Pergi?",
  ui_story_5024_50241501_29_dialog_content = "Kesabaranku sudah hampir habis. Berapa kali harus kuulangi kata-kataku?",
  ui_story_5024_50241501_30_dialog_content = "Kalian, makhluk-makhluk penghibur…",
  ui_story_5024_50241501_31_dialog_content = "<size=45>Harus tetap di sini!</size>",
  ui_story_5024_50241501_32_dialog_content = "Lenore! Awas!",
  ui_story_5024_50241501_33_dialog_content = "… Aah!",
  ui_story_5024_50241501_34_dialog_content = "Hmm… Huh…",
  ui_story_5024_50241501_35_dialog_content = "Kurung, kurunglah…",
  ui_story_5024_50241501_36_dialog_content = "Kurunglah <color=#FFB400>semuanya</color>…",
  ui_story_5024_50241501_37_dialog_content = "(Kejadian itu terulang lagi!)",
  ui_story_5024_50241501_38_dialog_content = "(Apa ini memang bagian dari adegan dramanya?)",
  ui_story_5024_50241501_39_dialog_content = "PlayerName, dia mendesak kita ke belakang panggung!",
  ui_story_5024_50241501_40_dialog_content = "Jangan sampai kita terdesak ke sana!",
  ui_story_5024_50241501_41_dialog_content = "<color=#e8d9bb>Klik… Klik…</color>",
  ui_story_5024_50241501_42_dialog_content = "Tirainya terangkat lagi!",
  ui_story_5024_50241501_43_dialog_content = "Sungguh anjing yang pintar!",
  ui_story_5024_50241501_44_dialog_content = "Pertunjukannya tak hanya sebatas di atas panggung sempit ini.",
  ui_story_5024_50241501_45_dialog_content = "Untuk anak-anak nakal yang perlu diajari disiplin dan perbaikan…",
  ui_story_5024_50241501_46_dialog_content = "Tempat kalian adalah di belakang panggung!",
  ui_story_5024_50241501_47_dialog_content = "Anak-anak nakal…",
  ui_story_5024_50241501_48_dialog_content = "Kalau punya lilin, apa May juga anak nakal?",
  ui_story_5024_50241501_49_dialog_content = "Tak ada yang suka anak nakal…",
  ui_story_5024_50241501_50_dialog_content = "Apa Tuan tak suka kucing?",
  ui_story_5024_50241501_51_dialog_content = "May! Sadarlah, May!",
  ui_story_5024_50241501_52_dialog_content = "Umm?",
  ui_story_5024_50241501_53_dialog_content = "Kenapa aku bilang begitu, ya?",
  ui_story_5024_50241501_54_dialog_content = "PlayerName, cari solusinya!",
  ui_story_5024_50241501_55_dialog_content = "Akal sehat May… bersama rumah ini… digerogoti oleh suatu hal yang tak bisa dijelaskan!",
  ui_story_5024_50241501_56_dialog_content = "Kalau area ini terus meluas… tak seorang pun dari kita akan bisa keluar hidup-hidup!",
  ui_story_5024_50241501_57_dialog_content = "Tak ada gunanya bersembunyi darinya…",
  ui_story_5024_50241501_58_dialog_content = "Kurasa kita harus membantunya menuntaskan <color=#FFB400>pertunjukan</color> akhir ini!",
  ui_story_5024_50241501_59_dialog_content = "Kalau kita bisa mengalahkan sang Tuan, pada akhirnya pertunjukan ini tak akan berantakan!",
  ui_story_5024_50241502_1_dialog_content = "Hosh… Hosh… Hosh…",
  ui_story_5024_50241502_2_dialog_content = "Aduh, aduh!",
  ui_story_5024_50241502_3_dialog_content = "Kumohon… Lepaskan aku!",
  ui_story_5024_50241502_4_dialog_content = "Hah? Gretel sudah tak sadar?",
  ui_story_5024_50241502_5_dialog_content = "Gretel! Gretel, sadarlah!",
  ui_story_5024_50241502_6_dialog_content = "Apa yang harus kita lakukan, PlayerName?",
  ui_story_5024_50241502_7_dialog_content = "<color=#e8d9bb>Klik… Klik…</color>",
  ui_story_5024_50241502_8_dialog_content = "Pertunjukan sudah selesai. Ayo kita bawa bocah ini ke belakang panggung.",
  ui_story_5024_50241502_9_dialog_content = "Kita pulihkan kewarasannya dengan cara yang sama.",
  ui_story_5024_50241502_10_dialog_content = "<color=#e8d9bb>Di area belakang panggung di Theater…</color>",
  ui_story_5024_50241502_11_dialog_content = "Kepalaku sakit… Di mana aku?",
  ui_story_5024_50241502_12_dialog_content = "Gretel!",
  ui_story_5024_50241502_13_dialog_content = "Apa kau bisa mendengarku?",
  ui_story_5024_50241502_14_dialog_content = "Kakak… Kakak…",
  ui_story_5024_50241502_15_dialog_content = "Mana kakakku?",
  ui_story_5024_50241502_16_dialog_content = "…",
  ui_story_5024_50241502_17_dialog_content = "Jangan takut, Gretel. Kami akan membawamu pergi dari sini.",
  ui_story_5024_50241502_18_dialog_content = "… PlayerName, bisa tolong lepaskan aku?",
  ui_story_5024_50241502_19_dialog_content = "Aku tak butuh bantuanmu.",
  ui_story_5024_50241502_20_dialog_content = "(Bagus sekali! Dia sudah kembali normal!)",
  ui_story_5024_50241502_21_dialog_content = "Kau sungguh tak sopan…",
  ui_story_5024_50241502_22_dialog_content = "Namun, aku senang melihatmu sudah baik-baik saja.",
  ui_story_5024_50241502_23_dialog_content = "… Omonganmu aneh.",
  ui_story_5024_50241502_24_dialog_content = "\"Satu-satunya Truth terkandung dalam lagu anak-anak yang harus dilantunkan berulang kali. Nasib si pemeran tetap tak diketahui, ibarat syair yang belum selesai dalam halaman naskahnya.\"",
  ui_story_5024_50241502_25_dialog_content = "\"Sebelum tirai panggung diturunkan saat adegan akhir akbar, tak seorang pun boleh pergi.\"",
  ui_story_5024_50241502_26_dialog_content = "Hahahahah! Akhirnya aku paham!",
  ui_story_5024_50241502_27_dialog_content = "Rupanya inilah makna sebenarnya dari ramalan itu…",
  ui_story_5024_50241502_28_dialog_content = "Pertunjukan Anjing Baik yang Mengantuk dimulai begitu kita masuk ke Theater.",
  ui_story_5024_50241502_29_dialog_content = "Satu-satunya cara agar pertunjukannya berhasil…",
  ui_story_5024_50241502_30_dialog_content = "Adalah dengan menghancurkan belenggu sang Tuan di atas dan di luar panggung…",
  ui_story_5024_50241502_31_dialog_content = "<size=45><color=#FFB400>Hancurkan semuanya</color>!</size>",
  ui_story_5024_50241502_32_dialog_content = "Inilah kebenaran di balik pertunjukan yang sempurna…",
  ui_story_5024_50241502_33_dialog_content = "(Kurasa akhirnya aku berhasil memahami bagian yang samar dari lagu anak-anak itu…)",
  ui_story_5024_50241502_34_dialog_content = "Kau bergumam apa, sih?",
  ui_story_5024_50241502_35_dialog_content = "Sebentar! Jangan lari!",
  ui_story_5024_50241502_36_dialog_content = "PlayerName, ayo kejar dia!",
  ui_story_5024_50241502_37_dialog_content = "<color=#e8d9bb>Theater, di depan panggung</color>",
  ui_story_5024_50241502_38_dialog_content = "Hosh… Gretel… Ada apa?",
  ui_story_5024_50241502_39_dialog_content = "Apa?",
  ui_story_5024_50241502_40_dialog_content = "PlayerName, bagaimana mungkin ini bisa terjadi?",
  ui_story_5024_50241502_41_dialog_content = "Eee… Memangnya ada apa?",
  ui_story_5024_50241502_42_dialog_content = "Anjing Baik yang Mengantuk… sudah selesai?",
  ui_story_5024_50241502_43_dialog_content = "Aku melewatkan semuanya!",
  ui_story_5024_50241502_44_dialog_content = "Padahal aku sangat ingin menontonnya… Bahkan, aku sampai membuat begitu banyak catatan…",
  ui_story_5024_50241502_45_dialog_content = "Aku…",
  ui_story_5024_50241502_46_dialog_content = "Aku…",
  ui_story_5024_50241502_47_dialog_content = "?!",
  ui_story_5024_50241502_48_dialog_content = "Gawat! May… tetap di belakangku!",
  ui_story_5024_50241502_49_dialog_content = "<size=33>Pfft…</size>",
  ui_story_5024_50241502_50_dialog_content = "<size=45>Hahahah!</size>",
  ui_story_5024_50241502_51_dialog_content = "Aku hanya bercanda. Kalian mudah sekali tertipu. Dasar dungu.",
  ui_story_5024_50241502_52_dialog_content = "Hoi! Coba ulangi kalau berani!",
  ui_story_5024_50241502_53_dialog_content = "Walau aku kehilangan akal sehatku pada momen yang sangat penting, aku tahu kali ini kalian sudah menyelamatkan nyawaku.",
  ui_story_5024_50241502_54_dialog_content = "Terima kasih, PlayerName, Carleen, dan…",
  ui_story_5024_50241502_55_dialog_content = "Lenore…",
  ui_story_5024_50241502_56_dialog_content = "May!",
  ui_story_5024_50241502_57_dialog_content = "Giles~",
  ui_story_5024_50241502_58_dialog_content = "Setidaknya kita masih ingat nama kita sendiri.",
  ui_story_5024_50241502_59_dialog_content = "Tak banyak yang bisa kuingat, tapi aku ingat sempat bertarung melawan PlayerName dalam mimpiku.",
  ui_story_5024_50241502_60_dialog_content = "Kacau sekali. Aku bahkan mempertunjukkan Anjing Baik yang Mengantuk dalam mimpiku.",
  ui_story_5024_50241502_61_dialog_content = "Namun, sayang sekali.",
  ui_story_5024_50241502_62_dialog_content = "… Lain kali, aku akan menontonnya!",
  ui_story_5024_50241502_63_dialog_content = "(Semoga tak perlu ada lain kali!)",
  ui_story_5024_50241502_64_dialog_content = "<color=#e8d9bb>Krieeek…</color>",
  ui_story_5024_50241502_65_dialog_content = "Pintunya sudah terbuka, PlayerName!",
  ui_story_5024_50241502_66_dialog_content = "Semuanya, ayo pergi dari tempat ini!",
  ui_story_5024_50241502_67_dialog_content = "Teman-teman kita di True Order pasti sangat penasaran dengan apa yang kita alami di sini!",
  ui_story_5024_50241601_1_dialog_content = "PlayerName, kau berhasil!",
  ui_story_5024_50241601_2_dialog_content = "… Selamat datang kembali di dunia nyata.",
  ui_story_5024_50241601_3_dialog_content = "Dunia nyata?",
  ui_story_5024_50241601_4_dialog_content = "PlayerName, aku juga punya kabar baik.",
  ui_story_5024_50241601_5_dialog_content = "Silakan buka tirainya dan lihatlah ke luar jendela.",
  ui_story_5024_50241601_6_dialog_content = "Hah?",
  ui_story_5024_50241601_7_dialog_content = "Ke luar jendela…",
  ui_story_5024_50241601_8_dialog_content = "Semuanya kembali normal?",
  ui_story_5024_50241601_9_dialog_content = "Kurasa, inilah ramalan yang sesungguhnya dalam Bloody Bible Prophecy.",
  ui_story_5024_50241601_10_dialog_content = [[
"Satu-satunya Truth terkandung dalam lagu anak-anak yang harus dilantunkan berulang kali. 
Nasib si pemeran tetap tak diketahui, ibarat syair yang belum selesai dalam halaman naskahnya."]],
  ui_story_5024_50241601_11_dialog_content = "\"Sebelum tirai panggung diturunkan saat adegan akhir akbar, tak seorang pun boleh pergi.\"",
  ui_story_5024_50241601_12_dialog_content = "Pintu Theater terbuka setelah tirainya diturunkan. Itulah satu-satunya cara untuk keluar dari Manor of Truth.",
  ui_story_5024_50241601_13_dialog_content = "Truth selalu menuntun langkah kita.",
  ui_story_5024_50241601_14_dialog_content = "Semoga Truth memberkatimu, Victoria!",
  ui_story_5024_50241601_15_dialog_content = "Terima kasih atas kerja keras kalian. Nikmatilah buah manis dari kemenangan kalian.",
  ui_story_5024_50241601_16_dialog_content = "Hmm? Aku melihat beberapa wajah yang tak begitu kukenal.",
  ui_story_5024_50241601_17_dialog_content = "…",
  ui_story_5024_50241601_18_dialog_content = "Tentu saja. Biar saja tetap seperti itu.",
  ui_story_5024_50241601_19_dialog_content = "Namun, yang kumaksud adalah gadis berambut putih itu.",
  ui_story_5024_50241601_20_dialog_content = "Jangan memelintir kata-kataku, Carleen.",
  ui_story_5024_50241601_21_dialog_content = "(Dia mengejekku, ya?)",
  ui_story_5024_50241601_22_dialog_content = "Anu… Kau pasti…",
  ui_story_5024_50241601_23_dialog_content = "Pustakawan di sini, ya?",
  ui_story_5024_50241601_24_dialog_content = "(Hah?!)",
  ui_story_5024_50241601_25_dialog_content = "Hahah… Gadis kecil, sepertinya kau sangat tertarik dengan buku-buku yang ada di Manor of Truth, ya?",
  ui_story_5024_50241601_26_dialog_content = "Kira-kira begitulah… Oh ya, aku Gretel.",
  ui_story_5024_50241601_27_dialog_content = "Gretel… Akan kucoba mengingat namamu.",
  ui_story_5024_50241601_28_dialog_content = "Kalau kau memang tertarik dengan buku-buku ini, bagaimana kalau kau bergabung saja dengan True Order?",
  ui_story_5024_50241601_29_dialog_content = "(Barusan, Lady Victoria mengajaknya secara langsung untuk menjadi anggota True Order, ya?)",
  ui_story_5024_50241601_30_dialog_content = "True Order… Semacam klub baca buku, begitu?",
  ui_story_5024_50241601_31_dialog_content = "(Jawabannya santai sekali!)",
  ui_story_5024_50241601_32_dialog_content = "Hahah… Kurasa, bisa dibilang begitu.",
  ui_story_5024_50241601_33_dialog_content = "Setiap orang punya kebebasan dan hak untuk memahami Truth dengan caranya masing-masing.",
  ui_story_5024_50241601_34_dialog_content = "Kau boleh menganggap True Order adalah semacam klub baca buku. Toh, kebenaran tak akan terhalang gara-gara itu.",
  ui_story_5024_50241601_35_dialog_content = "(Aku paham!)",
  ui_story_5024_50241601_36_dialog_content = "(Sekarang, aku sudah lebih memahami kebenaran…)",
  ui_story_5024_50241601_37_dialog_content = "Baiklah. Faust…",
  ui_story_5024_50241601_38_dialog_content = "Lady Victoria.",
  ui_story_5024_50241601_39_dialog_content = "Tolong antar mereka ke aula jamuan makan.",
  ui_story_5024_50241601_40_dialog_content = "(Kurasa sekarang aku lebih bisa memahami para anggota True Order…)",
  ui_story_5024_50241601_41_dialog_content = "(Mereka tak peduli cara orang menyebarkan atau memperoleh pengetahuan. Mereka juga tak peduli apa pandangan orang luar tentang mereka…)",
  ui_story_5024_50241601_42_dialog_content = "(Bahkan, entah dunia ini nyata dan aman maupun tidak, itu pun tak penting bagi mereka.)",
  ui_story_5024_50241601_43_dialog_content = "(Kepercayaan mereka tentang keyakinan mereka saja sudah cukup untuk menjadi dasar bagi segala hal dalam hidup mereka…)",
  ui_story_5024_50241601_44_dialog_content = "Hmm? PlayerName, apa kau sedang merenungkan sesuatu?",
  ui_story_5024_50241601_45_dialog_content = "Kalau kau penasaran tentang True Order, aku tak keberatan membahasnya secara pribadi denganmu.",
  ui_story_5024_50241601_46_dialog_content = "Hah?",
  ui_story_5024_50241601_47_dialog_content = "… Sejak kapan Victoria punya kemampuan psikis seperti Caelestite?",
  ui_story_5024_50241601_48_dialog_content = "Heheh. Aku tak punya kemampuan psikis luar biasa sepertimu…",
  ui_story_5024_50241601_49_dialog_content = "Namun, Black Tome ini kadang memang membisikkan ramalan-ramalan jelas ke telingaku.",
  ui_story_5024_50241601_50_dialog_content = "Sang Caelestite yang kebingungan tersesat dalam kebenaran…",
  ui_story_5024_50241601_51_dialog_content = "Yang tersisa dalam dirinya hanyalah kepala kosong dan perut keroncongan.",
  ui_story_5024_50241601_52_dialog_content = "Apa!?",
  ui_story_5024_50241601_53_dialog_content = "Itu berarti…",
  ui_story_5024_50241601_54_dialog_content = "Jangan berdiri bengong saja di sana, PlayerName.",
  ui_story_5024_50241601_55_dialog_content = "Lenore dan Giles sudah menuju aula jamuan makan.",
  ui_story_5024_50241601_56_dialog_content = "Heheh. Pesta tanpa kerusuhan akan segera dimulai.",
  ui_story_5024_50241601_57_dialog_content = "Maukah para tamu tak diundang ini bergabung denganku?",
  ui_story_5024_50241601_58_dialog_content = "Tahu, tidak? Jarang sekali aku punya kesempatan untuk sedekat ini dengan Lumopolis Gardens.",
  ui_story_5024_50241601_59_dialog_content = "Bolehkah, Carleen?",
  ui_story_5024_50241601_60_dialog_content = "Um…",
  ui_story_5024_50241601_61_dialog_content = "Dasar wanita sinting!",
  ui_story_5024_50241601_62_dialog_content = "<color=#e8d9bb>Ding… Ding…</color>",
  ui_story_5024_50241601_63_dialog_content = "Semuanya! Mari angkat gelas kita.",
  ui_story_5024_50241601_64_dialog_content = "Bersulang demi para aktor luar biasa dalam pertunjukan ini!",
  ui_story_5024_50241601_65_dialog_content = "Kurasa, kalian pasti sudah tak sabar ingin mendengar cerita mereka selama berada di dalam Theater.",
  ui_story_5024_50241601_66_dialog_content = "Jangan buat kami menunggu terlalu lama, PlayerName…",
  ui_story_5024_50241601_67_dialog_content = "Ahahahah! Anu… aku butuh waktu untuk menata pikiranku…",
  ui_story_5024_50241601_68_dialog_content = "(Kedengarannya cukup aneh, kami berusaha begitu keras untuk masuk ke Theater hanya agar bisa keluar dari sana!)",
  ui_story_5024_50241601_69_dialog_content = "(Aneh pula karena niat kami adalah membantu Lenore menyelamatkan ibunya, tapi kami justru diselamatkan oleh sisa-sisa kesadaran ibunya!)",
  ui_story_5024_50241601_70_dialog_content = "(Menyelamatkan Gretel dengan cara mengalahkannya juga bukanlah cerita yang wajar!)",
  ui_story_5024_50241601_71_dialog_content = "Hahahahahah! Jangan membuat PlayerName kikuk…",
  ui_story_5024_50241601_72_dialog_content = "Karena ceritanya sudah disampaikan, tak usah bingung memikirkan \"bagaimana\" dan \"kenapa\".",
  ui_story_5024_50241601_73_dialog_content = "Kalau kalian tertarik, aku punya beberapa lagu anak-anak yang bisa kunyanyikan untuk kalian.",
  ui_story_5024_50241601_74_dialog_content = "Giles, kau sungguh bijak dan penuh percaya diri!",
  ui_story_5024_50241601_75_dialog_content = "Dari dulu, aku memang bukan pria kacangan. Kalau tawaranku belum cukup menarik…",
  ui_story_5024_50241601_76_dialog_content = "Aku bisa menuliskan beberapa lagu rakyat, di sini, sekarang juga.",
  ui_story_5024_50241601_77_dialog_content = "Tak usah repot-repot!",
  ui_story_5024_50241601_78_dialog_content = "Hmm… Anu…",
  ui_story_5024_50241601_79_dialog_content = "Ada apa, Kak?",
  ui_story_5024_50241601_80_dialog_content = "Mmm… Baru kali ini aku mencicipi tomat panggang asin dengan tentakel Eclipsite…",
  ui_story_5024_50241601_81_dialog_content = "Beginikah rasa makanan di luar sana?",
  ui_story_5024_50241601_82_dialog_content = "Ah! Sebenarnya… kau tak perlu memaksakan diri untuk mencicipinya…",
  ui_story_5024_50241601_83_dialog_content = "Menurutku…",
  ui_story_5024_50241601_84_dialog_content = "Menurutku makanan ini sangat lezat!",
  ui_story_5024_50241601_85_dialog_content = "Uhh? Baiklah kalau begitu… Selera makanmu agak unik, ya…",
  ui_story_5024_50241601_86_dialog_content = "Ada banyak perasaan dan hal di dunia ini yang harus kupelajari.",
  ui_story_5024_50241601_87_dialog_content = "May, maukah kau mengajariku?",
  ui_story_5024_50241601_88_dialog_content = "Aduh…!",
  ui_story_5024_50241601_89_dialog_content = "Permintaanmu berat sekali! Namun, karena kau memintanya dengan sangat sopan…",
  ui_story_5024_50241601_90_dialog_content = "…",
  ui_story_5024_50241601_91_dialog_content = "… Carleen? Kau sama sekali belum menyentuh makananmu…",
  ui_story_5024_50241601_92_dialog_content = "Maaf, aku terpaksa membuat kalian kecewa.",
  ui_story_5024_50241601_93_dialog_content = "Namun, aku sama sekali tak berniat memaksa diri untuk mencicipi makanan seaneh ini.",
  ui_story_5024_50241601_94_dialog_content = "Carleen, tak ada yang merasa kecewa, kok.",
  ui_story_5024_50241601_95_dialog_content = "Kau sudah berbuat begitu banyak untuk mencari Gretel dan menyelidiki berbagai peristiwa janggal di Lumopolis.",
  ui_story_5024_50241601_96_dialog_content = "Aku bisa merasakannya dengan jelas.",
  ui_story_5024_50241601_97_dialog_content = "Kau sudah berusaha sepenuh hati untuk mempertahankan keyakinanmu.",
  ui_story_5024_50241601_98_dialog_content = "Terima kasih atas segala yang telah kaulakukan dalam pencarian orang hilang ini.",
  ui_story_5024_50241601_99_dialog_content = "…",
  ui_story_5024_50241601_100_dialog_content = "Sungguh… sungguh lancang, PlayerName!",
  ui_story_5024_50241601_101_dialog_content = "Jangan berani-berani lagi membaca isi hatiku tanpa seizinku.",
  ui_story_5024_50241601_102_dialog_content = "Aku tak perlu membaca pikiranmu untuk mengetahuinya, kok.",
  ui_story_5024_50241601_103_dialog_content = "Apa sudah saatnya kita pergi?",
  ui_story_5024_50241601_104_dialog_content = "(Sudah berhari-hari aku pergi. Valencia pasti khawatir…)",
  ui_story_5024_50241601_105_dialog_content = "Aww… Apa ini sudah saatnya kita berpisah?",
  ui_story_5024_50241601_106_dialog_content = "Terima kasih banyak atas kemurahan hati dan keramahanmu. Aku akan mempertimbangkan matang-matang tawaran kalian untuk bergabung dengan True Order.",
  ui_story_5024_50241601_107_dialog_content = "Silakan, Nona Manis.",
  ui_story_5024_50241601_108_dialog_content = "Namun… Faust… Karena sekarang Manor of Truth sudah bisa dimasuki…",
  ui_story_5024_50241601_109_dialog_content = "Bagaimana kalau kita undang PlayerName dan teman-temannya untuk menginap di sini?",
  ui_story_5024_50241601_110_dialog_content = "Ohh? Saranmu sungguh luar biasa, Beryl.",
  ui_story_5024_50241601_111_dialog_content = "Benar sekali. Lagi pula, kenapa harus buru-buru?",
  ui_story_5024_50241601_112_dialog_content = "Lady Victoria sudah menyiapkan pesta dansa setelah jamuan makan ini, lalu dilanjutkan dengan sesi membaca buku sebelum tidur…",
  ui_story_5024_50241601_113_dialog_content = "Lalu, besok, kita akan mengikuti Truth Meditation, Noon Salon, dan White Suitcase Poetry Recitation…",
  ui_story_5024_50241601_114_dialog_content = "Uhh… Terima kasih banyak, tapi sepertinya kami tak akan bisa mengikuti semua acara luar biasa itu!",
  ui_story_5024_50241601_115_dialog_content = "(Kurasa, orang-orang ini tak terlalu peduli apakah mereka bisa keluar dari tempat ini atau tidak!)",
  ui_story_5024_50241601_116_dialog_content = "Menginaplah di sini, PlayerName…",
  ui_story_5024_50241601_117_dialog_content = "Pintunya baru saja terbuka, tapi kau malah sudah mau pergi? Ayolah!",
  ui_story_5024_50241601_118_dialog_content = "(Ah oh… aku dikepung…)",
  ui_story_5024_50241601_119_dialog_content = "(Lenore, May, dan Giles ke mana, sih? Aku butuh bantuan…)",
  ui_story_5024_50241601_120_dialog_content = "Umm? Kau sudah mau pergi, PlayerName?",
  ui_story_5024_50241601_121_dialog_content = "Padahal Lenore sudah menyiapkan piama bersih dan mengganti seprai untukmu…",
  ui_story_5024_50241601_122_dialog_content = "PlayerName… memangnya kau tak mau menginap di sini?",
  ui_story_5024_50241601_123_dialog_content = "Aku… aku…",
  ui_story_5024_50241601_124_dialog_content = "Ya!",
  ui_story_5024_50241601_125_dialog_content = "PlayerName, Carleen, Gretel… Kumohon, menginaplah di sini!",
  ui_story_5024_50241601_126_dialog_content = "Beau senang mendengar bahwa kalian mau menginap di sini!",
  ui_story_5024_50241601_127_dialog_content = "Meong!",
  ui_story_5024_50241601_128_dialog_content = "Sebentar. Aku kan tak pernah bilang iya!",
  ui_story_5024_50241601_129_dialog_content = "Aww… PlayerName…",
  ui_story_5024_50241601_130_dialog_content = "Tak punya tanduk saat pagi hari, punya dua tanduk saat siang, dan punya satu tanduk saat tengah malam…",
  ui_story_5024_50241601_131_dialog_content = "Tahu jawabannya, tidak?",
  ui_story_5024_50241601_132_dialog_content = "Kambing!",
  ui_story_5024_50241601_133_dialog_content = "Hah? Kok bisa?",
  ui_story_5024_50241601_134_dialog_content = "Karena kambing belum punya tanduk saat lahir… Sepasang tanduknya baru akan tumbuh saat mereka beranjak dewasa…",
  ui_story_5024_50241601_135_dialog_content = "Lalu, saat marah, ia akan mengamuk sampai satu tanduknya patah!",
  ui_story_5024_50241601_136_dialog_content = "… Mbeeek!",
  ui_story_5024_50241601_137_dialog_content = "Begitukah? Terima kasih atas penjelasannya…",
  ui_story_5024_50241601_138_dialog_content = "Takdir telah menuntun kita ke Manor of Truth…",
  ui_story_5024_50241601_139_dialog_content = "Semua hal baik tetap saja akan berakhir… Kita…",
  ui_story_5024_50241601_139X1_dialog_content = "Cukup sudah bicaranya.",
  ui_story_5024_50241601_139X2_dialog_content = "Lenore, bawa PlayerName kembali.",
  ui_story_5024_50241601_139X3_dialog_content = "Baik.",
  ui_story_5024_50241601_140_dialog_content = "Aku… Kita… Sampai jumpa lagi!",
  ui_story_5024_50241601_141_dialog_content = "<color=#e8d9bb>*Halaman buku dibalik*</color>",
  ui_story_5024_50241601_142_dialog_content = "Sebuah drama akan segera dipentaskan di Wonderland Theater.",
  ui_story_5024_50241601_143_dialog_content = "Seorang genius tak dikenal berhasil memperoleh kebijaksanaan sejati.",
  ui_story_5024_50241601_144_dialog_content = "Tak seharusnya itu terjadi. Hal itu jadi sumber dengki.",
  ui_story_5024_50241601_145_dialog_content = "\"Hukuman pun dijatuhkan oleh ■■, sebelum pertunjukan berakhir.\"",
  ui_story_5024_50241601_146_dialog_content = "Lady Victoria, aku tak bermaksud menyela, tapi sudah saatnya semua lampu dimatikan.",
  ui_story_5024_50241601_147_dialog_content = "Aku tahu. Selamat malam.",
  ui_story_5024_50241601_148_dialog_content = "Hmm? Kau sedang membaca Bloody Bible?",
  ui_story_5024_50241601_149_dialog_content = "Semoga Truth memberkatimu! Apakah aku cukup beruntung bisa mendengar ramalan baru?",
  ui_story_5024_50241601_150_dialog_content = "Hahah… Tak ada ramalan baru. Aku hanya membaca-baca saja…",
  ui_story_5024_50241601_151_dialog_content = "… Sebuah kisah yang terjadi setahun lalu dalam Bloody Bible.",
  ui_story_5024_50241601_152_dialog_content = "Kisah?",
  ui_story_5024_50241601_153_dialog_content = "Ya…",
  ui_story_5024_50241601_154_dialog_content = "Kalau mau, mari membacanya bersamaku, Faust.",
  ui_story_5024_50241601_155_dialog_content = "Dengan senang hati.",
  ui_story_5024_50241601_156_dialog_content = "Sebuah drama akan segera dipentaskan di Wonderland Theater.",
  ui_story_5024_50241601_157_dialog_content = "Seorang genius tak dikenal berhasil memperoleh kebijaksanaan sejati.",
  ui_story_5024_50241601_158_dialog_content = "Tak seharusnya itu terjadi. Hal itu jadi sumber dengki.",
  ui_story_5024_50241601_159_dialog_content = "\"Hukuman pun dijatuhkan oleh ■■, sebelum pertunjukan berakhir.\"",
  ui_story_5024_50241601_160_dialog_content = "Orang yang suka pamer di atas panggung…",
  ui_story_5024_50241601_161_dialog_content = "Selamanya akan tinggal di sana sebagai boneka.",
  ui_story_5024_50241601_162_dialog_content = "Setelah drama dan semua kehidupan berakhir.",
  ui_story_5024_50241601_163_dialog_content = "Biarlah takdir yang tak terduga menghapus semua jejak…",
  ui_story_5024_50241601_164_dialog_content = "Prolognya cukup panjang… Ini kisah tentang Wonderland Theater, ya?",
  ui_story_5024_50241601_165_dialog_content = "Benar. Sebenarnya, tokoh utama dalam kisah ini bukan orang asing bagi kita.",
  ui_story_5024_50241601_166_dialog_content = "Sungguh? Tokoh utamanya… PlayerName?",
  ui_story_5024_50241601_167_dialog_content = "… Heheh. Sabarlah dan teruskan membaca saja.",
  ui_story_5024_50241601_168_dialog_content = "Awal",
  ui_story_5024_50241601_169_dialog_content = "Seorang gadis yang belum bisa berjalan mengabaikan perintah ibunya.",
  ui_story_5024_50241601_170_dialog_content = "Seorang anak naik ke panggung untuk menghadapi kutukan yang akan mengubahnya menjadi boneka.",
  ui_story_5024_50241601_171_dialog_content = "\"■■ tak menunjukkan belas kasih, tapi nyawanya terselamatkan.\"",
  ui_story_5024_50241601_172_dialog_content = "Jalanan",
  ui_story_5024_50241601_173_dialog_content = [[
"Di suatu sudut yang tak terjamah dari aturan dan hukum, 
suatu keajaiban yang sirna sebelum waktunya menanti untuk bisa kembali."]],
  ui_story_5024_50241601_174_dialog_content = "Seorang ibu bergegas ke sana, mengejar sesuatu yang sudah lama hilang darinya.",
  ui_story_5024_50241601_175_dialog_content = "Walaupun nyawanya sendiri harus jadi taruhannya.",
  ui_story_5024_50241601_176_dialog_content = "Persimpangan",
  ui_story_5024_50241601_177_dialog_content = "Upaya untuk kembali itu gagal, tapi semuanya belum berakhir. Hingga akhirnya berhasil sepenuhnya.",
  ui_story_5024_50241601_178_dialog_content = "Di dalam Theater, satu-satunya keyakinan sejati melayang-layang dalam keheningan yang bagaikan maut.",
  ui_story_5024_50241601_179_dialog_content = "Ia menanti, sambil menanggung beban kehidupan.",
  ui_story_5024_50241601_180_dialog_content = "Menanti seorang gadis bertubuh boneka yang mencari ibunya…",
  ui_story_5024_50241601_181_dialog_content = "Aku paham… Ini ramalan tentang si gadis boneka dan ibunya…",
  ui_story_5024_50241601_182_dialog_content = "Dia datang ke Manor of Truth bersama PlayerName…",
  ui_story_5024_50241601_183_dialog_content = "Kau sudah memprediksi kedatangan mereka?",
  ui_story_5024_50241601_184_dialog_content = "Aku melihat sebuah kisah yang bisa dipahami.",
  ui_story_5024_50241601_185_dialog_content = "Dua jalan yang saling mengarah satu sama lain pada akhirnya akan bertemu.",
  ui_story_5024_50241601_186_dialog_content = "Aku berdiri di Persimpangan, menyaksikan sang ibu menuntun anak gadis kesayangannya kembali ke awal.",
  ui_story_5024_50241601_187_dialog_content = "Tamat"
}
return config
